[41774] = { ["id"] = 41774, ["name"] = "The Rival Lords of Fire", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 8125, ["storyline"] = { 41774 }, ["series"] = { 41773, 41888, 41934 }, ["description"] = "You stand before the true Lord of the Firelands, mortal. This land is mine by right, claimed from the ashes of Ragnaros himself. However, there are still some who foolishly oppose my reign. I would take great pleasure in destroying their worthless souls, but I will not honor them with death by my hands. They must be humiliated for their insolence, and there is nothing more humiliating than being slain by a mere mortal. Amuse me shaman. Prove your worth and destroy my rivals!", ["objectivesText"] = "Return to Lord Smolderon with Garixxia's Smoldering Heart and the Core of Molten Rage.", ["rewardGold"] = 404400, ["rewardXP"] = 7675, ["rewardItems"] = { 136535, 136536 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 8125 } }, ["questType"] = "standard" },
[44498] = { ["id"] = 44498, ["name"] = "Winterhoof Cleansing", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 44498 }, ["series"] = { 20441, 24440, 24441, 24456, 24457, 24523, 24524, 24540, 24550 }, ["description"] = "I have crafted the totem to cleanse the Winterhoof Water Well. Now, you must take it to the well and perform a cleansing ritual. The well is to the southeast, but be warned: whoever did this may still be there, laying in wait. This may prove very dangerous, <name>. Be careful...but do not let the defilers of our well escape.", ["objectivesText"] = "Use the Winterhoof Cleansing Totem at the Winterhoof Water Well.", ["rewardXP"] = 200, ["rewardItems"] = { 5411, 57205, 57221 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[45043] = { ["id"] = 45043, ["name"] = "The Glowing Bloodthistle Petal", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 45043 }, ["series"] = { 44781, 44782, 44821, 45030, 45033, 45037, 45045, 45050, 45052, 45053, 45054, 45059, 45060, 45061, 46765, 47000 }, ["description"] = "<It is exceedingly rare to find bloodthistle outside of Blood Elf lands, especially a petal as fresh as this one.> <Perhaps the Legion merely claimed it off of a fallen combatant, but that seems far too convenient an explanation.> <You figure the Kirin Tor in Dalaran would likely be interested in this.>", ["objectivesText"] = "Find someone interested in the Glowing Bloodthistle Petal. You suspect that the Kirin Tor in Dalaran are a good place to start.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 142376 } },
[45167] = { ["id"] = 45167, ["name"] = "REUSE ME", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 7588, ["storyline"] = { 45167 }, ["description"] = "<name>, we will need to bolster our army by any means necessary to have any hope of driving back the legion. The kvaldir are cursed beyond redemption, but they are fierce warriors and are a resource we should not overlook. They are bound to obey whomever posesses Helya's Horn . You must obtain it. Her so-called helarjar were tasked with guarding it. You will have to take it from them.", ["objectivesText"] = "Find Helya's Horn .", ["rewardGold"] = 202200, ["rewardXP"] = 6140, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142315, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7588 } }, ["questType"] = "standard" },
[48395] = { ["id"] = 48395, ["name"] = "Whispers from the Shadows", ["level"] = 45, ["requiredLevel"] = 45, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7503, ["storyline"] = { 48395 }, ["description"] = "Hero, we have a problem. The ancient Necrodark cult has returned. When Dargrul was the Underking he would quell these cultists whenever they appeared, keeping them from exploring the vault of Neltharion. But now, with Dargrul gone, they are sieging the vault in force. We must stop them before they find what they are looking for.", ["objectivesText"] = "Help Navarrogg defeat the Necrodark.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7503 } }, ["questType"] = "standard" },
[49590] = { ["id"] = 49590, ["name"] = "REUSE ME", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 49590 }, ["description"] = "As you peer from one gem to the next, you realize that the shrine appears to be fine, yet no power radiates from it. Pulling out your jewelcrafting tools, you begin to inspect the central gem and realize that there is in fact a flaw. A small crack near the base of it that permeates through the gem towards the back. You reference your notes on the shrine and discover that this gem came from a \"golden sanctuary\". Perhaps someone back at the Explorer's League Campsite will know what this means.", ["objectivesText"] = "Travel to the Reliquary Camp and ask around about the \"golden sanctuary\". Then find a replacement gem once you learn of its location.", ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
[49591] = { ["id"] = 49591, ["name"] = "REUSE ME", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 49591 }, ["description"] = "Surveying the shrine, you believe that the sandy winds in this area have worn down the embedded gems, producing odd shapes and cracks in some. Looking at your notes, the earthen mentions coming across dunes sprinkled with orange gems. He said it reminded him of the soft sunlight in this area. Samuel added his own note saying he believes the location of these gems to be south of the shrine's location.", ["objectivesText"] = "Go to the location on your map where you believe these gems to be and recover $1oa of them. Polish and shape them as you find them.", ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49592] = { ["id"] = 49592, ["name"] = "REUSE ME", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 49592 }, ["description"] = "Upon inspection of the shrine, you notice something... familiar. The cut of the gems looks like a primitive or simple version of the way you've learned to cut rubellites. It's clear though that time has had its way with these gems, some eroded and chipped in places. Repairing this shrine may be as simple as replacing the old gems with newer ones of the same type and cut.", ["objectivesText"] = "Cut $1oa Insightful Rubellites and replace the old ones with the new.", ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49593] = { ["id"] = 49593, ["name"] = "REUSE ME", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 49593 }, ["description"] = "I once viisted Kul Tiras. Da humans dere not be too friendly to us Zandalari. However one of da shrines be dere, in Tiragarde Sound. Dat place have da most humans of all dat land. Ya need to be watchin' your back out dere, <name>. I'll mark da location of it on your map for ya. And let's be hoping dem humans didn't mess wit it.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Tirigarde Sound. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49594] = { ["id"] = 49594, ["name"] = "REUSE ME", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 49594 }, ["description"] = "Da next shrine be a in a place dey call Drustvar. From what I be hearin', dat place is full of witches. Dey use deir magics to bring tings ta life. But lookin at da map and where I tink dis shrine be, ya may not be needing to run into any of dem. It's pretty close ta da Smuggler's Cove. I'd make ya way dere and den find da shrine. I'll mark ya map for ya where I tink it is.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Drustvar. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49595] = { ["id"] = 49595, ["name"] = "REUSE ME", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 49595 }, ["description"] = "Da last shrine in Kul Tiras be in a green place dey call Stormsong Valley. Da humans dere probably won't be givin' ya too much trouble. But da shrine be pretty dead center in da land, so ya probably gonna have ta do some travelin'. I'll mark it on ya map for ya.", ["objectivesText"] = "Travel to the location marked on your map and investigate the shrine in Stormsong Valley. Do what you can to repair the shrine, should the need arise.", ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[49596] = { ["id"] = 49596, ["name"] = "REUSE ME", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "horde", ["requiredProfessions"] = { "jewelcrafting" }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 49596 }, ["description"] = "As you peer at the rock altar in front of you, you can't help but revel at the construction of it. Seamlessly constructed with azure jewels placed just so in a radial pattern, collapsing towards a single point. A single, empty point. An absence you assume to be a mistake. Quickly surveying the area for something that might fit there, you find nothing. However, someone who had not been there before has shown up. Perhaps he might know the whereabouts of the shrine's missing piece.", ["objectivesText"] = "Speak with \"Slippery Salton\" and learn what you can about the missing centerpiece.", ["rewardGold"] = 996000, ["rewardXP"] = 200, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "dungeon" },
