[58211] = { ["id"] = 58211, ["name"] = "Pumped Up", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58211 }, ["description"] = "When this necropolis collapsed, plenty of its parts got submerged in the riverbed flowing just outside. I hope you're really dedicated to fixing this place, because we're gonna dredge those parts back up! Take this pump. If you find any places bubbling in that sludge, that's a good sign parts will be there! Just be careful with whatever you pull up! You could face some resistance.", ["objectivesText"] = "Collect 15 Salvaged Gear by using the Sludge Pump near bubbling sludge. Progress: Have you recovered anything useful?", ["rewardGold"] = 257400, ["rewardItems"] = { 173881, 173892, 181501, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181652, 181653, 181654, 181656, 181657, 181659, 181675, 181676, 181677, 181681, 181689, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
