[58260] = { ["id"] = 58260, ["name"] = "Queens And Future Kings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 58260 }, ["description"] = "A swarm of marrowbore queens have been laying eggs atop the ruins of our house. We may be able to use this to our advantage. With Twigin's help, eliminate the queens and recover larvae from the eggs. I have a plan for the larvae that may allow us to use the marrowbore to our advantage.", ["objectivesText"] = "Slay 1 marrowbore queens , and collect 5 marrowbore larvae. Progress: It's dirty work, but we need those larvae.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173942, 181501, 181502, 181503, 181507, 181625, 181626, 181645, 181647, 181649, 181650, 181652, 181653, 181654, 181661, 181662, 181663, 181679, 181680, 181682, 181694, 184194, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58327] = { ["id"] = 58327, ["name"] = "Snacks for Stonehead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 58327 }, ["description"] = "< Stonehead has amassed a wide variety of half-eaten oddities. He'd certainly appreciate you bringing some new, creative snacks for him to try.>", ["objectivesText"] = "Collect a sampling of snacks from across the Ember Ward for Stonehead . Progress: Tummy rumbly...", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 175826, 175828, 175829, 175840 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157199, ["x"] = 0.39, ["y"] = 0.66 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.39, ["y"] = 0.66 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
