[58625] = { ["id"] = 58625, ["name"] = "Connecting the Dots", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 58625 }, ["description"] = "The old baron for the House of the Chosen? Ah, yes! I do think I remember seeing him! An angry soul, but very good at fighting. He went off to meet with some member of the House of Rituals. There were a few of his guards with him. While it's been quite some time since he passed this way, you may be able to find some signs of where he went towards the old footpath up the mountains.", ["objectivesText"] = "Search the Forgotten Wounds for the previous baron.", ["rewardGold"] = 289300, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[58664] = { ["id"] = 58664, ["name"] = "Ultimate Makeover", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["storyline"] = { 58664 }, ["description"] = "We now control the Apparatus of Abominable Construction! We can use it to create new constructs to contain worthy souls. Emeni is the best choice to be first. Her combat skills are unmatched, and you may need her to help secure the Stitchyard. You will assist me in rebuilding Emeni's construct.", ["objectivesText"] = "Help Rathan rebuild Emeni's Construct.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[58769] = { ["id"] = 58769, ["name"] = "REUSE ME", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 58769 }, ["description"] = "Suddenly the lack of fae and souls makes much more sense. These vile creatures must have taken them as they took my husband. But I will get them back. If you are our new champion then you will help me for the good of Ardenweald . <Thiernas snorts.> Death did not part us. I will not be torn from him now.", ["objectivesText"] = "Ride with Thiernax after the Drust.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 71083, 128823, 133803, 133804, 142342, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841, 190456, 198048, 200453, 204075, 204743, 204744, 204747, 204748, 204750, 204752, 204754, 204758, 204759, 204761, 204766, 204769, 204774, 204780, 204787, 204896, 204898 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[58908] = { ["id"] = 58908, ["name"] = "Finding Your Way", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["series"] = { 59583 }, ["description"] = "Stormwind has a lot to offer adventurers like us, but it's far too big to explore on foot. The captain has arranged for you to receive a mount to help you get around. She said to speak with Curly at the stables in Old Town... but I can't seem to remember the way there. Have no worries, <name>! All we need to do is ask a guard for directions. If you ever need help finding something, the city guards will show you where to go. Let's ask a nearby guard for directions to the stable master in Old Town!", ["objectivesText"] = "Speak with Curly at the stables in Old Town. Progress: Welcome to the stables, <class>. I've been expecting you.", ["rewardXP"] = 505, ["rewardItems"] = { 2411, 25470, 25474 }, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163095, ["x"] = 0.713818, ["y"] = 0.739636 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 163007, ["x"] = 0.774, ["y"] = 0.671 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.713818, ["y"] = 0.739636 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 49, ["flags"] = 0 } } },
[58910] = { ["id"] = 58910, ["name"] = "What's Your Specialty?", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["requiredClasses"] = { 11 }, ["requiredRaces"] = { 4, 22 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 59254, 59350, 59583, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "Hey, <name>! Have you decided on a combat specialization yet? Since you're a <class>, you already know about the different classes available to adventurers. But did you know that there are also areas of specialization within each class? Choosing a specialization is an important decision. Your specialty determines your combat role in a party, as well as the kinds of weapons and abilities that you will use. Let's go speak with Mithlos Falconbriar to learn more about specializations!", ["objectivesText"] = "Speak with Mithlos Falconbriar to learn about combat specializations. Progress: Greetings. Have you come to learn about combat specializations?", ["rewardXP"] = 505, ["rewardItems"] = { 25470, 25474, 175165, 175166, 246462 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 164962, ["x"] = 0.792, ["y"] = 0.697 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.792, ["y"] = 0.697 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 52, ["flags"] = 0 } } },
[58911] = { ["id"] = 58911, ["name"] = "Home Is Where the Hearth Is", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 54933, 54951, 54952, 55122, 55173, 55174, 55184, 55186, 55193, 55194, 55196, 55639, 55763, 55764, 55879, 55881, 55882, 55965, 55981, 55988, 55989, 55990, 55991, 55992, 56034, 56344, 56775, 56839, 58208, 58209, 58908, 58909, 58910, 58911, 58914, 58915, 58917, 58923, 58933, 58946, 58953, 58960, 58962, 59002, 59254, 59339, 59342, 59347, 59349, 59350, 59352, 59354, 59355, 59356, 59583, 59586, 59587, 59588, 59589, 59590, 59591, 59592, 59593, 59594, 60168, 85678, 87547, 87555, 87560, 87562 }, ["description"] = "I don't know about you, but all this running around has got me thirsty! Why don't we head over to the Pig and Whistle Tavern and rest our legs over some cool pints of moonberry juice? While we're there, speak with Meagan the innkeeper to make the Pig and Whistle Tavern your new home. That way, if you ever find yourself stranded without a flight master nearby, you can use your hearthstone to return to the inn. Not only is it faster than a gryphon, but you'll save a few copper in the process!", ["objectivesText"] = "Speak with Meagan Tillman to make the Pig and Whistle Tavern your home. Progress: How can I help you today, <class>? Are you looking for a place to stay?", ["rewardGold"] = 200, ["rewardXP"] = 505, ["rewardItems"] = { 6948 }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 44237, ["x"] = 0.755333, ["y"] = 0.540667 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.755333, ["y"] = 0.540667 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 926, ["name"] = "The Missing Expedition", ["orderIndex"] = 53, ["flags"] = 0 } } },
[58912] = { ["id"] = 58912, ["name"] = "An Urgent Meeting", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 58912 }, ["description"] = "I've been looking for you all over Stormwind, <name>. The captain has delivered her report to the king. It appears that Stormwind requires your service yet again. The leaders of the Alliance have gathered together for a meeting at Stormwind Keep, and your presence has been requested by King Wrynn himself. I was instructed to find you and deliver the message without delay. It has been an honor serving with you, <name>. May the Light bless you on your journey.", ["objectivesText"] = "Speak with Captain Garrick at Stormwind Keep.", ["rewardXP"] = 125, ["starts"] = { { ["mapID"] = 84, ["npcID"] = 163211, ["x"] = 0.754, ["y"] = 0.543333 } }, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 163219, ["x"] = 0.85, ["y"] = 0.324 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.754, ["y"] = 0.543333 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
