[59740] = { ["id"] = 59740, ["name"] = "Repair and Restore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 59740 }, ["description"] = "You've already attuned several mirrors without incident. I do believe it's time you try your hand at repairing them instead. It's quite easy once you've found the fragments, but there are a few things of note to keep in mind. Repaired mirrors are fragile and unpredictable. They often break with a single use, and it's never a guarantee that using one will translocate you somewhere safe. Here's a few shards to get you started. Restore the mirror to working order and see where it leads.", ["objectivesText"] = "Repair the Broken Mirror and reap the rewards. Progress: I have complete faith in your abilities.", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["rewardItems"] = { 181363, 182112 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
