[59747] = { ["id"] = 59747, ["name"] = "A Lost Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 59747 }, ["description"] = "Many of us struggled to free ourselves when Gharmal imprisoned our souls here, but none more than Bacilia. She was a great champion, but the confinement drove her mad and darkness consumed her soul. Though we tried to reason with her over the course of eons, it is clear that there is no coming back for her. Please end her misery.", ["objectivesText"] = "Bacilia the Lost slain. Progress: Have you completed this task?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 181478, 181549, 181552, 181646, 181648, 181650, 181743, 184149, 184379, 184380, 184763, 184764 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
