[59772] = { ["id"] = 59772, ["name"] = "Research Ruination", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59772 }, ["description"] = "The Cult of the Damned continue their work within the halls of Aldur'thar. Infiltrate their chambers and destroy their research. It may not stop them, but it will buy us valuable time.", ["objectivesText"] = "Destroy 5 Research Notes at Aldur'thar. Progress: Making progress?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59782] = { ["id"] = 59782, ["name"] = "The Deathspeaker's Devout", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59782 }, ["description"] = "Though Deathspeaker Kharos has long since been slain, the cultists in the nearby mountains continue his nefarious work. Clearly emboldened by the Scourge's resurgence and the rift in the sky, they once again kidnap our crusaders and perform their abhorrent alchemical experiments. Go forth and purge those fanatics from their camp.", ["objectivesText"] = "Kill 6 Dark Ritualists and 6 Dark Zealots at Deathspeaker's Watch.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59783] = { ["id"] = 59783, ["name"] = "Cultist Captors", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59783 }, ["description"] = "Those damned cultists are relentless! They caught us off guard and managed to drag a few of our crusaders back to their camp. Light only knows what they're doing to them up there... Word is you're quite capable of holding your own. Our numbers are stretched thin enough as it is... if you could rescue the captives, we'd be in your debt. You can find the cultists lurking up in their mountain camp.", ["objectivesText"] = "Retrieve the Interrogator's Key from Interrogator Grell. Rescue 8 Captive Aspirants at Deathspeaker's Watch. Progress: What news have you?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 181497 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 168880, ["x"] = 0.66, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.66, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
