[59838] = { ["id"] = 59838, ["name"] = "Scourge War Machines", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59838 }, ["description"] = "The Scourge's war machines make it exceedingly difficult for us to gain ground. They must be our top priority. Though they are well protected, we must destroy them if we are to clear a path for our ground forces and grant them an opportunity to strike. Plant these charges underneath the war machines and then clear the area.", ["objectivesText"] = "Destroy 5 Scourge War Machines in The Conflagration.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 182313 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59839] = { ["id"] = 59839, ["name"] = "WARNING: This is Only a Test!", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59839 }, ["description"] = "Where some see a problem, I see an opportunity. What this Scourge fiasco calls for is a creative solution! Behold--my \"secret weapon\"! Controlled by none other than my Carefully Constructed Control Device, or C.C.C.D. for short! Hmm, that name might need a little work. You're the first to see it, so that means you'll be the first to test it. But don't worry, I'm pretty sure it's safe. Good luck!", ["objectivesText"] = "Successfully complete the testing of Fizzix Blastbolt 's \"Secret Weapon\" at Deathspeaker's Watch. Progress: So, how's it goin'?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 172905, ["x"] = 0.67, ["y"] = 0.262667 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 172905, ["x"] = 0.67, ["y"] = 0.262667 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.262667 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59840] = { ["id"] = 59840, ["name"] = "Divine Gratitude", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 59840 }, ["description"] = "Many thanks for restoring my power and vigor. My path will now lead me back to my people, but it is only right that you are rewarded for your efforts.", ["objectivesText"] = "Accept the boon offered by the deity.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[59847] = { ["id"] = 59847, ["name"] = "Defending the Rampart", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59847 }, ["description"] = "The Scourge are assaulting our outpost! We must defend it at all costs! Slay as many of the fiends as you can!", ["objectivesText"] = "Defend against the Scourge attack atop the Ironwall Rampart.", ["rewardGold"] = 248040, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
