[59863] = { ["id"] = 59863, ["name"] = "Combat Nullifier 07-X", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59863 }, ["description"] = "While everyone is busy fending off our enemies with swords and magic, how about we try something different. Behold, my latest invention--the Combat Nullifier 07-X! With this device, no enemy is truly your enemy any longer! Now, I haven't quite worked out the exact energy modulator calculations, but I am certain it works. Mostly. For now, we'll need to \"borrow\" some energy from our enemies in order to operate it. Go ahead. Charge it up and give it a whirl!", ["objectivesText"] = "Charge the Power Containment Module to Blast 5 enemies with the Combat Nullifier 07-X at Sindragosa's Fall. Progress: How's it going?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 173124, ["x"] = 0.676, ["y"] = 0.328 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 173124, ["x"] = 0.676, ["y"] = 0.328 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.328 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59878] = { ["id"] = 59878, ["name"] = "Too Many Whelps", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 59878 }, ["description"] = "We cannot hope to hold this ground if frostwyrms strafe the skies above us. Cultists have been raising whelps from the dead nearby. The more of them we eliminate, the fewer monstrosities to breath deadly ice upon our forces. Put an end to their efforts.", ["objectivesText"] = "Kill 4 Wyrm Reanimators and 12 Frostbrood Whelps at Sindragosa's Fall.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[59882] = { ["id"] = 59882, ["name"] = "Sure Bet", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1536, ["storyline"] = { 57316, 58068, 58088, 58090, 58575, 58900, 58947, 59203, 59750, 59781, 59800, 59826, 59827, 59828, 59837, 59879, 59882 }, ["description"] = "You appear to have great profit potential. There are many interested parties willing to bet upon your performance in the Theater of Pain. Go now, Louison will arrange your appearance.", ["objectivesText"] = "Meet with Louison", ["rewardGold"] = 30900, ["rewardXP"] = 175, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["questLines"] = { { ["id"] = 1156, ["name"] = "Theater of Pain", ["orderIndex"] = 11, ["flags"] = 0 } } },
