[59986] = { ["id"] = 59986, ["name"] = "Wide Worlds of Catalysts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 59986 }, ["description"] = "Catalysts come in different forms, for now we shall introduce you to two of them. Speed catalysts can speed up the restoration process. This can obviously be helpful for managing how many souls we can recover. Quality catalysts improve the quality of the material goods that a spirit might offer upon their restoration. Return to me when you have found an example of each. I will be eager to see whether your small little eyes are sharp enough to spot them.", ["objectivesText"] = "Identify the different types of Catalysts", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
