[60096] = { ["id"] = 60096, ["name"] = "Wrath of the Lich King: To Northrend!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 84, ["storyline"] = { 28709, 39204, 39207, 49551, 49552, 49553, 49554, 49555, 60096, 60962 }, ["description"] = "The Lich King stirs in the north. An undead army follows his command, marching across Northrend and spreading blight wherever they tread. We need you to stop them, <name>.", ["objectivesText"] = "Take a ship to Northrend. You can board the ship to Borean Tundra in Stormwind Harbor, or the ship to Howling Fjord in Wetlands.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5579, ["name"] = "Wrath of the Lich King Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
