[60120] = { ["id"] = 60120, ["name"] = "Burning Crusade: To Outland!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 84, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["description"] = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the draenei. Adventurers of the Alliance are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion. Travel to the Blasted Lands, and pass through the Dark Portal.", ["objectivesText"] = "Go through the Dark Portal in Blasted Lands. The Honor Hold Mage in the Mage District can help you get there.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60123] = { ["id"] = 60123, ["name"] = "Burning Crusade: To Outland!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 85, ["storyline"] = { 28705, 39180, 39182, 39196, 39198, 39201, 49532, 60123, 60961 }, ["description"] = "The Burning Legion - an uncountably vast army of demons - has assaulted Outland, the tattered homeworld of the orcs. Adventurers of the Horde are needed to protect what remains of Outland from utter annihilation at the hands of this demonic invasion. Travel to the Blasted Lands, and pass through the Dark Portal.", ["objectivesText"] = "Go through the Dark Portal in Blasted Lands. The Thrallmar Mage in the Orgrimmar Portal Room can help you get there.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5576, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60125] = { ["id"] = 60125, ["name"] = "Mists of Pandaria: To Pandaria!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 60125, 60965 }, ["series"] = { 29547, 29548, 31732, 31733, 49556 }, ["description"] = "Please come to Stormwind Keep immediately for a briefing with King Varian Wrynn. We have received word of a conflict in the seas to the south, and we need the help of an experienced <class> to assist in the investigation.", ["objectivesText"] = "Report to Rell Nightwind in Stormwind.", ["ends"] = { { ["mapID"] = 84, ["npcID"] = 55789, ["x"] = 0.791, ["y"] = 0.396 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.791, ["y"] = 0.396 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard", ["db2PoiUiMapID"] = 84, ["questLines"] = { { ["id"] = 5583, ["name"] = "Mists of Pandaria Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60126] = { ["id"] = 60126, ["name"] = "Mists of Pandaria: To Pandaria!", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60126, 60964 }, ["series"] = { 29611, 29612, 29690, 31765, 31766, 31767, 31768, 31769, 31853, 49538 }, ["description"] = "You are hereby ordered to present yourself at Grommash Hold immediately. We have received word of a new, resource-rich continent in the south, and we intend to send you and a small contingent of soldiers to claim it for the Horde.", ["objectivesText"] = "Report to Grommash Hold in Orgrimmar.", ["ends"] = { { ["mapID"] = 85, ["npcID"] = 54870, ["x"] = 0.485, ["y"] = 0.707 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.707 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5582, ["name"] = "Mists of Pandaria Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
[60132] = { ["id"] = 60132, ["name"] = "Constellan Writs and Stygia", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 60132 }, ["description"] = "There is much to discover within the Maw , and much of it can be turned to future profit. Information is an investment. There are many objects that I find interesting in this place, and I am happy to barter with you should you find any. Find one and we shall open negotiations.", ["rewardItems"] = { 175769 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60153] = { ["id"] = 60153, ["name"] = "Into the Unknown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 60153 }, ["description"] = "Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181430, 181457, 181458, 181459, 181477, 181479, 181541, 182469, 182605, 183132, 183167, 183466, 183473, 183479, 183482, 183485, 183487, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60155] = { ["id"] = 60155, ["name"] = "To Open the Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60155 }, ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60172] = { ["id"] = 60172, ["name"] = "This Quest is Temporary", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 60172 }, ["description"] = "Dropping out of the sky is a key part of this playtest, so enjoy the ride.", ["objectivesText"] = "Speak with Draedan to enter the Maw.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[60175] = { ["id"] = 60175, ["name"] = "A Taste of Tirna Noch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60175 }, ["description"] = "I'm a simple mushroom with simple pleasures, <name>. And what's simpler than a nice, hearty meal? Don't look so surprised. I need to eat just like anyone else! How else do you think I grew so big? Nice, tasty compost, that's how! Back in my day, I had the pick of Ardenweald for where to feed. Now, not so much. I've had a hankering for some of the loam that used to be around Tirna Noch. I haven't had shoots out there in a long time. Could you bring me some?", ["objectivesText"] = "Collect 6 Leafy Loam in Tirna Noch. Progress: Tirna Noch is a beautiful tree located east of Hibernal Hollow. You can't miss it.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 178215, 179513, 179517, 179532, 179562, 181405, 181406, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181477, 181479, 181511, 181541, 182335, 182466, 182621, 183467, 183473, 183478, 183490, 183505, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60188] = { ["id"] = 60188, ["name"] = "Go Beyond!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 60188 }, ["description"] = "Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 178464, 178465, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181420, 181421, 181422, 181423, 181424, 181425, 181427, 181428, 181429, 181430, 181457, 181459, 181461, 181477, 181479, 181541, 184381, 184382, 184383, 184384, 194371, 194372, 194376, 194393, 194416, 199461, 200960, 204076, 204586, 204594, 204602, 204610, 210024, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[60211] = { ["id"] = 60211, ["name"] = "Spore Losers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["storyline"] = { 60211 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world" },
[60215] = { ["id"] = 60215, ["name"] = "Timely Gate Crashers", ["level"] = 30, ["requiredLevel"] = 30, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 440, ["mapID"] = 71, ["storyline"] = { 60215 }, ["description"] = "Did you see that giant mechanical monstrosity just walking around in the dunes outside? How about the icky shadowy Sha of Anger ? Or that big frost giant in the north? Yeah, they aren't native to this area. They tell me the timeways are screwy around this time of year. They have asked me to organize a clean-up crew. Would you be up to the challenge? If you like this challenge, I have another for you as well.", ["objectivesText"] = "Defeat Doomwalker , Sha of Anger , and Archavon the Stone Watcher in Tanaris. Progress: How's it going?", ["rewardGold"] = 1366400, ["rewardXP"] = 8230, ["rewardItems"] = { 44083, 87771, 185907, 208572, 232877, 233014 }, ["starts"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["ends"] = { { ["mapID"] = 71, ["npcID"] = 223882, ["x"] = 0.622, ["y"] = 0.516 } }, ["coords"] = { ["mapID"] = 71, ["source"] = "quest_giver", ["x"] = 0.622, ["y"] = 0.516 }, ["mapCandidates"] = { ["npc"] = { 71 }, ["zone"] = { 440 } }, ["questType"] = "standard", ["db2LabelIDs"] = { 4063 }, ["db2QuestSortName"] = "Nightborne" },
