[60230] = { ["id"] = 60230, ["name"] = "More the Merrier", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60230 }, ["description"] = "News of our work here has spread, new souls have arrived seeking to join us! Take their requests for new construct bodies. We'll see if we can build them new constructs too!", ["objectivesText"] = "Take the construct requests from the souls present.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60231] = { ["id"] = 60231, ["name"] = "State of Decay", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60231 }, ["objectivesText"] = "Kill Slimed enemies or Players", ["rewardXP"] = 8165, ["rewardItems"] = { 177245 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "pvp", ["db2Objectives"] = { { ["text"] = "Kill Slimed enemies or Players", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 113, ["db2QuestInfoName"] = "PvP World Quest" },
[60236] = { ["id"] = 60236, ["name"] = "RSVP: Cryptkeeper Kassir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60236 }, ["description"] = "I would be most honored to attend Prince Renathal's Ember Court. I prefer to wear my official signet ring for such prestigious occasions. It was given to me by the Accuser herself when I was first charged with my duties. However, the Lord Chamberlain's goons have stolen it once more. They hide their ill-gotten gains inside of these crypts... But I have no idea which one houses my ring. It may take some time to find Atonement Crypt Keys, but any venthyr here in the halls could have one.", ["objectivesText"] = "Collect Atonement Crypt Keys from venthyr around the Halls of Atonement and open Atonement Crypts until you find the Lost Cryptkeeper's Ring . Progress: Desired objects tend to be in the last place we look, do they not? Perhaps we shall be fortunate this time.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172957, 176120, 177231, 178526, 180380, 180397, 184225 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163073, ["x"] = 0.702, ["y"] = 0.562 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.702, ["y"] = 0.562 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60237] = { ["id"] = 60237, ["name"] = "Old Stomping Grounds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60237 }, ["description"] = "Once, long ago, I journeyed to Ardenweald to assist in putting down a threat now long forgotten. I remember that while there, I saw small creatures taking tiny clusters of anima--animacones, the fae called them--and buried them under the soil. If those clusters are still there, we must gather them for ourselves! I should be able to unearth any of the animacones we encounter. Let's go hunt for them!", ["objectivesText"] = "Collect 15 Lost Animacones . Use Toothpick 's World Shaker to unearth them.", ["rewardXP"] = 8165, ["rewardItems"] = { 182488, 182497, 182506, 182515, 183043, 183744, 183755, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159212, ["x"] = 0.548, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60238] = { ["id"] = 60238, ["name"] = "A Gently Shaken Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["storyline"] = { 60238 }, ["rewardItems"] = { 21270, 21271, 128652, 128768, 139343, 151345, 162974, 172225, 178529, 178530, 187520, 192093, 210657, 218309, 244906 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[60239] = { ["id"] = 60239, ["name"] = "A Winter Veil Gift", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1637, ["storyline"] = { 60239 }, ["rewardItems"] = { 34426, 43504, 46740, 67443, 70938, 90892, 104319, 116761, 128653, 139341, 151350, 162644, 172224, 178528, 178533, 187561, 192094, 209871, 218311, 244908 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[60242] = { ["id"] = 60242, ["name"] = "Trading Favors: Necrotic Wake", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12916, ["storyline"] = { 60242 }, ["description"] = "We of the brokers place value on things that may seem strange to an outsider like yourself. Objects that are unusual or one-of-a-kind are things we may find more valuable than others. So let us make a deal, hm? Should you find yourself in possession of one such object, I will offer a trade for something you may find more valuable. I hear that the forces of Maldraxxus have made an attack on Bastion. Such things rarely happen without objects of power in tow, no?", ["objectivesText"] = "Obtain Nalthor's Phylactery Instructions from Nalthor the Rimebinder in the Necrotic Wake. Progress: Have you found any objects of interest?", ["rewardItems"] = { 178577, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12916 } }, ["questType"] = "dungeon" },
[60243] = { ["id"] = 60243, ["name"] = "Trading Favors: Sanguine Depths", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12842, ["storyline"] = { 60243 }, ["description"] = "The generals of Revendreth are outfitted with only the finest arms and armor, procured by Sire Denathrius in his unquenchable appetite for power. In terms of profitable trades and exchanges, he has been a shrewd partner in trade to us. It would please me greatly to see the return of some relics that were traded in a way that benefited him far more than us. There are few things more insulting to my kind.", ["objectivesText"] = "Obtain a Medallion of Orientation from General Kaal in the Sanguine Depths. Progress: What have you brought before me?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178584, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12842 } }, ["questType"] = "dungeon" },
[60244] = { ["id"] = 60244, ["name"] = "Trading Favors: Halls of Atonement", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12831, ["storyline"] = { 60244 }, ["description"] = "The mechanisms by which each land of the Shadowlands operates are quite intriguing. Yet, I have always held a particular fascination with the venthyr of Revendreth. How they siphon souls of their sins, storing them in strange stones, and dredge up minions from the muck that surrounds them -- it is all quite novel. They keep their secrets close at hand, however, and will not willingly part with information. I offer trades for any of their tomes you might come into possession of.", ["objectivesText"] = "Obtain the Tome of Dredger Alchemy from Lord Chamberlain in the Halls of Atonement. Progress: Have you found something of interest?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178583, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12831 } }, ["questType"] = "dungeon" },
[60245] = { ["id"] = 60245, ["name"] = "Trading Favors: De Other Side", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60245 }, ["description"] = "Mueh'zala is an ancient and primitive creature that commands a place known as De Other Side. Little is known about this land, as we are not permitted to visit. We have sent many offers of trade, yet there has never been a reply. A pity, as the few that have escaped Mueh'zala's clutches claim his domain to be a place of many oddities. We would never ask you to venture into such danger. There is, however, a standing offer of trade for things procured from Mueh'zala's grasp.", ["objectivesText"] = "Obtain a Golden Death Mask from Mueh'zala in De Other Side. Progress: You have the stench of death about you.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178582, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "dungeon" },
[60246] = { ["id"] = 60246, ["name"] = "Trading Favors: Tirna Scithe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13334, ["storyline"] = { 60246 }, ["description"] = "The gorm devour anything in their path when left unchecked. We have sold more than a few of them as both pets and weapons. You do not want to see what a world looks like when they are introduced to it and allowed to infest. Or perhaps, mhm, you do? For some, that is entertainment. It is difficult for us to explore Ardenweald with things as they are at this time. A fat, healthy gorm larva would fetch a fine price on the markets. I trust my meaning is understood?", ["objectivesText"] = "Obtain an Engorged Gorm Larva from Tred'ova in the Mists of Tirna Scithe. Progress: Have you completed the task?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178581, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13334 } }, ["questType"] = "dungeon" },
[60247] = { ["id"] = 60247, ["name"] = "Trading Favors: Theater of Pain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12841, ["storyline"] = { 60247 }, ["description"] = "Grandmaster Vole runs the arena in Maldraxxus, where the champions of each of the houses compete for glory. Naturally, prizes are often awarded to the victors. Those of our kind do not often participate in such battles. To find such a prize for sale by one of us would be quite unusual indeed. I trust I need say no more? Let us keep this transaction between us, and I will be happy to part with some valuable goods.", ["objectivesText"] = "Obtain a Champion's Coin from Mordretha in the Theater of Pain. Progress: Six, seven, eight... oh, yes? Do you have an offer of trade? I have much more inventory to catalogue.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178580, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12841 } }, ["questType"] = "dungeon" },
[60248] = { ["id"] = 60248, ["name"] = "Trading Favors: Plaguefall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13228, ["storyline"] = { 60248 }, ["description"] = "Is is such a shame what happened to poor Margrave Stradama. Just between us, she was once one of our most favored trading partners. When things get lost in Maldraxxus they tend to end up at the bottom of her blighted pools. You would not, perhaps, be interested in continuing this relationship on her behalf? We would, of course, compensate you quite well. I am sure she has little use for these possessions in her current state.", ["objectivesText"] = "Obtain one of Stradama's Lost Ledgers from Margrave Stradama in Plaguefall. Progress: Oh, it is you again.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178579, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13228 } }, ["questType"] = "dungeon" },
[60249] = { ["id"] = 60249, ["name"] = "Trading Favors: Spires of Ascension", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12837, ["storyline"] = { 60249 }, ["description"] = "The Kyrians of Bastion serve a unique role in the Shadowlands, ferrying mortal souls from their realms to ours. They are able to do so in great numbers, it would seem, in times of crisis or devastation. We would like to know more about their travels to the realms beyond. Surely one of them has brought something back from another land? They are, after all, so very interested in memories.", ["objectivesText"] = "Obtain a Strange Doll from Devos, Paragon of Doubt in the Spires of Ascension. Progress: How may I assist you?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178578, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12837 } }, ["questType"] = "dungeon" },
[60250] = { ["id"] = 60250, ["name"] = "A Valuable Find: Theater of Pain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12841, ["storyline"] = { 60250 }, ["description"] = "The Theater of Pain in Maldraxxus is a brutal place, where only the strongest survive. With the houses so fiercely in competition with one another, it is considered a great point of pride to house a champion with a winning record. As such, the house lords often outfit their contenders with powerful arms, armor, and trinkets. Often these are storied items that have been passed down through many battles. I would very much like to see such an item.", ["objectivesText"] = "Obtain the Ring of Otherworldly Metal from Mordretha in the Theater of Pain. Progress: Were you victorious, or have you come to tend to your wounds?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178572, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12841 } }, ["questType"] = "dungeon" },
[60251] = { ["id"] = 60251, ["name"] = "A Valuable Find: Plaguefall", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13228, ["storyline"] = { 60251 }, ["description"] = "Life in Maldraxxus is one of constant warfare, the great houses in perpetual competition with one another. Every once in a great while, a house lord obtains an item or piece of knowledge of such rarity that it tips the scales in their favor. It is possible, even probable, that this was the cause of the fate that befell the House of Plagues. I do not need to tell you how valuable such a rarity would be to us, do I?", ["objectivesText"] = "Obtain A Slimy Correspondence from Margrave Stradama in Plaguefall. Progress: Yes? I am quite busy here.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178571, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13228 } }, ["questType"] = "dungeon" },
[60252] = { ["id"] = 60252, ["name"] = "A Valuable Find: Spires of Ascension", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12837, ["storyline"] = { 60252 }, ["description"] = "You have, no doubt, visited Bastion and seen what happens to souls that are accepted there. Their memories are extracted, viewed, and even stored in their great Temple of Wisdom. This temple houses memories that may answer some of the greatest questions we have about our realm and the worlds beyond. It is a shame they are locked away. We have heard that the fallen Paragon of Loyalty has interest in these memories. Any memory that would catch her attention would surely be worth trading for.", ["objectivesText"] = "Obtain the Fading Memory Glass from Devos, Paragon of Doubt in the Spires of Ascension. Progress: You have the look of one who has something to say.", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178570, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12837 } }, ["questType"] = "dungeon" },
[60253] = { ["id"] = 60253, ["name"] = "A Valuable Find: Necrotic Wake", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12916, ["storyline"] = { 60253 }, ["description"] = "Once in a rare while, we find ourselves in possession of an object of exceptionally cryptic origin. These objects allow us a brief glimpse into the realms beyond our comprehension. It may seem to you that I speak in riddles, yet so much of this realm is shrouded in mystery, even to us. There are others that have sought to unravel the history of this realm. Should you happen upon one of their works, I will offer you a trade of exceptional value.", ["objectivesText"] = "Obtain \" The Origin of Death \" from Nalthor the Rimebinder in the Necrotic Wake. Progress: What have you found?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178569, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12916 } }, ["questType"] = "dungeon" },
[60254] = { ["id"] = 60254, ["name"] = "A Valuable Find: Tirna Scithe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13334, ["storyline"] = { 60254 }, ["description"] = "The gorm are indiscriminate in what they consume, so long as it does not contain anima. A gorm queen that has lived for many generations may have any number of indestructible artifacts lodged within her belly. For this reason, sifting through a queen's carcass is not unlike treasure hunting for us. One of the largest queens is currently consuming Tirna Scithe. She surely is bloated with valuables. Should you come upon anything particularly unusual, know that we will compensate you in kind.", ["objectivesText"] = "Obtain the Unusual Automaton Parts from Tred'ova in the Mists of Tirna Scithe. Progress: You look as if you have been sifting through gorm carcass, or perhaps that is simply what you always look like?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178573, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13334 } }, ["questType"] = "dungeon" },
[60255] = { ["id"] = 60255, ["name"] = "A Valuable Find: De Other Side", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60255 }, ["description"] = "Mueh'zala has been around for many generations, how many exactly we cannot say. His domain is a land of mystery to us all. But we are a people of probabilities and margins. A creature of that age, with such power, and the many ancient souls within his domain, has a great chance to be in possession of a relic of unfathomable rarity. <The light around Ta'lan's head flares brightly for a moment. He seems... excited?> Slay the foolish creature, bring me his secrets, I will reward you handsomely!", ["objectivesText"] = "Obtain a Strange Ritual Mask from Mueh'zala in De Other Side. Progress: Have you brought something of interest?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178574, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "dungeon" },
[60256] = { ["id"] = 60256, ["name"] = "A Valuable Find: Halls of Atonement", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12831, ["storyline"] = { 60256 }, ["description"] = "The aristocracy of Revendreth trade in decadent and priceless shows of status with one another, but rarely with our kind. Often they will travel with a piece or two affixed to their garb as a show of status. Now, many of their kind have sided with Sire Denathrius and against the denizens of the Shadowlands. They must, of course, be stopped. Of course. Yet should you, in the process of doing so, relieve them of some of these possessions, know that I will trade generously.", ["objectivesText"] = "Obtain the Golden Orb of Energy from Lord Chamberlain in the Halls of Atonement. Progress: How does the battle fare?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178575, 178590, 178591, 178592, 178593, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12831 } }, ["questType"] = "dungeon" },
[60257] = { ["id"] = 60257, ["name"] = "A Valuable Find: Sanguine Depths", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12842, ["storyline"] = { 60257 }, ["description"] = "General Kaal has slain many foes, and in a bag at her side, she holds the skulls of those she considers her most precious kills. Not all of them, of course, have skulls -- it is a bag of eclectic contents. Contained within, we have heard, is the head of one of our kind. We do not know to whom it might belong, for we do not often find ourselves running afoul of the venthyr. Such a strange mystery must be solved. I will, of course, provide great compensation.", ["objectivesText"] = "Obtain an Ancient Broker Headpiece from General Kaal in the Sanguine Depths. Progress: What information do you bring?", ["rewardItems"] = { 1804, 1805, 1806, 1807, 178576, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12842 } }, ["questType"] = "dungeon" },
[60264] = { ["id"] = 60264, ["name"] = "Soul Survivor", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60264 }, ["description"] = "I knew when you helped me in the Etheric Vault, that you were a just and worthy leader. I have come here to offer you my help and services in your efforts to bring Maldraxxus back into balance. Please, build a construct for me, and allow me to help you as you have helped me.", ["objectivesText"] = "Take specifications for Miru's construct. Progress: Are you willing to do this?", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 119151 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167877, ["x"] = 0.55, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60274] = { ["id"] = 60274, ["name"] = "Trading Favors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 60274 }, ["description"] = "Welcome, friend. I can see by your garb that you must have quite a storied history. Many unique relics befitting of one that has traveled the worlds and vanquished many foes. There are those of us that find great value in such things, and would willingly part with our own valuables for a taste of what you may find. Let your curiosity guide you to the dark hallway across from the cookpots in the next room. Down there, you will find answers.", ["objectivesText"] = "Report to Finder Ta'sul in Oribos .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 1804, 1805, 1806, 1807, 184374 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[60283] = { ["id"] = 60283, ["name"] = "Specter Of War: Visectus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60283 }, ["objectivesText"] = "Progress: We have conjured Visectus to lead our attack, but we need your help to prepare it properly. We require more Anima-bound Wraps to strengthen the summons.", ["rewardItems"] = { 173202, 178594, 183619 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 161668, ["x"] = 0.535, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161668, ["x"] = 0.535, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60288] = { ["id"] = 60288, ["name"] = "Supplies from the Necrolords", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "emissary" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60288 }, ["description"] = "<name>, thanks to your efforts, our forces have been able to secure additional resources in our battles. The more you continue to dominate the battlefield the more resources our forces can spare.", ["objectivesText"] = "Speak with Oyne Soulborn at the Bleak Redoubt in Maldraxxus for your reward.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60291] = { ["id"] = 60291, ["name"] = "Corpse Run", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60291 }, ["description"] = "There's work that needs doing 'round here. Mmmm hmmm. Spotted a big ol' carcass nearby. I aim to salvage it for parts. Figure you could come along, help me drag it to Rathan . He'd like that. Mmmm hmmm. Reckon I could even carry you there and back. You don't look too big. Ready to get going?", ["objectivesText"] = "Return the Bone Carcass to Rathan at Butcher Block. Progress: Did you bring back the carcass?", ["rewardXP"] = 8165, ["rewardItems"] = { 178599, 182483, 182492, 182501, 182510, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1543, ["npcID"] = 158300, ["x"] = 0.332, ["y"] = 0.546 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536, 1543 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[60337] = { ["id"] = 60337, ["name"] = "Pupa Trooper", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60337 }, ["objectivesText"] = "Borrow a pair of enchanted wings", ["rewardXP"] = 8165, ["rewardItems"] = { 174042, 178717 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Borrow a pair of enchanted wings", ["amount"] = 1, ["type"] = 2, ["objectID"] = 365342, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60339] = { ["id"] = 60339, ["name"] = "The Ember Court", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60339 }, ["description"] = "Prince Renathal is prepared to host today's Ember Court whenever you're ready, Maw Walker. Be sure to talk to the rest of the staff to finalize the guest list and amenities before we open the court. Remember, we're trying to impress the guests and convince them that we know what we're doing, so make sure you choose amenities that'll make the guests happy! Talk to Lady Ilinca if you have any questions about guests. Once everything's ready, talk to me and I'll open the court!", ["objectivesText"] = "Finalize your guest and amenity selections for the Ember Court, then do your best to impress the guests. Progress: I can't wait to see who attends today's court!", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 176126, 176127, 176128, 176130, 176131, 176132, 176134, 176135, 176136, 176138, 176139, 176140, 176850, 179958, 181521, 181524, 181536, 182342, 182343 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.28, ["y"] = 0.43 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[60340] = { ["id"] = 60340, ["name"] = "Hands on Approach", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60340 }, ["description"] = "When I was imprisoned in the Etheric Vault, the anima scroungers would come to steal what little strength my soul still had. I swore I'd have revenge upon them should I ever escape. Now, with my blade hands... it's time for my revenge! I've seen anima scroungers near the House of Constructs. I want their leader dead and the anima they took from me recovered!", ["objectivesText"] = "Slay Wurtzog Soultap and recover 12 anima traces . Progress: Did you kill them all?", ["rewardXP"] = 8165, ["rewardItems"] = { 178788, 182484, 182493, 182502, 182511, 183127, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159214, ["x"] = 0.544, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60342] = { ["id"] = 60342, ["name"] = "Cut 'Em Down to Size", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60342 }, ["description"] = "Idle hands are a wasted opportunity. I need to keep my hands busy, or else these blades wouldn't be worth anything! I hear there's a devourer in Revendreth that's as tall as a house. Let's show the other constructs a thing or two by taking that monster out!", ["objectivesText"] = "Slay Charthox in the Dredgewood of Revendreth.", ["rewardXP"] = 8165, ["rewardItems"] = { 182484, 182493, 182502, 182511, 183127, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159214, ["x"] = 0.544, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544, ["y"] = 0.678 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60358] = { ["id"] = 60358, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60358 }, ["description"] = "Took our gildenite ! Stole it! Stole it and took it away! <Sika's feathers ruffle.> Need it, need it to make armor! Weapons! Can't make armor without gildenite ! <Sika moves her arms as if explaining how armor is made.> You understand? Yes? Why you still here?", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 182, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60360] = { ["id"] = 60360, ["name"] = "An Urgent Meeting", ["level"] = 7, ["requiredLevel"] = 7, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 60360 }, ["description"] = "I've been looking for you all over Orgrimmar , <name>. Warlord Grimaxe has delivered her mission report to the warchief. The Horde has need of you once again. I was ordered to find you and deliver the message without delay. It has been an honor to fight alongside you, <name>. Lok-tar ogar!", ["objectivesText"] = "Speak with Warlord Breka Grimaxe at Grommash Hold.", ["rewardXP"] = 125, ["starts"] = { { ["mapID"] = 85, ["npcID"] = 168771, ["x"] = 0.707333, ["y"] = 0.493333 } }, ["ends"] = { { ["mapID"] = 85, ["npcID"] = 168431, ["x"] = 0.511333, ["y"] = 0.827667 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.707333, ["y"] = 0.493333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard" },
[60362] = { ["id"] = 60362, ["name"] = "Blank", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1519, ["storyline"] = { 60362 }, ["series"] = { 46727, 46728, 46729, 47098, 47099, 51341, 57766, 58983, 59641 }, ["description"] = "Kul Tiras is the greatest naval power in Azeroth, and a former ally. But we've had little contact with them since Jaina's father, Lord Admiral Daelin Proudmoore, was defeated at Theramore. Many have criticized Jaina's decision that day, saying she believed so deeply in the promise of peace between the Alliance and Horde that she betrayed her own father. Perhaps she feels the time has come to atone for this. Loath as I am to put Jaina in harm's way... Kul Tiras must join the Alliance. Good luck.", ["objectivesText"] = "Speak with Lady Jaina Proudmoore in Stormwind Harbor.", ["rewardGold"] = 128700, ["rewardXP"] = 1415, ["rewardItems"] = { 204985, 205188 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[60363] = { ["id"] = 60363, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60363 }, ["description"] = "Hshh... the golden ore, we need it. Golden ore of Bastion. Make their armor with it. We need, many uses. Armors, weapons, trinkets and rings. Many uses. Travel to Bastion. The eyes have shown me stores of it, stolen and hidden throughout their lands. They do not use it. We will. Go now.", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 226, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60364] = { ["id"] = 60364, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60364 }, ["description"] = "Our allies in Bastion are in possession of a special ore known as gildenite . A golden metal used for many things in their lands, it is also useful to us. Once upon a time, we would have traded for it. Now, we have little to trade, and they have little to give. Yet it is a necessary component to focus our magics, capable of harnessing magical energy and amplifying it. Should you come across any in your travels, liberate it, and return it to me. I shall use what we need, and share the remainder.", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 204, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60365] = { ["id"] = 60365, ["name"] = "Gildenite Grab", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60365 }, ["description"] = "The golden ore known as gildenite is found only in Bastion. Used to make many of their own armors, it is useful to us all. We harden our own armors and weapons with it, and it holds magical charge well. Our stores are nearly depleted, and we have little to trade, but our needs are great. Let us reflect. In Bastion, there are those that have turned their backs on their own people. We may relieve these deceivers of their gildenite without remorse.", ["objectivesText"] = "Collect 3 Gildenite from rare monsters and treasure chests in Bastion.", ["rewardItems"] = { 179321 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 248, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60369] = { ["id"] = 60369, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60369 }, ["description"] = "The shapers of our lands cultivate a very special form of wood we call wealdwood . It contains the essence of Ardenweald, of the plants and animals that make up our soil and our air. It can be enchanted with powerful magics, and it will not burn. It is the basis of our arms and armor, and in these dark days, it is a target of our enemies. They steal and hoard it, out there in the wilds. Find them, and return our treasures to us.", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 203, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60370] = { ["id"] = 60370, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60370 }, ["description"] = "In Ardenweald, the shapers form boughs into a magical form of wood. Wealdwood , an enchanted substance used for many sorcerous purposes, is a key component in our rituals. Without it, our magics pale in comparison to those of our enemies. Yet in these times, Ardenweald is beset by many foes. They steal the supplies of the Night Fae and scurry off into the dark places. Travel to those places, and return to us once you have brought atonement to these vile creatures.", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 247, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60371] = { ["id"] = 60371, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60371 }, ["description"] = "The eyes have shown me supplies, in Ardenweald. Hidden in the boughs, hidden from us, but they cannot hide from the eyes. They do not use it, not as we would. We must use it. It is ours to take. Kshhhh... bring it to us, the shaped wood. Many uses, very magical. Holds magic as a pitcher holds slime, fills with it. Need it for our sorcerers. Cannot win in battle without our magic. Must win, no other way.", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 225, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60372] = { ["id"] = 60372, ["name"] = "A Wealth of Wealdwood", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60372 }, ["description"] = "Ardenweald in trouble! We in trouble too! No Ardenweald, no wealdwood . wealdwood magical, help us make many thing. You find some? Bring to Sika? Yes? Hoo? Yes. <Sika writes your name on a scroll and underlines it twice, then shows it to you.> See?", ["objectivesText"] = "Collect 3 Wealdwood from rare monsters and treasure chests in Ardenweald.", ["rewardItems"] = { 179320 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 181, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60373] = { ["id"] = 60373, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60373 }, ["description"] = "There is a dark, evil vine that grows in Revendreth, known as sorrowvine . They say it feeds off of the anguish of the souls as they are broken. Regardless of its origins, it is used in many of our potions and spells. It contains a powerful magic, likely a product of its origin. Revendreth has little opportunity to trade with us these days. Should you find any of these vines, I will gladly accept them.", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 206, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60374] = { ["id"] = 60374, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60374 }, ["description"] = "The denizens of Maldraxxus are used to a life of battle, and in doing so, find themselves in possession of so very many bones. They form their armors out of a cultivated form of bone we call bonemetal . Harder than most metals, yet pliable, it can be forged into a variety of shapes without losing its strength. We have many uses for it, both as a means of attachment, and when ground up, as a reagent. We cannot ask them for resources now, but if you find any, I would use it.", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 205, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60375] = { ["id"] = 60375, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60375 }, ["description"] = "Maldraxxus no longer answers our calls, and the houses are in disarray. Yet we have need of them. Once, they supplied us with bonemetal , a strong yet malleable material useful for many armors. There are those in Maldraxxus that hoard the material, seeking to profit from the chaos. They must atone for these sins.", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 249, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60376] = { ["id"] = 60376, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60376 }, ["description"] = "Ksh-ksh-ksh... you are needed. So many betrayers in our lands, many deaths, much armor destroyed. Need to rebuild. The eyes have shown me stores of bonemetal , hoarded by our foes. Bring them to me.", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 227, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60377] = { ["id"] = 60377, ["name"] = "Bonemetal Bonanza", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60377 }, ["description"] = "<Sika is studying a scroll.> No bonemetal ! Again, out of bonemetal ! <Sika throws a pile of scrolls into the air.> Hoo! Where you come from? Oh, OH. bonemetal ! You get? Get from Maldraxxus. Help us out! <Sika points in the direction of Maldraxxus.> That way!", ["objectivesText"] = "Collect 3 Bonemetal from rare monsters and treasure chests in Maldraxxus.", ["rewardItems"] = { 179317 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 183, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60378] = { ["id"] = 60378, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60378 }, ["description"] = "Sorrowvine grows only here, in the lowlands of Revendreth. It has power contained within the leaves and seeds, perhaps a byproduct of the cleansing of sins. We use it for many things, from potions to venoms. It is a versatile reagent. Our stores are low, and we have little ability to forage these days with the forces of our enemies bearing down on us. As you travel our lands, should you come upon any, we would make good use of it.", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 250, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60379] = { ["id"] = 60379, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60379 }, ["description"] = "Kshh... need you today. Stores of sorrowvine getting low, need it for our venoms. Revendreth does not answer our calls. The eyes show me conflict and strife in their lands. This matters little to us. Shh... travel there, find their vines, return to me.", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 228, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60380] = { ["id"] = 60380, ["name"] = "A Source of Sorrowvine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60380 }, ["description"] = "Need sorrowvine ! Please help! Revendreth not sending us supplies, not answering Sika! Can't make potions now. What we do? <Sika seems to have just remembered that you were there.> You go! <Sika pushes you.> Go go!", ["objectivesText"] = "Collect 3 Sorrowvine from rare monsters and treasure chests in Revendreth.", ["rewardItems"] = { 179318 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 184, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60381] = { ["id"] = 60381, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60381 }, ["description"] = "Today, we must turn our gaze inward. We are beset by foes here, in Ardenweald, from all sides. Travel our lands, weapon in hand, and bring hope and victory with you. Bring aid to those in need, and remind them that we are here for them, and Ardenweald will not fall. Remind them that our great purpose will be fulfilled, and we will not let the groves wither. You, Maw Walker, will unite us today.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you brought hope and faith to our people today?", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 207, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60382] = { ["id"] = 60382, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60382 }, ["description"] = "We do not turn out backs on our allies, even when we face darkness here in Ardenweald. In Revendreth, they battle against the forces of Sire Denathrius, who has proven himself a false leader. We cannot allow those that make Sinfall their home to lose hope. Travel to Revendreth and supply aid to them. Show them that we will not let them falter, that we are stronger together.", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: How goes the battle in Revendreth?", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 210, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60383] = { ["id"] = 60383, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60383 }, ["description"] = "Maldraxxus defends us from forces that threaten the Shadowlands, or at least, they once did. Now they are plagued by infighting and an imbalance in power. We have few allies there, but those that remain, we must maintain. Go there, give them aid, and help them reunite the houses such that the armies of the undying may defend us once more. Without them, we are but one invasion from complete annihilation.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: Have you aided the forces of Maldraxxus?", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 209, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60384] = { ["id"] = 60384, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60384 }, ["description"] = "The denizens of Bastion have long served the Shadowlands with faith and honor. Without them, souls would not arrive for us to nurture, and our lands would wither and die. We cannot allow them to fall, for without Bastion, we are lost. Travel to the golden fields, weapon in hand, and provide aid to our besieged allies. We will show them that in these dark times, they are not alone.", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Have you aided Bastion today?", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 208, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60385] = { ["id"] = 60385, ["name"] = "Training in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60385 }, ["description"] = "The dark lands of Revendreth, ruled over by the traitor Denathrius, pose a great risk to us, and a great opportunity for training. Come here, trainee! Today, you hunt with the Maw Walker. Should you return to me, we will celebrate, with a hunt. For tomorrow, we hunt.", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee.", ["rewardItems"] = { 181556 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 214, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60386] = { ["id"] = 60386, ["name"] = "Training in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60386 }, ["description"] = "The forces of Maldraxxus are some of the most highly trained and well-regimented in all of the Shadowlands. Once, they defended us all, now we must fend for ourselves. There is little better place for our trainees to gain real combat and strategy experience than on their blood-soaked battlefields. Take this one with you on your travels today, so that they may see what real combat looks like.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Do you return with a trainee, or a coward?", ["rewardItems"] = { 181732 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 213, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60387] = { ["id"] = 60387, ["name"] = "Training in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60387 }, ["description"] = "Our hunters do not have the time for proper training, and so we must train them in the field. Our allies in Bastion are in desperate need of support, and I wish one of the trainees to accompany you in this endeavor. Do you hear that, trainee? Today, you accompany the Maw Walker! Maw Walker, do not go easy on this one.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee. Progress: I hope that today's trainee survived the trip, but I am not overly confident.", ["rewardItems"] = { 181372 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 212, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60388] = { ["id"] = 60388, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 60388 }, ["description"] = "Get up, trainee, you must get up! Look at this one! Needs much more training before we stand a fighting chance against our enemies. We have precious little time to build combat prowess these days, with so many foes at our backs. Take this one with you today, show them the ways of battle, and keep them safe from overwhelming odds. It is the only way we will make enough progress.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee. Progress: How goes the training?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158544, ["x"] = 0.478, ["y"] = 0.535 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.478, ["y"] = 0.535 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 211, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60389] = { ["id"] = 60389, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60389 }, ["description"] = "Ay there, ya got a moment? Lotta things going on down in Ardenweald. Bad stuff, bugs and things. Look delicious, but probably give me ol' stomach a nasty one. We're lookin' pretty solid here today, ya see? Probably could use a hand down there. Maybe they give us a hand in return, see? Do I gotta spell it out for you? Get on over there, ya big goof.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald.", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 251, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60390] = { ["id"] = 60390, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60390 }, ["description"] = "We are attacked by enemies on all sides, Maw Walker. And Ardenweald faces a similar threat. It is in our best strategic interests to forge lasting alliances with those outside of Maldraxxus. Though we may be under assault, we are still the strongest military might in the Shadowlands. Under our protection, they will thrive and grow, and in turn, provide us with aid in our times of need. Together, we are strong. This is the doctrine of the phalanx, and it will be ours as well.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you secured allies in Ardenweald?", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 229, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60391] = { ["id"] = 60391, ["name"] = "Aiding Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60391 }, ["description"] = "Ardenweald has long been one of our closest companions in the shepherding and nurturing of souls. Now they are beset by many foes, and we will not allow them to fall! Make haste to their forested lands, and with the blessing of the Archon upon you, serve a glorious purpose. Stand with them in their time of need, a gilded shield, a reminder that they are not alone! Bastion stands with them, and with us, they will never falter!", ["objectivesText"] = "Complete 3 World Quests in Ardenweald. Progress: Have you served in Ardenweald today?", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 185, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60392] = { ["id"] = 60392, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60392 }, ["description"] = "In our own golden hills, evil abounds. We will not allow it to take root and fester! Raise your voice, Maw Walker, and shout to the foes of Bastion! We are coming for them! With haste, now, seek out those in need of your might. Bring the sharpened blade of faith to bear against doubt and uncertainty. Crush despair with a gilded fist, and let it know the vengeance of the Archon! For Bastion!", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Do the hills echo with the cries of your victories, Maw Walker?", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 186, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60393] = { ["id"] = 60393, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60393 }, ["description"] = "The kyrians of Bastion serve a unique purpose in the Shadowlands, and without them we will be unable to replenish our forces. Should we wish to stand triumphant in Maldraxxus, we must extend some of our might to aid them. Travel to Bastion and provide support, so as to stabilize their situation. In doing so, we will secure the future of our armies and cut off the supply to our enemies. War is not always fought on the battlefield, but often in the means of replenishment.", ["objectivesText"] = "Complete 3 World Quests in Bastion. Progress: Have you secured the situation in Bastion?", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 230, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60394] = { ["id"] = 60394, ["name"] = "Aiding Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60394 }, ["description"] = "If'n the kyrians of Bastion don't get souls to the Shadowlands, we got no one to join up, and no anima to gain in them sinstones. Be in a bad place, you know, now and in the future, if things ever bother to get better. We got things figured out here today. Head on over to them golden hills of Bastion and give 'em a hand. Bet they pay us back some day. They're all about honor an' stuff. < Rendle wipes his nose loudly.>", ["objectivesText"] = "Complete 3 World Quests in Bastion.", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 252, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60395] = { ["id"] = 60395, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60395 }, ["description"] = "In the fetid wastes of Maldraxxus, we yet find allies. Their sacred duty, to defend the Shadowlands, has not been forgotten by all. We must take flight, now, to stand side by side with our bone-bound brethren. Shoulder to shoulder, hand in hand, we will push back those that would sow chaos and discord. A spear of gold and bone we will form! And thrust it into the heart of evil! Go now, Maw Walker, as the tip of the spear, to glorious battle!", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: Have you pierced the heart of evil in Maldraxxus?", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 187, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60396] = { ["id"] = 60396, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60396 }, ["description"] = "The allies we have here in Maldraxxus may be few, but we cannot turn our backs on them. Every hand we pull out of darkness and into our fold, is a hand that can hold a weapon or wand. Walk our lands, find those seeking aid, and provide it. Crush our enemies, and show them that we are at once everywhere. Make them fear you. Fear is the seed that breeds doubt, and doubt is the root that crumbles empires.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus. Progress: How goes the battle?", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 231, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60397] = { ["id"] = 60397, ["name"] = "Aiding Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60397 }, ["description"] = "Once was a time that those bony lot in Maldraxxus were the defenders o' all of us here in the Shadowlands. Now they spend their time destroyin' what little they got left. All's I know is that if things keep up like this, one big ol' swath of devourers could sweep in and wipe us all out. Get over there and help them good ones keep the peace, maybe they help us out some day, too.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus.", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 253, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60398] = { ["id"] = 60398, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60398 }, ["description"] = "Our allies in Revendreth are all that stem the tide of Denathrius's forces from overtaking the rest of the Shadowlands. Once, we would be charged with righting this wrong, but our armies have dwindled with the actions of our rival houses. Today, you will be the messenger from Maldraxxus, carrying a message of justice in the name of the great cycle of which we all take part. It is your Primus-given duty to aid Sinfall against those that seek to break the cycle.", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: Have you broken the forces of Denathrius?", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 232, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60399] = { ["id"] = 60399, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1700, ["storyline"] = { 60399 }, ["description"] = "Oi there, got somethin' for you to do today. Lots of problems outside of Sinfall, there are. Big problems, little problems, all sorts of problems. We're not gonna make much headway against Denathrius with his lot at our heels all the time, ay? Get out there an' get some muck on your boots.", ["objectivesText"] = "Complete 3 World Quests in Revendreth. Progress: What do ya want?", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 254, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60400] = { ["id"] = 60400, ["name"] = "Aiding Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60400 }, ["description"] = "Take flight to Revendreth, where those that are loyal to the Shadowlands are under siege from the forces of Sire Denathrius. We cannot allow them to fall. Without the aid of Sinfall, the forces of Revendreth will grow unchecked, and their dark alliance with the Jailer will threaten us all. We of Bastion will not allow this to happen! Raise your swords, ready your shields, take wing and bring the glory of Bastion to Revendreth!", ["objectivesText"] = "Complete 3 World Quests in Revendreth.", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 188, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60401] = { ["id"] = 60401, ["name"] = "Training in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60401 }, ["description"] = "I have another trainee for you to look after, they need some training on the battlefield. Take them out to, oh, let's say Ardenweald. <Sakaa waves her hand vaguely in the direction of Ardenweald.> Plenty of things to maim over there, maybe they learn a thing or two about wood. <Sakaa smirks.>", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee.", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 255, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60402] = { ["id"] = 60402, ["name"] = "Training in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60402 }, ["description"] = "Look at this lot! Bones and gristle, all of them. Need some meat on their bones and some training in their heads. Take this trainee out and get them some real combat experience. Ardenweald's a good spot, plenty of things to fight there. Learn some new tactics, get them used to the chaos of battle, all that stuff.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee. Progress: You back already?", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 233, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60403] = { ["id"] = 60403, ["name"] = "Training in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60403 }, ["description"] = "It is our great duty to take our aspiring warriors and train them in combat. Today, this is your trainee. Take them to Ardenweald, show them what it means to be in the glorious service of the Archon. Defend our allies, and bring faith to their lands. Teach them the ways of battle and honor.", ["objectivesText"] = "Complete 3 World Quests in Ardenweald with your trainee. Progress: How fares the training?", ["rewardItems"] = { 171263, 171301, 171349, 171436, 171439, 173126, 174285, 177040, 178227, 179286, 180318, 181475, 184500, 184501, 184502, 184503, 184504, 184507 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 189, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60404] = { ["id"] = 60404, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60404 }, ["description"] = "What better place to stretch our wings than right here on our own fields? Take one of our trainees out with you today, show them the ways of combat in Bastion against the growing threats we face here. Part of their training will be courage when facing off against those they thought their brethren. It has been known to break hearts and ranks before.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee. Progress: How fares your heart today?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 190, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60405] = { ["id"] = 60405, ["name"] = "Training in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60405 }, ["description"] = "Useless minions, the lot of them. All of this fodder needs to get trained. Here, take this one with you today. Get them away from me, go to... Bastion. Yeah, Bastion, far away from me. Plenty of things to test them against, there. If you get them killed, I don't want to hear it.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee. Progress: Any luck with this sad lot?", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 234, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60406] = { ["id"] = 60406, ["name"] = "Training in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60406 }, ["description"] = "I have yet another minion, er, recruit that needs training. Take them on out to the fertile fields of Bastion. There is plenty to learn over there that they won't find around these parts, perhaps it will help them grow into a better soldier. Maybe you pick up some new tricks while you're out there, too.", ["objectivesText"] = "Complete 3 World Quests in Bastion with your trainee.", ["rewardItems"] = { 92683, 116424, 171268, 171270, 171441, 181372, 184090 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 256, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60407] = { ["id"] = 60407, ["name"] = "Training in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60407 }, ["description"] = "Our aspiring warriors must be trained in the thick of battle, in the harshest conditions, for wars do not happen lightly, and never will it give them pause for breath. Take this one to Maldraxxus--the heart of the armies of the Shadowlands resides there. It is a land in chaos and turmoil, filled with fallen champions and gladiators. There, they will face true challenges, and return with great knowledge.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Has your trainee survived the fields of battle?", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 191, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60408] = { ["id"] = 60408, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60408 }, ["description"] = "Our armies are nothing without some combat training, but every time we send them out, they come back as a pile of bones and meat. Take a trainee out and pit them against the forces of the other houses. Just don't get them killed, alright? Not all the way killed. A little killed is fine.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Any luck out there?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 235, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60409] = { ["id"] = 60409, ["name"] = "Training in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60409 }, ["description"] = "Another trainee needs some looking after, if you don't mind. Maldraxxus is a place of constant battle, and probably the best place to take them. They've got to learn about war and strategy and, you know, all that. Just throw them in the arena or something. 'Sink or swim' is an effective training strategy.", ["objectivesText"] = "Complete 3 World Quests in Maldraxxus with your trainee. Progress: Could really go for a nap I could.", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 257, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60410] = { ["id"] = 60410, ["name"] = "Training Our Forces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60410 }, ["description"] = "I have yet more troops for you to train, and there are plenty of things to do right here in our domain. Take them out and give them a good, solid, and probably bloody taste of what we're up against. Now, if you get them killed? That's none of my business. <Sakaa sips a thick and sweet-smelling beverage.>", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee. Progress: Did you manage to bring them back alive?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 258, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60411] = { ["id"] = 60411, ["name"] = "Training in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60411 }, ["description"] = "Lousy, useless, bunch of bones. This army's less of an army than it is a bunch of dead meat walking. Do me a favor, take out this trainee and head over to Revendreth. Give them some good battle training against some of our enemies, a little taste of strategy and tactics and maybe getting hit in the face with a little magic. Won't do us any good unless we find a way to train them that doesn't end up in a bunch of dead minions.", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee. Progress: Well? You bring back a pile of bones or a trainee?", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 236, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60412] = { ["id"] = 60412, ["name"] = "Training in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60412 }, ["description"] = "A trainee is in need of your guiding hand. Take them to Revendreth, where you will find the armies of Denathrius thirsting for our demise. Wade in to battle with them against our mighty foes. Return victorious, as their shield and mentor, so that our armies will be bolstered this day.", ["objectivesText"] = "Complete 3 World Quests in Revendreth with your trainee.", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 192, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60414] = { ["id"] = 60414, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 60414 }, ["description"] = "The Brokers are odd characters, but useful. They can find many things across the vast realms of the Shadowlands that we cannot. We have relied upon them to bring us useful materials for many years, but these days, we have little to trade. They value a currency of their own making, coins of brokerage, as a general means of trade. If you find any in your travels, I would appreciate a handful, as it would allow me to procure some rare and necessary items.", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Have you found any coins?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 168513, ["x"] = 0.435, ["y"] = 0.524 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168513, ["x"] = 0.435, ["y"] = 0.524 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.435, ["y"] = 0.524 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 202, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60415] = { ["id"] = 60415, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60415 }, ["description"] = "Hello! Yes! Hello. Brokers, you know them? < Sika does her best attempt at looking like a broker. It is not convincing.> Trade many things with us. Things we no get. Things we want. Need coins. Clink clink! < Sika makes a circle with her finger feathers.> Find them everywhere, bring them to Sika !", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Bring coins to Sika ? Need trade with brokers. You know this?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168519, ["x"] = 0.634, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168519, ["x"] = 0.634, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 180, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60416] = { ["id"] = 60416, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60416 }, ["description"] = "Kh-kh-kh... the brokers, they go to many places. Many places we cannot. The eyes cannot follow them. Find many secrets, they do. Bring us supplies, strange and rare. Need things to trade. Need broker coins. They trade with all. Find coins in all lands. Slay those that hold them, bring the coins to me. You may eat their corpses, I will not judge. Just need coins.", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Bring me coins? Coins for brokers. Many uses. You see?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 224, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60417] = { ["id"] = 60417, ["name"] = "Rare Resources", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13400, ["mapID"] = 1700, ["storyline"] = { 60417 }, ["description"] = "The brokers are an enigmatic group. We know little about them, save that they can travel to many lands in the Shadowlands that we cannot. How they do this, we are not sure. They are willing partners in trade, though, and through them we have acquired many rare and valuable resources that cannot be found elsewhere. They hold in high regard a currency of their own creation, you may find such coins in your travels. I will gladly take them off of your hands to bolster our supplies.", ["objectivesText"] = "Collect 3 Coins of Brokerage from rare monsters and treasure chests in the Shadowlands. Progress: Have you found any of the broker's coins?", ["rewardItems"] = { 179327, 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 246, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60418] = { ["id"] = 60418, ["name"] = "A Call to Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60418 }, ["description"] = "Our allies in Bastion are absolutely necessary for the Shadowlands to function at all. They alone can bring us the souls we need to keep the cycle moving. If they fall to darkness, it's only a matter of time before we, too, dwindle and fade. They are beset by all manner of problems. We have to get over there and help them!", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: How are the Kyrians?", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 194, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60419] = { ["id"] = 60419, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60419 }, ["description"] = "They say that all of the Shadowlands is a stage, and right now, I think we're in a tragedy! All throughout Ardenweald, we are under attack. They seek our anima and the souls that we protect. If the cycle stops here, so many great souls will be lost... forever. There's no time to waste, we need your help! Defend Ardenweald!", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Are things improving in the glades?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 193, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60420] = { ["id"] = 60420, ["name"] = "A Call to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60420 }, ["description"] = "I'm glad you're here! We've got some problems in Maldraxxus. The forces of Maldraxxus are the defenders of the Shadowlands. They've always managed to balance one another out, like actors on a stage, never stealing too much of the spotlight. But now, some of the houses have overthrown the balance, and seek to conquer the rest of us! Our allies there need our help! Aid them however you can.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons. Progress: Are things improving in Maldraxxus?", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 195, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60421] = { ["id"] = 60421, ["name"] = "A Call to Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60421 }, ["description"] = "Oh, I'm glad you're here, we've got a problem! Our friends in Revendreth are struggling under the rule of Sire Denathrius. He was always a cruel leader, and now he's thrown in his lot with the Jailer! If Denathrius's control of Revendreth isn't broken, he'll come for us next... Let's do whatever we can to help them out!", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: How are things in Revendreth?", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 196, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60422] = { ["id"] = 60422, ["name"] = "A Call to Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60422 }, ["description"] = "We cannot stand alone. If one section of the Shadowlands falls, we will all be in danger. The great soul-trees of Ardenweald are under assault from many foes that seek to harness their power. We must aid our allies in the Night Fae, and punish their enemies for these transgressions. We are stronger together.", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Have you completed your task?", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 237, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60423] = { ["id"] = 60423, ["name"] = "A Call to Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60423 }, ["description"] = "Ardenweald was once a place of peace and regrowth, now beset by dark forces from all sides. Maldraxxus alone is responsible for challenging those that would disrupt the cycle. Take our banners, steady your weapons, and bring war to Ardenweald. For the Shadowlands.", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: How do the boughs break?", ["rewardItems"] = { 181475 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 215, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60424] = { ["id"] = 60424, ["name"] = "A Call to Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60424 }, ["description"] = "Ardenweald is one of our closest allies, and to them we ferry some of the most powerful souls. Should the weald fall, the devastation that would be unleashed could destroy us all. We must aid the Winter Queen. It is the will of the Archon. Go now, and provide support to the Night Fae.", ["objectivesText"] = "Defend Ardenweald by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Mists of Tirna Scithe and De Other Side dungeons. Progress: Have things improved in Ardenweald?", ["rewardItems"] = { 181475 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 171, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60425] = { ["id"] = 60425, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60425 }, ["description"] = "Sometimes we must look inward to find true darkness. Here, in Bastion, where once there was harmony, now we face many foes. Today, we root them out. Head into the golden fields, with your weapon in hand. Cleanse us of these foul creatures, aid our forces when they have need of you. In the name of the Archon.", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Are the fields cleansed?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 172, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60426] = { ["id"] = 60426, ["name"] = "A Call to Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60426 }, ["description"] = "We, the defenders of the Shadowlands, will never let a great foe go unchallenged. The Kyrians of Bastion have long served all denizens of the Shadowlands by ferrying souls. We would be lost without their services. Now, they too are under attack from within. We must defend them in their time of need. Go now, and bring glory in the name of the Primus.", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Are the golden fields bathed in blood?", ["rewardItems"] = { 179327, 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 216, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60427] = { ["id"] = 60427, ["name"] = "A Call to Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60427 }, ["description"] = "The denizens of Bastion are a key component to the cycle of power here in the Shadowlands. Without them, we cannot replenish our ranks, and the forces of the Jailer will grow ever stronger. They have their own troubles in these times, as well. Today, we must look without, and aid our allies. Travel to the golden fields, and rid them of their foes. Only with allies do we stand a chance against Denathrius.", ["objectivesText"] = "Defend Bastion by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Spires of Ascension and Necrotic Wake dungeons. Progress: Have you completed your task?", ["rewardItems"] = { 181372 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 238, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60429] = { ["id"] = 60429, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60429 }, ["description"] = "Look! Look around you! All around us, foes await the crushing hand of victory. There is an upset in the balance of power, and with it, the defenders of the Shadowlands are weakened. The only cure is more combat! Challenge the houses that sought to disrupt Maldraxxus, bring them to heel under the weight of your boots.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons. Progress: Have you littered the ground with the bones of your enemies?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 217, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60430] = { ["id"] = 60430, ["name"] = "A Call to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60430 }, ["description"] = "The forces of Maldraxxus have long defended the Shadowlands from threats outside of our lands. Now, they face their greatest threats from within. The balance of power between the houses is broken. It has led them to assault us, and others. Their problems are many, our solutions are just. Travel to Maldraxxus and slay those that would do the Shadowlands harm, providing shelter to your allies when you find them.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", ["rewardItems"] = { 181732 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 173, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60431] = { ["id"] = 60431, ["name"] = "A Call to Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60431 }, ["description"] = "The forces of Maldraxxus were once intended to defend the Shadowlands against threats from beyond. They are all but broken, now. The houses are in disarray, infighting with one another. We have few allies there, and those that have sided with us are bruised and beaten. Go now, aid them, and slay their foes. Bring balance back to Maldraxxus, and in turn, will they aid us.", ["objectivesText"] = "Defend Maldraxxus by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Plaguefall and Theater of Pain dungeons.", ["rewardItems"] = { 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 239, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60432] = { ["id"] = 60432, ["name"] = "Troubles at Home", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60432 }, ["description"] = "There are many tasks that need your attention outside of the walls of Sinfall. Our closest allies are under assault from all sides, and the forces of Denathrius are unrelenting. Take your weapon and steel yourself. Today, we defend Revendreth, and in doing so, further bulwark ourselves against our enemies. We will take back what is ours.", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: Have you reclaimed our homeland?", ["rewardItems"] = { 181372, 181475, 181556, 181732 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 240, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60433] = { ["id"] = 60433, ["name"] = "A Call to Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60433 }, ["description"] = "We fight not only for might and glory, but for the greater good of the Shadowlands. It is our calling to bring war upon those that would disrupt the flow of souls. There is one such betrayer - Sire Denathrius. Bring the vengeance of Maldraxxus down upon his foul crown. Slay his allies, serve his foes, end his reign in carnage.", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: How fares the battle for Revendreth?", ["rewardItems"] = { 181556 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 218, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60434] = { ["id"] = 60434, ["name"] = "A Call to Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60434 }, ["description"] = "We all serve the greater purpose here, even those in Revendreth that we may not agree with. We take souls to them in need of a harsher form of cleansing, and it is just. Yet Sire Denathrius has gone too far, and now seeks to control all of the Shadowlands. We have friends there, amongst the Venthyr. Aid them, and put their enemies to rest. The Word of the Archon is with you.", ["objectivesText"] = "Defend Revendreth by completing Daily Quests and World Quests, looting treasures, and slaying rare creatures. You may also defeat powerful foes in the Sanguine Depths and Halls of Atonement dungeons. Progress: Have you returned victorious?", ["rewardItems"] = { 181556 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160037, ["x"] = 0.664, ["y"] = 0.165 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.664, ["y"] = 0.165 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 174, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60435] = { ["id"] = 60435, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60435 }, ["description"] = "We never truly counted the forces of Denathrius as our allies, and now he has shown his true colors. Over many years, he has built an army. One capable of destroying any other land, provided we were divided, and not united. He has empowered monstrous creations and broken them to his will. What better way to secure our allies and test our strength, than to eliminate his most fervent champions. Go now, and hunt.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Have you thinned Denathrius's forces?", ["rewardItems"] = { 181557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 200, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60436] = { ["id"] = 60436, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60436 }, ["description"] = "Maldraxxus is a land of conflict and strife. There is little better place than to test yourself against the might of the Shadowlands. There, you will find warriors that are bred on combat, honed by the sword and hammer, tested in arenas and battlegrounds. Crash into them like the felling of a great branch, let them see the might of Ardenweald is no less terrifying.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Have you returned victorious?", ["rewardItems"] = { 181733 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 199, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60437] = { ["id"] = 60437, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60437 }, ["description"] = "Bastion has long been one of our closest allies, and a key to the inner workings of the Shadowlands. We cannot abide dysfunctions in the passage of souls. They are beset by a host of issues brought on by dissension in their ranks. Every day, doubt gnaws at their forces, bleeding away their hope, and plunging us further into chaos. Doubt is a powerful foe, and not easily dispatched. Keep your wits about you and crush these dark thoughts.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you aided the denizens of Bastion?", ["rewardItems"] = { 181741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 198, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60438] = { ["id"] = 60438, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60438 }, ["description"] = "The Wild Hunt count as our prey the most dangerous creatures in the weald. Here, you may test yourself against challenges the likes of which you may not have faced in your previous life. In our current state, my gravest concern is with Tirna Scithe. Once full of life, it is now overtaken by multitudes of foul creatures. They siphon its power, and though we may never regain the glade, we must not allow this to continue. Take on this trial, and put an end to the invaders of Tirna Scithe.", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: How goes the hunt?", ["rewardItems"] = { 181476 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 197, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60439] = { ["id"] = 60439, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60439 }, ["description"] = "Our close companions in Ardenweald face challenges unlike any that have previously plagued their peaceful glades. Ready your weapons, for now is the time that the golden shields of Bastion shine. Now is the time to take flight into the weald and show courage in the face of darkness. It is not always about us, you see. True courage means fighting for others when necessary, even against overwhelming odds and the most vile of evils. Light shines only in darkness.", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Have you cleansed the weald?", ["rewardItems"] = { 181476 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 175, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60440] = { ["id"] = 60440, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60440 }, ["description"] = "Looking to prove yourself? I hear there are powerful creatures invading Ardenweald. Sounds like a challenge, no? So ready your weapon and get out there! What better place to prove your might? Smash them to pieces, in the name of Maldraxxus!", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Rip and tear!", ["rewardItems"] = { 181476 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 219, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60441] = { ["id"] = 60441, ["name"] = "Challenges in Ardenweald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60441 }, ["description"] = "Ardenweald was once a place of peace and regrowth, but no longer. Foes assault the weald from all sides, dark creatures that serve no masters. They will not be exempted from the hand of justice. We will bring the trials of Revendreth to bear upon them. They will see what we do to those that must be broken. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Terrors in Tirna Scithe World Quest, the Mists of Tirna Scithe Dungeon, or De Other Side Dungeon in Ardenweald. Progress: Has justice been served?", ["rewardItems"] = { 181476 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 241, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60442] = { ["id"] = 60442, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60442 }, ["description"] = "Sometimes we need look no further than our own golden hills to find a suitable challenge. Doubt has crept into the minds of some of the most stoic shieldbearers of the Kyrian people. It has poisoned them against us, and in doing so, harmed the ability of the Shadowlands to heal from this blight. We must stand against them, now. It will not be easy, but things that are worth fighting for rarely are.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you seen the face of doubt and shown it certainty?", ["rewardItems"] = { 181741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 176, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60443] = { ["id"] = 60443, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60443 }, ["description"] = "We consider the denizens of Bastion to be allies of a sort. Without their service, we would have no souls, and without souls, we could not raise armies, and without armies, we could not smash our fists against one another in the glorious theatre of battle! <Grandmaster Volo laughs and smashes his weapon around.> We must aid them against their foes, or else the arena will sit barren, and we can't have that! Find their greatest enemies and turn their bones into golden dust.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Have you clipped their wings?", ["rewardItems"] = { 181741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 220, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60444] = { ["id"] = 60444, ["name"] = "Challenges in Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60444 }, ["description"] = "Our allies in Bastion have long served the cycle of the Shadowlands, delivering souls in need of our services. Yet, within their ranks, doubt has grown and festered. If this continues, we will all pay. Their loss of focus shall not be allowed to continue. We will punish their wandering hearts. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Disloyal Denizens World Quest, the Spires of Ascension Dungeon, or the Necrotic Wake Dungeon in Bastion. Progress: Has justice been served?", ["rewardItems"] = { 181741 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 242, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60445] = { ["id"] = 60445, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60445 }, ["description"] = "The purpose of Maldraxxus is to raise the most competent and confident warriors that the Shadowlands has ever seen, to create the perfect army in order to defend us against threats from the outer worlds. Here, you will find some of your greatest challenges. Seek out the champions of the strongest houses, stand against them, and let them see your might.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Do you stand victorious?", ["rewardItems"] = { 181502, 181733, 183484 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 221, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60446] = { ["id"] = 60446, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60446 }, ["description"] = "Those of Maldraxxus are the chosen warriors of the Shadowlands, charged with defending us against threats from other worlds. For many years, a careful balance has been maintained between the houses. Now, there are those that have broken this balance, and we are all left weakened and defenseless. They must pay for these transgressions. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Has justice been served?", ["rewardItems"] = { 181733 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 243, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60447] = { ["id"] = 60447, ["name"] = "Challenges in Maldraxxus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60447 }, ["description"] = "In Maldraxxus, the House of the Chosen have taken control of large swaths of land, upsetting the balance of power amongst the houses. To them flock the most seasoned gladiators and warriors. What better place to test yourself? Head into the land of bones and blood, and stand against their most powerful minions. Prove true what you know to be inside of yourself.", ["objectivesText"] = "Complete the Chosen Champions World Quest, the Theater of Pain Dungeon, or the Plaguefall Dungeon in Maldraxxus. Progress: Have you found the truth in courage?", ["rewardItems"] = { 181733 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 177, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60448] = { ["id"] = 60448, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1525, ["storyline"] = { 60448 }, ["description"] = "Those that have taken up arms against us in the name of Sire Denathrius and the Jailer have turned their backs on us all. Some are mere pawns in this game, others command them. Those that lead the charge of this crisis bear the greatest responsibility. They are the mightiest of Denathrius's allies, and they must be brought to justice. I accuse these souls of sins against the Shadowlands. Mete out justice in the name of Revendreth.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Has justice been served?", ["rewardItems"] = { 181557 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165291, ["x"] = 0.436, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.436, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 244, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60449] = { ["id"] = 60449, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60449 }, ["description"] = "I've never really trusted the Venthyr of Revendreth. Maybe it's those long coats they wear, or maybe it's those pointy teeth, but something about them creeps me out. Their leader, Denathrius, has sided with the Jailer against the rest of us, so I guess I was right. I want you to find his most powerful allies in Revendreth and smash them to a bloody pulp. Send him a message from Maldraxxus.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: You didn't let them bite you, right?", ["rewardItems"] = { 181557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 222, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60450] = { ["id"] = 60450, ["name"] = "Challenges in Revendreth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1707, ["storyline"] = { 60450 }, ["description"] = "Challenging oneself is a necessary part of ascension, for what is courage in the face of normalcy? In this current state of unrest, opportunities abound to prove ourselves. Consider it the gilded lining to a tarnished shield. None more so than in Revendreth, where Sire Denathrius has consolidated power and influence, and seeks to overthrow the natural order of the Shadowlands. And here is where you must challenge yourself today.", ["objectivesText"] = "Complete the Destroy the Dominant World Quest, the Sanguine Depths Dungeon, or the Halls of Atonement Dungeon in Revendreth. Progress: Have you proven your worth in Revendreth?", ["rewardItems"] = { 181557 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 178, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60452] = { ["id"] = 60452, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60452 }, ["description"] = "Oh no, no no no. The Jailer's taken all the souls, and now he's also got a whole lot of anima! Who knows what he's going to do with it! You need to go back there! You're the Maw Walker! See what you can learn of his power, and slow him down however you can. I believe in you! Be careful, ok?", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 262, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60454] = { ["id"] = 60454, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60454 }, ["description"] = "We have been able to do little to stem the flood of souls into the maw, until now. You, Maw Walker, have the power to put a stop to this. We know little about the Jailer's lands, save that he is powerful beyond imagining. I ask something of you today that I would not place upon anyone else. You must travel to his lands, and do what you can to slow the growth of his forces. We must buy more time.", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 263, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60455] = { ["id"] = 60455, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60455 }, ["description"] = "We cannot allow the Jailer to grow in power. You alone can take the battle to his lands, and you must do so, or we will all fall. Return to his lands, Maw Walker. He has already shown his hand, and we know he grows in power with each passing day. His forces must be slowed, make what progress you can.", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw. Progress: You seem different, somehow.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 265, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60456] = { ["id"] = 60456, ["name"] = "Storm the Maw", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60456 }, ["description"] = "We know little about the maw, Maw Walker. Only you have the power to traverse those lands and return. What I am about to ask of you I would not dare ask of another. We cannot allow the Jailer to grow in power. You must travel to the Maw and take the battle to his lands. Make what progress you can, we must slow down his forces however possible.", ["objectivesText"] = "Kill 3 rare or special encounter bosses in The Maw.", ["rewardXP"] = 6140, ["rewardItems"] = { 136350, 181476, 181557, 181733, 181741 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 267, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60457] = { ["id"] = 60457, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1701, ["storyline"] = { 60457 }, ["description"] = "So many souls that should have been nurtured here have been lost to the Maw, it pains me to think of it. Maw Walker, we ask you now to do that which we cannot. Traverse the Jailer's domain, walk his barren fields, climb his accursed tower. Bring us that which we lack.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you recovered the Anima Embers ?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1701, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 261, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60458] = { ["id"] = 60458, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 60458 }, ["description"] = "When we ferried souls to the Arbiter, we never thought this would happen. We watched in despair as they were cast into the Maw, one by one, then by the hundreds and thousands. Souls that have been devoured, consumed, their anima lost to us. Return to us what you can.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you secured the lost Anima Embers ?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160212, ["x"] = 0.67, ["y"] = 0.155 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.67, ["y"] = 0.155 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 260, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60459] = { ["id"] = 60459, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1698, ["storyline"] = { 60459 }, ["description"] = "The Arbiter has done us a great disservice. Our armies dwindle in number as souls are cast into the Maw instead of taking their place on the battlefields of Maldraxxus. The Undying Army must not be snuffed out. If the Shadowlands are to survive, we must be able to supply our troops. Travel now into the Maw, Maw Walker, and enter Torghast. Return with Anima Embers to help kindle our supplies.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you brought Anima Embers for our stockpiles?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 264, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60460] = { ["id"] = 60460, ["name"] = "Anima Salvage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 60460 }, ["description"] = "Revendreth is not a place that many souls choose to go, but it is a place that they must go. Here, their sins are laid bare before them, and they are broken and re-formed to function in our society. This is a necessary part of the cycle. Yet now, the cycle is broken, and are unable to serve our great purpose. In order for us to do our work we require Anima. Travel to Torghast, Maw Walker, gather that which we can not. Without it, we wither and fade.", ["objectivesText"] = "Gather 150 Anima Embers from Torghast, Tower of the Damned. Progress: Have you brought the Anima Embers to us?", ["rewardItems"] = { 181372, 181475, 181556, 181732, 184561 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 266, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60462] = { ["id"] = 60462, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1702, ["storyline"] = { 60462 }, ["description"] = "Maw Walker! The Anima Reservoir is nearly depleted. Without more anima, the groves shall soon wither and die. Search the realms for additional nourishment and deliver it to the sanctum. Ardenweald cannot continue without your aid!", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at the Heart of the Forest in Ardenweald.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 22, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1702, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 201, ["factionID"] = 0, ["bountySetID"] = 114 } } } },
[60463] = { ["id"] = 60463, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1700, ["storyline"] = { 60463 }, ["description"] = "Maw Walker! Our anima stores have run low, and soon we will have nothing to sate our thirst... Seek out additional sources of anima amongst the realms of the Shadowlands and deliver it to the sanctum. These are dire circumstances. Our fate is in your hands.", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at Sinfall in Revendreth.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 20, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1700, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 245, ["factionID"] = 0, ["bountySetID"] = 112 } } } },
[60464] = { ["id"] = 60464, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1698, ["storyline"] = { 60464 }, ["description"] = "Maw Walker! Our anima reserves are nearly depleted. Without an additional supply of anima, our mission of conquest will be lost! Scour the realms for all the anima you can gather and deliver it here to the sanctum. Victory depends on your success!", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at Seat of the Primus in Maldraxxus.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 19, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1698, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 223, ["factionID"] = 0, ["bountySetID"] = 113 } } } },
[60465] = { ["id"] = 60465, ["name"] = "Anima Appeal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = { "calling", "bounty" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1707, ["storyline"] = { 60465 }, ["description"] = "Maw Walker! Our supply of anima is dwindling and the reservoir is nearly depleted. We must replenish our reserves before it is too late! Search the realms for all the anima you can gather and deliver it to the sanctum. Time is short. Move swiftly, <class>.", ["objectivesText"] = "Deposit 600 anima in the Anima Reservoir at Elysian Hold in Bastion.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2DetailThemeID"] = 17, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1707, ["db2QuestInfoID"] = 271, ["db2QuestInfoName"] = "Calling Quest", ["worldSystems"] = { ["bounties"] = { { ["id"] = 179, ["factionID"] = 0, ["bountySetID"] = 111 } } } },
[60474] = { ["id"] = 60474, ["name"] = "Spawn Tracking Unit-Specified World Effect in a WMO Bug", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 60474 }, ["description"] = "There seems to be a bug when you setup a world effect containing a gold dot on the minimap through Spawn Tracking that is set to Unit, rather than Objective. It seems to only happen with spawns inside WMOs. Might also be happening with setting it to Object as well. If the Spawn Tracking on the World Effect is set to Objective, everything's fine. However, if it is set to Unit, the golden dot will not show up on the minimap.", ["objectivesText"] = "Attempt to figure out why the WMO spawned objective's minimap golden dot will not appear when its spawn tracking is set to Unit instead of Objective.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[60475] = { ["id"] = 60475, ["name"] = "We'll Workshop It", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1565, ["storyline"] = { 60475 }, ["objectivesText"] = "Deliver the supplies", ["rewardGold"] = 202200, ["rewardXP"] = 8165, ["rewardItems"] = { 178876, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Deliver the supplies", ["amount"] = 1, ["type"] = 0, ["objectID"] = 168568, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60482] = { ["id"] = 60482, ["name"] = "See With My Eyes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60482 }, ["description"] = "After the destruction of our house, the spiders in this area become increasingly hostile. They expand their domain, and prey upon the few survivors that live here. There are weapons we could use to help protect ourselves, but they lie hidden within the Sightless Hold, webbed over by the weavers that inhabit it now. Journey to the hold, use my sightless vision to see the weapons and recover what you can.", ["objectivesText"] = "Collect 10 hidden weapons Progress: Have you recovered the weapons.", ["rewardGold"] = 89550, ["rewardXP"] = 8165, ["rewardItems"] = { 178992, 178993, 181501, 181502, 181503, 181507, 181625, 181626, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181662, 181664, 181665, 181666, 181671, 181672, 181674, 181679, 181680, 181681, 181682, 181686, 181689, 181690, 181695, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[60500] = { ["id"] = 60500, ["name"] = "Halls of Atonement: Medallion of Pride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 60500 }, ["description"] = "Our attempts at a parley were met with skepticism, at best. Acquiring the medallions may take more work than originally intended. However, not all hope is lost. I do believe that we can win over many of the Harvesters, and for those we cannot, a more direct approach will need to be taken. Lord Chamberlain falls into this latter category. His medallion must be taken by force.", ["objectivesText"] = "Recover the Medallion of Pride from Lord Chamberlain within the Halls of Atonement. Progress: Have you recovered the medallion?", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 179024 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "dungeon" },
[60502] = { ["id"] = 60502, ["name"] = "Sanguine Depths: An Ally Within", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12842, ["mapID"] = 1525, ["storyline"] = { 60502 }, ["description"] = "There are whispers of a prisoner within these depths that may be of use to our cause. Whether this information can be relied upon is unknown. It is just as likely to be a trap, but still, we must investigate. We cannot afford to ignore an opportunity such as this. Venture into the Sanguine Depths and recover this valuable prisoner.", ["objectivesText"] = "Recover the valuable prisoner from within the Sanguine Depths.", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 181549 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168893, ["x"] = 0.26, ["y"] = 0.436 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.26, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 12842 } }, ["questType"] = "dungeon" },
[60505] = { ["id"] = 60505, ["name"] = "Spider's Lair", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60505 }, ["description"] = "When our house fell in ruins, Manipulator Zalisar seized the opportunity to reform the house under his leadership. He found few followers and soon vanished into the ruins nearby. He has begun to manipulate the spiders and train them to be his soldiers. Spiders under his control have begun to prey upon our forces. We need to deal with this threat before it grows any worse. I need you eliminate Manipulator Zalisar and his spider forces.", ["objectivesText"] = "Slay 8 Razorweb Weavers and Manipulator Zalisar .", ["rewardGold"] = 257400, ["rewardItems"] = { 181501, 181502, 181638, 181645, 181646, 181647, 181648, 181649, 181650, 181656, 181658, 181671, 181672, 181673, 181674, 181679, 181681, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168675, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
