[60622] = { ["id"] = 60622, ["name"] = "Eye of the Scryer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60622 }, ["description"] = "Evading the Mawsworn's scryers requires powerful magical countermeasures. The prime reagent? A luminescent eye, pried from the skull of a scryer recently shaken from its trance. The scrying ritual begins as we speak. You will, of course, be compensated only for an intact eye. Restraint is advised in its procurement.", ["objectivesText"] = "Obtain the Eye of the Scryer from Leerok the Scryer in The Maw . Progress: Well? Do you have it, undamaged?", ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883, 180035, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
