[60732] = { ["id"] = 60732, ["name"] = "Disrupting the Flow", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60732 }, ["description"] = "<The tortured embodiment of the soul before you burns with magmatic flame. Whatever purpose it was meant for here in the cauldron has since been served. The complete disregard for the remaining husk of this soul is unsettling. These efforts will continue if something isn't done. Send the inhabitants of Zovaal's Cauldron a message.>", ["objectivesText"] = "Disrupt the Mawsworn's efforts in Zovaal's Cauldron.", ["rewardGold"] = 309800, ["rewardXP"] = 2765, ["rewardItems"] = { 177698, 177699, 178874, 178877, 178880, 178881, 178882, 178883 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 176164, ["x"] = 0.394, ["y"] = 0.458 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.394, ["y"] = 0.458 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
