[60762] = { ["id"] = 60762, ["name"] = "Death Motes", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60762 }, ["description"] = "I have a task for you, Maw Walker. Souls deemed suitable for service among the Mawsworn are broken down to their barest essence. The resulting creature forms a black shade, devoid of all individual will. It is a tragic end. I wish to better understand this process--what is it about a soul that causes this transformation? Fragments of broken souls rain down across Ruin's Cradle. Bring me some of them, so that I might learn more about our common adversaries.", ["objectivesText"] = "Collect 10 Death Motes from Ruin's Cradle in The Maw .", ["rewardItems"] = { 177698, 178874, 178880, 178881, 178882, 178883, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[60765] = { ["id"] = 60765, ["name"] = "Cure For All Ills", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 60765 }, ["description"] = "Many survivors from the House of Plagues are still in need help. Their suffering fills me with great sadness. Maw Walker, I'd do anything to help them. Even saving a few is better than saving none. Please, help me cure them!", ["objectivesText"] = "Use Roseboil 's Regenerative Molt to cure 15 Plague-ridden Survivors .", ["rewardXP"] = 8165, ["rewardItems"] = { 178680, 182487, 182496, 182505, 182514, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 159241, ["x"] = 0.55, ["y"] = 0.68 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
