[60775] = { ["id"] = 60775, ["name"] = "A Suitable Demise", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 60775 }, ["description"] = "Surviving in this miserable place has been difficult, but I must confess... sending a few Mawsworn to a suitable demise does bring me joy. The soulforgers in Zovaal's Cauldron are among the cruelest minions the Jailer employs. I find satisfaction in disposing of their cores in the very forges which they maintain. This of course has the added benefit of temporarily slowing down their arms production, if you require more sober justification for your actions.", ["objectivesText"] = "Throw 5 Soulforged Cores into Soulforges in Zovaal's Cauldron in the Maw .", ["rewardItems"] = { 177698, 177699, 178874, 178880, 178881, 178882, 180280, 185717 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
