[60825] = { ["id"] = 60825, ["name"] = "Amateur Spies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 60825 }, ["objectivesText"] = "Progress: Your court is infested with spies, Maw Walker. Necromancers from Maldraxxus, amateurs hoping to ambush me while my guard is down. I will dispatch any that I come across, but I would prefer to focus my attentions on the court. Bring me the heads of shrouded necromancers to prove you have some competence in counterintelligence.", ["rewardItems"] = { 180296 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 168444, ["x"] = 0.512, ["y"] = 0.466667 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 168444, ["x"] = 0.512, ["y"] = 0.466667 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.466667 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
