[60887] = { ["id"] = 60887, ["name"] = "Cataclysm: Onward to Adventure in Kalimdor", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 1637, ["mapID"] = 85, ["storyline"] = { 27718, 27721, 27722, 28557, 28717, 60887 }, ["description"] = "There are people across Azeroth that could use your help, <name>. They come from different walks of life, but are all working towards finding their place on this beautiful world. Examine the Warchief's Command Board and see where your adventure awaits!", ["objectivesText"] = "Find the Warchief's Command Board in Orgrimmar. Progress: I cannot wait to hear your stories someday.", ["ends"] = { { ["mapID"] = 85, ["npcID"] = 172387, ["x"] = 0.493333, ["y"] = 0.765333 } }, ["coords"] = { ["mapID"] = 85, ["source"] = "quest_giver", ["x"] = 0.493333, ["y"] = 0.765333 }, ["mapCandidates"] = { ["npc"] = { 85 }, ["zone"] = { 1637 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1, ["db2PoiUiMapID"] = 85, ["questLines"] = { { ["id"] = 5580, ["name"] = "Cataclysm Chromie Time Breadcrumbs", ["orderIndex"] = 0, ["flags"] = 0 } } },
