[60930] = { ["id"] = 60930, ["name"] = "Lower Your Standards", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 60930 }, ["objectivesText"] = "Progress: < Picky Stefan leans in close and whispers.> Maw Walker, we are running low on refreshments! Thankfully, you chose to serve such a humble ... \"delicacy\" that we can find more just about anywhere. As you find fungus around the Ember Court, bring them to me and I shall have the dredgers sneak it onto the empty platters.", ["rewardItems"] = { 180470 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165500, ["x"] = 0.358923, ["y"] = 0.590615 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165500, ["x"] = 0.358923, ["y"] = 0.590615 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.358923, ["y"] = 0.590615 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[60945] = { ["id"] = 60945, ["name"] = "Deep Echo Trident", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60945 }, ["description"] = "<The trident glistens in the sunlight. This should give your soulbinds the ability to interrupt their foes in the Path of Ascension.>", ["objectivesText"] = "Bring the Deep Echo Trident to Paolone .", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171816, ["x"] = 0.628, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 181499 } },
[60946] = { ["id"] = 60946, ["name"] = "Blueprint: Deep Echo Trident", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60946 }, ["description"] = "<You have discovered plans for a trident that may give your soulbinds an edge in the Path of Ascension. Dactylis should be able to help you with crafting this piece of equipment.>", ["objectivesText"] = "Bring the Blueprint: Deep Echo Trident to Dactylis . Provided item:", ["rewardItems"] = { 178995, 179008, 179009, 179010, 179378, 180472, 180477, 180478, 180579 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 180472 } },
[60947] = { ["id"] = 60947, ["name"] = "Blueprint: Charm of Fortitude", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60947 }, ["description"] = "<You have discovered plans for a charm that seems to fortify your soulbinds in the Path of Ascension. Dactylis should be able to help you with crafting this charm.>", ["objectivesText"] = "Bring the Blueprint: Charm of Fortitude to Dactylis . Provided item:", ["rewardItems"] = { 180482 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 180482 } },
[60948] = { ["id"] = 60948, ["name"] = "RSVP: The Countess", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 60948 }, ["description"] = "The Prince wishes to host court? Well, that should be interesting... I am sure you understand that one musn't give without receiving something of value in return. It sets a terrible precedent, provides unrealistic expectations, and encourages beggars. So you shall do something for me. House Briarbane is very proud of their new mascot. They have been flaunting it in the streets and irritating the other houses. Steal it for me, but incriminate one of the other houses in the act.", ["objectivesText"] = "Disguise yourself as a member of House Iremoore and steal the House Briarbane mascot. Progress: It would be a shame to waste such a fine mascot on such an unworthy house.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176114, 180497 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 171106, ["x"] = 0.58, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 171106, ["x"] = 0.58, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.58, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[60955] = { ["id"] = 60955, ["name"] = "Noko's Flute", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 60955 }, ["objectivesText"] = "Progress: < Noko breathes in slowly.> The stage manager says he cannot find my flute anywhere. The last time this happened, one of the rowdy roadies had run off with it. You can find those troublesome dredgers causing trouble around the party. Retrieve my flute from them and I will play for your guests.", ["rewardItems"] = { 180484, 180485, 180486 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170874, ["x"] = 0.5355, ["y"] = 0.375 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170874, ["x"] = 0.5355, ["y"] = 0.375 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5355, ["y"] = 0.375 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[60957] = { ["id"] = 60957, ["name"] = "Ansel's Lucky Violin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 60957 }, ["objectivesText"] = "Progress: < Lucky Ansel reluctantly breaks gaze with his sinstone.> My burdens are still far too heavy. I will never be free of the Maw's dangers while even a single sin remains on this stone. Luckily, my exceptional music warrants praise from my venthyr controllers, and I am assured that aiding Prince Renathal's court is a worthwhile endeavor. Retrieve my violin from the band supplies over near the dancers and I will begin my public penance.", ["rewardItems"] = { 180484, 180485, 180486 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170881, ["x"] = 0.5352, ["y"] = 0.3684 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170881, ["x"] = 0.5352, ["y"] = 0.3684 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5352, ["y"] = 0.3684 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[60958] = { ["id"] = 60958, ["name"] = "We Send Only You", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60958 }, ["objectivesText"] = "House of Constructs forces disrupted", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "House of Constructs forces disrupted", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 0 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[60959] = { ["id"] = 60959, ["name"] = "Burning Crusade: Onward to Adventure in Outland", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 111, ["storyline"] = { 28708, 39181, 39188, 39197, 39199, 39202, 49550, 60120, 60959 }, ["description"] = "The harsh remains of Outland will test the strength of even the hardiest adventurers like yourself. Find your way back there and continue your adventure!", ["objectivesText"] = "Travel to the shattered world of Outland.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2PoiMapID"] = 530, ["db2PoiUiMapID"] = 111, ["questLines"] = { { ["id"] = 5577, ["name"] = "Burning Crusade Chromie Time Breadcrumbs", ["orderIndex"] = 1, ["flags"] = 0 } } },
[60960] = { ["id"] = 60960, ["name"] = "Chiu's Lute", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 60960 }, ["objectivesText"] = "Progress: I am nervous, <name>. Music lays bare my soul for all to see. And while this sinstone reminds all of the darkness within me, I hope that my music will expose the light that also dwells within. Lord Garridan at your embassy agreed. He as most kind and enjoyed the music I played for him when I first arrived. I must've left my lute with him. Please retrieve it for me while I continue my pre-show meditation.", ["rewardItems"] = { 180484, 180485, 180486 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 170878, ["x"] = 0.5336, ["y"] = 0.362 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 170878, ["x"] = 0.5336, ["y"] = 0.362 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.5336, ["y"] = 0.362 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
