[60973] = { ["id"] = 60973, ["name"] = "Blueprint: Phial of Serenity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60973 }, ["description"] = "<You have discovered plans for a phial that may give your soulbinds an edge in the Path of Ascension. Dactylis should be able to help you with crafting this piece of equipment.>", ["objectivesText"] = "Bring the Blueprint: Phial of Serenity to Dactylis . Provided item:", ["rewardItems"] = { 180495 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 180495 } },
[60974] = { ["id"] = 60974, ["name"] = "Phial of Serenity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 60974 }, ["description"] = "<Your steward friend gave you an extra bottle to store this potion in. This should keep your soulbinds fighting in the Path of Ascension, as your phial does.>", ["objectivesText"] = "Bring the Phial of Serenity to Paolone .", ["rewardGold"] = 16980, ["rewardXP"] = 1020, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171816, ["x"] = 0.628, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 184478 } },
