[61129] = { ["id"] = 61129, ["name"] = "RSVP: Droman Aliothe", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61129 }, ["description"] = "I serve my Queen and abide by my oath to guard this hollow and tend the spirits it encloses. Once, I might have enjoyed your Prince's party, but I am no longer suited to revelry. My world was destroyed long ago, and perhaps I have lost the joy I felt as its wild guardian. I would dearly like a reminder of my old home. I have heard those strange traders, the brokers, have unusual objects from other worlds. Perhaps they have something from mine?", ["objectivesText"] = "Investigate the offers of the Brokers to see whether a remnant of Aliothe's world may be found. Progress: Have you found a reminder of my home for me?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171828, 176121, 179315, 180774, 180969, 180970, 180971, 180972, 180973 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61130] = { ["id"] = 61130, ["name"] = "RSVP: Sika", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61130 }, ["description"] = "Hello, <name>! Sika like to help. So much to do. Would go to Ember Court, but too many things only Sika can do. Very sorry.", ["objectivesText"] = "Find others in Olympic Village to take on Sika 's tasks so she can attend the Ember Court. Progress: Busy, busy. Too busy. No one else can do all the things.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176125, 180965, 180966, 180967, 180968 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 166577, ["x"] = 0.526, ["y"] = 0.826 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.526, ["y"] = 0.826 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
