[61141] = { ["id"] = 61141, ["name"] = "Deathfang's Favorite Toy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61141 }, ["objectivesText"] = "Throwin' Skull found Play with Deathfang", ["rewardXP"] = 8165, ["rewardItems"] = { 180810, 180811 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Throwin' Skull found", ["amount"] = 1, ["type"] = 0, ["objectID"] = 166274, ["orderIndex"] = 0 }, { ["text"] = "Play with Deathfang", ["amount"] = 5, ["type"] = 0, ["objectID"] = 171591, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61146] = { ["id"] = 61146, ["name"] = "Manifesting Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61146 }, ["description"] = "As you know, shedding our memories of life can result in dangerous creatures known as manifestations. They have increased in number and strength as of late, but I believe we can find use for them yet. Manifestations carry great power within them--power we may purify and use in our own creations at the forge here. In making something positive out of such negativity, we do a noble act of service. Simply eliminate any you come across, and collect their essence. That is all.", ["objectivesText"] = "Collect 15 Condensed Essence from manifestations. Progress: Be cautious in your travels. Manifestations are no simple foe.", ["rewardXP"] = 8165, ["rewardItems"] = { 180785, 181368, 181377, 181581, 181609, 181614, 181627, 181637, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61148] = { ["id"] = 61148, ["name"] = "AHHH! Real Monsters!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61148 }, ["objectivesText"] = "Enter a Rift Exit the Rift", ["rewardXP"] = 8165, ["rewardItems"] = { 180789 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Enter a Rift", ["amount"] = 1, ["type"] = 0, ["objectID"] = 171514, ["orderIndex"] = 1 }, { ["text"] = "Exit the Rift", ["amount"] = 1, ["type"] = 0, ["objectID"] = 171829, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61156] = { ["id"] = 61156, ["name"] = "Where There's a Quill...", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61156 }, ["description"] = "In times long past, Aspirants trained against the fauna of Bastion. The creation of the Centurions rendered such unstructured progression obsolete. The many flying denizens of this realm are known for their quills. They are light and sturdy, perfect for our purposes. Gather all that you can, please. Any flying creature shall suffice.", ["objectivesText"] = "Collect 30 Shimmerflight Quills from flying beasts. Progress: Have you the quills?", ["rewardXP"] = 8165, ["rewardItems"] = { 175967, 180536, 180796, 181368, 181377, 181629, 181631, 181632, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184841, 184842 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171676, ["x"] = 0.504, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171676, ["x"] = 0.504, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61157] = { ["id"] = 61157, ["name"] = "Straight to the Point", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61157 }, ["description"] = "The horned beasts of Bastion were once commonly used in aspirant training, but centurion sparring units have mostly taken their place. Over the past few eons, their numbers have grown and now must be culled. Their horns are critical components to our work. Many specimens are broken from use in battle--they will not suffice. You must be careful in collecting them. Face them, defeat them, and bring back their horns.", ["objectivesText"] = "Collect 12 Elysian Horns from horned beasts. Progress: We require as many horns as you are able to procure.", ["rewardXP"] = 8165, ["rewardItems"] = { 180809, 181368, 181377, 181577, 181605, 181606, 181609, 181611, 181612, 181702, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171676, ["x"] = 0.504, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171676, ["x"] = 0.504, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61159] = { ["id"] = 61159, ["name"] = "Signs of Demise", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61159 }, ["description"] = "All members of the Forsworn carry an insignia on their person at all times. We suspect they are imbued with the power of the Temple of Loyalty, bolstering their strength against us. Collect these insignias from their deceased forms. Strip them of this power, and we shall put it to better use in our own machinations. Such is the Archon's will, as it is ours.", ["objectivesText"] = "Collect 20 Forsworn Insignias from Forsworn kyrian. Progress: Each insignia is a shift of power in our favor.", ["rewardXP"] = 8165, ["rewardItems"] = { 180816, 181368, 181377, 181571, 181578, 181606, 181608, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184842 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171676, ["x"] = 0.504, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171676, ["x"] = 0.504, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
