[61166] = { ["id"] = 61166, ["name"] = "Reduce, Reuse, Recycle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61166 }, ["description"] = "Centurions need lots of parts. But so do we! Kofi needs their metal. Can be from Centurions or the ground. Your choice! Not too damaged, ok? Hard to clean!", ["objectivesText"] = "Collect 20 Resonant Alloy from Forsworn centurions or Centurion parts. Progress: You have metal?", ["rewardXP"] = 8165, ["rewardItems"] = { 180830, 181368, 181377, 181585, 181605, 181610, 181611, 181703, 181704, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184841 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61173] = { ["id"] = 61173, ["name"] = "RSVP: Mikanikos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61173 }, ["description"] = "Ember Court sounds interesting ... but very busy right now! Forsworn got into my supplies. Now everything jumbled and disorganized. Can't work in these conditions. My workshop isn't right! Help me! Get parts. Most will be damaged and you don't know how to tell about flaws. Bring me many to examine. I will find perfect part.", ["objectivesText"] = "Assist Mikanikos by gathering potentially perfect parts so he can finish his construction and attend the Ember Court. Progress: Have my parts?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176113, 180895, 182114 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171647, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171647, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[61174] = { ["id"] = 61174, ["name"] = "RSVP: Baroness Vashj", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61174 }, ["description"] = "I am no stranger to courts, Maw Walker. Having attended on Queen Azshara herself, and then later serving my Lord Illidan. That does not mean, however, that I accept every invitation I receive. < Baroness Vashj smirks.> Impress me with your strength, $p, and I will believe Prince Renathal has power that is worth my time.", ["objectivesText"] = "Gather the heads of fearsome foes to present to Baroness Vashj . Progress: Where are the heads of your enemies?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176097, 180846, 180848, 180849, 180850 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 162487, ["x"] = 0.676, ["y"] = 0.46 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.676, ["y"] = 0.46 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61179] = { ["id"] = 61179, ["name"] = "Forge Ahead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61179 }, ["description"] = "The Eternal Forge has anima again? Ah! Yes! So exciting! You must go. Find Forgelite Selene . She will help! So much to make!", ["objectivesText"] = "Speak to Forgelite Selene at the Eternal Forge.", ["rewardGold"] = 274800, ["rewardXP"] = 8165, ["rewardItems"] = { 94219, 94220, 211279 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61182] = { ["id"] = 61182, ["name"] = "Pollen Your Weight", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61182 }, ["description"] = "You know Twirlpetal flowers?! They spin around in the light! We need pollen. Only pollen if in bloom! Get a bunch! Flowers in golden fields. And they spin! Round and round!", ["objectivesText"] = "Collect 30 Twirlpetal Pollen in Bastion's plains. Progress: Pollen very fragile. Won't last long!", ["rewardXP"] = 8165, ["rewardItems"] = { 180851, 180897, 181368, 181377, 181605, 181606, 181609, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184841, 184842 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61189] = { ["id"] = 61189, ["name"] = "Further Gelatinous Research", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61189 }, ["objectivesText"] = "Accumulator Acquired Slime gathered", ["rewardXP"] = 8165, ["rewardItems"] = { 180876 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11462 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Accumulator Acquired", ["amount"] = 1, ["type"] = 0, ["objectID"] = 171747, ["orderIndex"] = 0 }, { ["text"] = "Slime gathered", ["amount"] = 30, ["type"] = 0, ["objectID"] = 171746, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61193] = { ["id"] = 61193, ["name"] = "A Light Touch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61193 }, ["description"] = "Need Firstborne's Light ! You know? Named after Archon! Always in water. Kofi 's favorite! Shine big light when grown. And go to shore! Easy to see!", ["objectivesText"] = "Collect 15 Firstborne's Light in water sources. Progress: Only grown flowers! Little ones won't work.", ["rewardGold"] = 30900, ["rewardXP"] = 8165, ["rewardItems"] = { 180897, 181368, 181377, 181612, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184842 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61196] = { ["id"] = 61196, ["name"] = "The Secret Ingredient", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61196 }, ["description"] = "At times, even the most seasoned kyrian may have difficulty meditating. Recently, such problems have become increasingly common. There is a special draught crafted from our purest waters that can be used to focus the mind. I believe it may prove useful in our work here as well, perhaps as a catalyst for more potent reactions. Will you gather some? Move swiftly, for the liquid becomes unstable once removed from our sacred pools.", ["objectivesText"] = "Collect 10 Ephemeral Draught . Progress: Were you able to find the draught?", ["rewardGold"] = 549600, ["rewardXP"] = 8165, ["rewardItems"] = { 180898, 181368, 181377, 181583, 181601, 181610, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840, 184841, 184842 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61199] = { ["id"] = 61199, ["name"] = "Arms Day", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61199 }, ["description"] = "Many battles here. Especially lately! Now weapons all over. Too many. We can use! Go to big battle places and grab them. We will use better!", ["objectivesText"] = "Collect 20 Blessed Armaments from battlefields. Progress: Careful with the pointy end!", ["rewardXP"] = 8165, ["rewardItems"] = { 180946, 181368, 181377, 181599, 181609, 181610, 181629, 181632, 181636, 181703, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171671, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61209] = { ["id"] = 61209, ["name"] = "A Somber Melody", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61209 }, ["description"] = "Though we kyrian cease to be should we perish in battle here, there is much power within Bastion itself that can call forth echoes of our former brothers and sisters. These memories wander the roads. At times, they take on some purpose they served in their eternity here--crafting goods, guarding our sacred grounds, and the like. Take my lyre. Its ancient melody will dispel the memories, and in the process charge it with the residual energy of our realm.", ["objectivesText"] = "Dissipate 15 Kyrian memories along the roads of Bastion.", ["rewardXP"] = 8165, ["rewardItems"] = { 180990, 181368, 181377, 181570, 181578, 181581, 181589, 181594, 181599, 181606, 181609, 181614, 181635, 181745, 184294, 184362, 184363, 184765, 184766, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171677, ["x"] = 0.502, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.502, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61220] = { ["id"] = 61220, ["name"] = "AHHH! Real Monsters!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61220 }, ["objectivesText"] = "Assist Aspirant Thetes Repel the Devourer threat Helpless Aspirant rescued", ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10534 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Assist Aspirant Thetes", ["amount"] = 1, ["type"] = 0, ["objectID"] = 171834, ["orderIndex"] = 0 }, { ["text"] = "Repel the Devourer threat", ["amount"] = 1, ["type"] = 15, ["objectID"] = 0, ["orderIndex"] = 1 }, { ["text"] = "Helpless Aspirant rescued", ["amount"] = 40, ["type"] = 0, ["objectID"] = 162685, ["orderIndex"] = 6 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest" },
[61255] = { ["id"] = 61255, ["name"] = "RSVP: Alexandros Mograine", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61255 }, ["description"] = "It would be an honor to represent Maldraxxus at the Ember Court of Prince Renathal. But before I leave my post, I must ensure my comrades will be safe while I am away. Fight your way into the Ossein Foundry and retrieve weapons from our rivals there. I will have them distributed among the troops while I make ready to depart.", ["objectivesText"] = "Collect 9 Ossein Staves and 3 Ossein Battleaxes from the Ossein Foundry. Progress: Have you gotten the weapons yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176115, 181160, 181161 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 171933, ["x"] = 0.504, ["y"] = 0.675 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 171933, ["x"] = 0.504, ["y"] = 0.675 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.504, ["y"] = 0.675 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61256] = { ["id"] = 61256, ["name"] = "RSVP: Kleia and Pelagos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61256 }, ["description"] = "Oh, how wonderful! Thank you for the invitation to the Ember Court. We were just going to go cleanse ourselves with a meditation. That will be even more necessary if we are to travel soon. Care to join us?", ["objectivesText"] = "Join Kleia and Pelagos in the Meditation chamber and face the memories of your past. Progress: Have you completed your meditation yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176123, 180062 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 174916, ["x"] = 0.558, ["y"] = 0.864 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 171951, ["x"] = 0.581, ["y"] = 0.868 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.864 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[61265] = { ["id"] = 61265, ["name"] = "Blueprint: Charm of Alacrity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61265 }, ["description"] = "<You have discovered plans for a charm that seems to hasten your soulbinds in the Path of Ascension. Dactylis should be able to help you with crafting this charm.>", ["objectivesText"] = "Bring the Blueprint: Charm of Alacrity to Dactylis.", ["rewardItems"] = { 181139 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 181139 } },
