[61354] = { ["id"] = 61354, ["name"] = "RSVP: Lady Moonberry", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61354 }, ["description"] = "Of course I will attend, <name>, the Ember Court sounds like a lot of fun! But I cannot go without a gift! Hospitality gifts are an important tradition on many worlds and I feel obliged to provide something suitable for my host and fellow guests. < Lady Moonberry suppresses a smirk.> Now for reasons that I'm suuuure won't interest you, I'll need a stout but pretty vine, some dangerous but beautiful blossoms, and of course some gorm pheromones. Easy enough for someone of your prowess.", ["objectivesText"] = "Collect 3 Silverheart Vine Leaves , 9 Blooming Lasher Spurs , and a Gorm Pheromone Gland . Progress: Have you found all of the components for my gift?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176112, 181250, 181251, 181252 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172098, ["x"] = 0.49, ["y"] = 0.51 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172098, ["x"] = 0.49, ["y"] = 0.51 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.49, ["y"] = 0.51 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
[61356] = { ["id"] = 61356, ["name"] = "Echthra, Dame of Hatred", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61356 }, ["objectivesText"] = "Progress: We have made contact with a member of the former House of Eyes in Maldraxxus. She is a powerful marksman who would prove a most worthy adversary for your soulbinds. She has requested a special anointment oil used in kyrian ceremonies in return for her memory.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181273, 181701 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61357] = { ["id"] = 61357, ["name"] = "Hatred Abated", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61357 }, ["series"] = { 61490 }, ["description"] = "As agreed, you may take my memory for the trials you seek. Heed this warning, mortal--even as an echo of my physical form I will attack without hesitation. Expect no mercy, for I will show none. You have done me a great service this day. See to your business.", ["objectivesText"] = "Capture Echthra 's memory.", ["rewardGold"] = 68950, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181273, 181701 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172515, ["x"] = 0.566, ["y"] = 0.116 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.116 }, ["mapCandidates"] = { ["npc"] = { 1533, 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[61358] = { ["id"] = 61358, ["name"] = "Alderyn and Myn'ir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61358 }, ["series"] = { 61360, 61963, 61965 }, ["objectivesText"] = "Progress: The Wild Hunt is made up of trackers and hunters of incredible might who protect Ardenweald from forces that wish to bring ruin to the place of rest. We have reached out to a duo that has agreed to lend their memories if you help them take down a troublesome target.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181274, 182580 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61360] = { ["id"] = 61360, ["name"] = "The Hunt's Gratitude", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61360 }, ["series"] = { 61358, 61963, 61965 }, ["description"] = "The forests of Ardenweald are safer with your help, envoy of the kyrian. As a reward for your aid, we shall allow you to capture our memory. It is an honor to be chosen to help train the mighty warriors of Bastion. Whenever you are ready.", ["objectivesText"] = "Capture Alderyn and Myn'ir 's memories.", ["rewardGold"] = 241020, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181274, 182580 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173403, ["x"] = 0.518, ["y"] = 0.788 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.518, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[61361] = { ["id"] = 61361, ["name"] = "Nuuminuuru", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61361 }, ["series"] = { 61362, 62218, 62219 }, ["objectivesText"] = "Progress: The tirnenn of Ardenweald are ancient, mysterious fae with many lessons to teach. While they prefer to avoid conflict and battle, they are powerful foes if crossed. One tirnenn has offered themself as a teacher for your soulbinds. Along with their fleet of faeries, they have many nontraditional, yet crucial, lessons to teach you.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179378, 181275 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61362] = { ["id"] = 61362, ["name"] = "Caretaker of Faeries", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61362 }, ["series"] = { 61361, 62218, 62219 }, ["description"] = "Tirnenn and faeries hold many dissimilarities. While tirnenn stand patient and calm, like the trees that grow tall and protect us, faeries dance and dart and declare their desires directly. Despite these differences, we stand together. Learning, growing, evolving. We will help you and yours achieve the same symbiotic serenity.", ["objectivesText"] = "Capture Nuuminuuru 's memory.", ["rewardGold"] = 309800, ["rewardItems"] = { 182969 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173710, ["x"] = 0.514, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[61363] = { ["id"] = 61363, ["name"] = "Mad Mortimer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61363 }, ["objectivesText"] = "Progress: An alchemist in Maldraxxus swears that his new creation will be revolutionary, but is still missing a key catalyst. If we lend him aid, he has agreed to allow you to capture his memory for the Path.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179378, 181276 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61364] = { ["id"] = 61364, ["name"] = "Oozing with Opportunity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61364 }, ["series"] = { 61436 }, ["description"] = "They called me mad! As a matter of fact, they still do! Ah, but none of them have the mental acuity of Doctor James Mortimus of the very much in-tact House of Plagues, nor his handsome smile! Fools! With the catalyst you have so kindly provided, dear...whatever you are...certainly not a kyrian... I digress! We shall get to whatever it is you wanted in a moment, for now is the time of SCIENCE! Come, come, let me show you the wondrous fruits of my labors!", ["objectivesText"] = "Aid Mad Mortimer in his experiment, then capture his memory using the Soul Mirror .", ["rewardXP"] = 8165, ["rewardItems"] = { 181460 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172141, ["x"] = 0.592, ["y"] = 0.72 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.592, ["y"] = 0.72 }, ["mapCandidates"] = { ["npc"] = { 1533, 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[61365] = { ["id"] = 61365, ["name"] = "Splinterbark Nightmare", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61365 }, ["objectivesText"] = "Progress: Drust ritualists have created a horrific creature that threatens our nearby allies in Ardenweald. If we can successfully clear a path to the creature and mark it with a Praetor Resonance Beacon , we can both capture its essence for the Path and ensure it does not bring harm to the fae realm.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179378, 181277 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61366] = { ["id"] = 61366, ["name"] = "Tactical Operation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61366 }, ["description"] = "Your target lies near the Oaken Assembly in Ardenweald on the Elder Strand. Take caution, for powerful drust forces lurk nearby. Once your target is in sight, activate the beacon and protect the praetors that arrive as they work to subdue the beast. You will only be able to capture its memory once it has been fully incapacitated. Make haste, and good luck. Follow the path.", ["objectivesText"] = "Activate the Praetor Resonance Beacon at the Splinterbark Nightmare at the Elder Strand in Ardenweald, protect the praetors, then capture the Splinterbark Nightmare's memory.", ["rewardGold"] = 257400, ["rewardItems"] = { 182467 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61367] = { ["id"] = 61367, ["name"] = "Thran'tiok", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61367 }, ["series"] = { 61368, 62052, 62053 }, ["objectivesText"] = "Progress: Maldraxxus is home to one of the most powerful types of anima wielders in the Shadowlands, the liches of the House of Rituals. Training against a lich would teach your soulbinds important lessons and tactics they can wield if they ever come face to face with a magic user with ill intent.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179378, 181278 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61368] = { ["id"] = 61368, ["name"] = "Filching Phylacteries", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61368 }, ["series"] = { 61367, 62052, 62053 }, ["description"] = "This phylactery holds the soul of Thran'tiok... her very essence. Be quick in whatever you need to do. I must get this piece of her soul away from here before she returns. Her paranoia shall truly be her end.", ["objectivesText"] = "Capture Thran'tiok's memory through the Phylactery of Pain.", ["rewardGold"] = 280900, ["rewardItems"] = { 182965 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 173495, ["x"] = 0.576, ["y"] = 0.416667 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.576, ["y"] = 0.416667 }, ["mapCandidates"] = { ["npc"] = { 1533, 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[61369] = { ["id"] = 61369, ["name"] = "Craven Corinth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61369 }, ["objectivesText"] = "Progress: One of Denathrius's former subjects, Craven Corinth, has been deemed too dangerous to roam free even in their light-bathed Ember Ward. His memory would be a perfect opponent in the coliseum. All we need is a key to free him from his prison.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179378, 181279 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61370] = { ["id"] = 61370, ["name"] = "No Other Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61370 }, ["description"] = "Corinth will not surrender his memory willingly. You must weaken him sufficiently before he will relent to the soul mirror 's energy. You will find him deep within the Desiccation in Revendreth, locked away among the other light-scarred venthyr. Once you free him, he will surely attack in his confused rage. Subdue him, and capture his memory. He may then roam free among his kind.", ["objectivesText"] = "Subdue Craven Corinth in the Desiccation in Revendreth, then capture his memory.", ["rewardGold"] = 257400, ["rewardItems"] = { 182479, 182623 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61371] = { ["id"] = 61371, ["name"] = "Athanos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61371 }, ["objectivesText"] = "Progress: For your final test in the Path, you must face an old friend from your first moments in this realm--Athanos. It has been many millenia since the mighty goliath stepped into the arena with his legendary spear, Humility's Guard . The blade was disassembled upon his departure, as is tradition. Should Athanos bear witness to Humility's Guard once more, I believe he can be convinced to enter the arena once more. We have the shattered spear, but require materials to reforge it.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179378, 181280 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61372] = { ["id"] = 61372, ["name"] = "Back to Him", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61372 }, ["series"] = { 61478 }, ["description"] = "Even with Humility's Guard in hand, if you are to convince Athanos to join the Path of Ascension once more then you must prove yourself a worthy adversary. Enter the ring and wield the spear against him. Even with its power you cannot hope to defeat him, but it should be able to parry his mighty stomp. Thwart his assault for long enough, and he will surely allow you to capture his memory.", ["objectivesText"] = "Block Athanos' Power Stomp 6 times, then capture his memory.", ["rewardGold"] = 257400, ["rewardXP"] = 50, ["rewardItems"] = { 23022, 30014, 30016, 30019, 32616, 32617, 32622, 36884, 36885, 36886, 36887, 37354, 37440, 37519, 37529, 38214, 44751, 53354, 53370, 53371, 57253, 57255, 59765, 59766, 59767, 60241, 61531, 61532, 61533, 61534, 61535, 61536, 63566, 63567, 63568, 63569, 63570, 63571, 63572, 63573, 69648, 82574, 82575, 82576, 82577, 82578, 116202, 118532, 131554, 131606, 131851, 131899, 134021, 138819, 138820, 138821, 138822, 138823, 138824, 138837, 181472, 181501, 181502, 181503, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181652, 181653, 181654, 181655, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181667, 181668, 181669, 181670, 181672, 181675, 181676, 181677, 181679, 181680, 181689, 181695, 184305, 184772, 184773, 184774, 184775, 184776, 194521, 195220, 204076, 204985, 205188, 211279, 237812, 241215, 258979, 260431, 260432 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 175295, ["x"] = 0.516, ["y"] = 0.808 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.516, ["y"] = 0.808 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61373] = { ["id"] = 61373, ["name"] = "Azaruux, the Realm Ender", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61373 }, ["description"] = "You must act at once! A devourer of incredible strength has opened a rift in the coliseum and even now threatens to consume it! What few fighters were present at the time struggle to keep the creature at bay. If this horror is not stopped, it will continue into the rest of the spires. You must take what anima you can in the area and subdue it. Once the threat has been negated, take this spare mirror and capture its memory so we may learn more of its kind for future encounters.", ["objectivesText"] = "Absorb anima to activate the Anima Confluxes to subdue Azaruux, then capture its memory. Progress: You must not delay!", ["rewardGold"] = 262100, ["rewardItems"] = { 181795 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61391] = { ["id"] = 61391, ["name"] = "The Eye of the Jailer", ["level"] = 55, ["requiredLevel"] = 55, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61391 }, ["series"] = { 58160, 60287, 60289, 61355, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "<The air around you stands still. A chill of domination suffuses your being. You hear a voice.> Yes... I remember you... Do you think that because you evaded my grasp once, that I would let it happen again? No. The Maw answers to me. All that befalls you here will be because I willed it so. Death comes for you, mortal. Everywhere you go, my eye is upon you.", ["objectivesText"] = "Speak with Ve'nari about what you just heard.", ["rewardGold"] = 30900, ["rewardXP"] = 935, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[61394] = { ["id"] = 61394, ["name"] = "Gormling Toss: Tranquil Pools", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61394 }, ["objectivesText"] = "Gormling in a Bag acquired Wayward Gormlings knocked down and bagged", ["rewardXP"] = 8165, ["rewardItems"] = { 181284, 182600 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "Gormling in a Bag acquired", ["amount"] = 1, ["type"] = 0, ["objectID"] = 172175, ["orderIndex"] = 0 }, { ["text"] = "Wayward Gormlings knocked down and bagged", ["amount"] = 8, ["type"] = 0, ["objectID"] = 168254, ["orderIndex"] = 1 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["db2WidgetSetID"] = 472 },
[61395] = { ["id"] = 61395, ["name"] = "Spare Parts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10472, ["storyline"] = { 61395 }, ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 24423, 24424, 24425, 57489, 57490, 57491, 131250, 131472 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10472 } }, ["questType"] = "standard" },
[61398] = { ["id"] = 61398, ["name"] = "Ember Court: Traditional", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61398 }, ["description"] = "Of course Darkhaven is honored to provide traditional decorations for Prince Renathal's court. Venthyr decor is all about setting a certain mood. That means lurking stonefiends and death blossom scented candles in vast quantity. Our resources are stretched thin, <name>. We can supply stonefiends easily, but our artisans need wax to melt with fresh death blossom . There should be candle remnants and drips in the village to scrape up. Death blossoms can be harvested from the plants themselves.", ["objectivesText"] = "Collect 50 Candle Wax and 20 Death Blossoms . Death Blossoms can be harvested with the herbalism skill. Progress: Have you managed to gather the raw materials for our artisans yet?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 169701, 172061, 176126, 181473 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61399] = { ["id"] = 61399, ["name"] = "Ember Court: Mortal Reminders", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1670, ["storyline"] = { 61399 }, ["description"] = "For a reasonable renumeration, Ta Cartel can supply the decorations you require. Restocking unique and intriguing items is an important aspect of doing business. As you can freely return to your own world, you can provide me some new and exciting products to offer. Your world has captured the imagination of many of our clients. I have buyers looking for some specific things native to Azeroth.", ["objectivesText"] = "Help Keeper Ta'saran replenish stock by retrieving the items on the list he's provided you. Progress: Have you found something that fits each item on the list?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173057, 176128, 181336, 181354, 181356, 181367 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670 },
[61400] = { ["id"] = 61400, ["name"] = "Ember Court: Mystery Mirrors", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61400 }, ["description"] = "I support Prince Renathal's efforts and will certainly help the Ember Court! Mystery mirrors will be dangerous but add real excitement to the party. I will need a lot of mirror fragments to complete enough of them in time. You will also need to refresh my supply of Ashen Cores so I can get the glass sufficiently molten to work.", ["objectivesText"] = "Collect 12 Shrouded Mirror Shards , 12 Scorched Mirror Fragments , and 3 Molten Cores. Progress: Have you found the mirror fragments and an Ashen Core ?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176127, 181519, 182097, 183912, 183919 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172986, ["x"] = 0.246, ["y"] = 0.504 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 172986, ["x"] = 0.246, ["y"] = 0.504 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.246, ["y"] = 0.504 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61401] = { ["id"] = 61401, ["name"] = "Ember Court: Venthyr Volunteers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61401 }, ["description"] = "Oh, hello again! Did you hear that I have been given command of the guard for the Ember Court? That would probably be more impressive if there were already recruits. I need to get these recruiting posters up. If you can take care of that, I can meet the interested recruits here and then we can test their combat skills when you return.", ["objectivesText"] = "Place 6 Recruiting Posters and test 3 Sinfall Recruits. Progress: Those posters need to be put in visible locations and the recruits need to be tested.", ["rewardGold"] = 208560, ["rewardXP"] = 8165, ["rewardItems"] = { 176138, 181716 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172614, ["x"] = 0.61, ["y"] = 0.395 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 172614, ["x"] = 0.61, ["y"] = 0.395 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.395 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61402] = { ["id"] = 61402, ["name"] = "Ember Court: Stoneborn Reserves", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61402 }, ["description"] = "To call up the reserves to provide security for the Ember Court we will need anima. Good, loyal troops are ready as soon as we can animate them. We will also need weapons for them. Sort that out and I will make sure the Prince and his guests are well protected.", ["objectivesText"] = "Fill the anima canister by defeating enemy stoneborn in Dominance Keep. Collect 12 Stoneborn Glaives . Progress: Have you filled the anima canister and found enough weapons to equip our new comrades?", ["rewardGold"] = 619600, ["rewardXP"] = 10205, ["rewardItems"] = { 176139, 181500 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 172502, ["x"] = 0.265, ["y"] = 0.292 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 172502, ["x"] = 0.265, ["y"] = 0.292 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.265, ["y"] = 0.292 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "group", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525, ["db2QuestInfoID"] = 1, ["db2QuestInfoName"] = "Group" },
[61403] = { ["id"] = 61403, ["name"] = "Ember Court: Maldraxxus Army", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61403 }, ["description"] = "So your prince's little parties have attracted unwanted attention? < Emeni laughs.> I have my own long list of enemies, and far too many of them hide from me in the land of the living. Cowards! But I have finally found a solution. Take this crystal to my remains on Azeroth, and use it to project my image among the living for a short time so that I may exact revenge on my old kin.", ["objectivesText"] = "Release Emeni 's projection in Vol'dun and help her defeat her ancient sethrak enemies. Progress: What are you waiting for? Those sethrak won't impale themselves.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176140, 181519, 181523 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172964, ["x"] = 0.542, ["y"] = 0.692 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172964, ["x"] = 0.542, ["y"] = 0.692 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.542, ["y"] = 0.692 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61405] = { ["id"] = 61405, ["name"] = "Ember Court: Divine Desserts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61405 }, ["description"] = "Recipes very important. Must not be lost! I learn new foods from many mortals, add to my book. Best way is taste some of thing so can know what is good. You teach recipe to me this way and bring me right ingredients so I cook too. Then taste yours, then taste mine. Helps me learn. I bring desserts to Ember Court. Fair, yes?", ["objectivesText"] = "Collect a sample of Banana Beef Pudding , 30 Aethereal Meat , and 20 Phantasmal Haunch . Then taste-test Stewart 's concoction. Progress: You ready to give ingredients and taste test?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172052, 172055, 172069, 176135 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 172448, ["x"] = 0.34, ["y"] = 0.665 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 172448, ["x"] = 0.34, ["y"] = 0.665 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.34, ["y"] = 0.665 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533 },
[61406] = { ["id"] = 61406, ["name"] = "Ember Court: Mushroom Surprise!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61406 }, ["description"] = "I had not realized the fame of my fungi had reached so far. I'd be delighted to provide a mushroom feast to the Ember Court! Hmmm... I will need you to collect some rare specimens and will loan you my favorite foraging bag. It will help you find the very best fungi. It's never failed me. Let's see, I need tiny lacy bells from Bastion and some of those Ardenweald fancy purple frills. From the very tops of our mushrooms here I will need the feather caps . You'll need to grapple your way up there.", ["objectivesText"] = "Collect 18 Feather Caps , 24 Lacy Bell Morels , and 4 Violet Frills . Progress: Have you filled the foraging bag?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176136, 181522, 181828, 181829, 181830, 181839 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 168429, ["x"] = 0.402, ["y"] = 0.412 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 168429, ["x"] = 0.402, ["y"] = 0.412 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.402, ["y"] = 0.412 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[61407] = { ["id"] = 61407, ["name"] = "Ember Court: Atoning Rituals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61407 }, ["description"] = "If Prince Renathal wishes to impart knowledge of Revendreth's highest calling to his guests, we would be honored to demonstrate the rituals of atonement. However, I must ask for your assistance preparing the necessary components quickly. Capture nearby fugitive souls that hide from the Lord Chamberlain's corrupt venthyr. Bring them to our avowed ritualists across the halls. They will prepare the souls for our purpose. Sinstone fragments will also help us identify the sins of these lost souls.", ["objectivesText"] = "Collect 125 Sinstone Fragments and deliver 2 Fugitive Souls to Avowed Ritualists. Progress: Fugitive souls can be found hiding in the darkest corners of the Halls of Atonement.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176130 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 167332, ["x"] = 0.718, ["y"] = 0.404 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.718, ["y"] = 0.404 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1525 },
[61408] = { ["id"] = 61408, ["name"] = "Ember Court: Glimpse of the Wilds", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 61408 }, ["description"] = "It would be wonderful to show Revendreth the wild creatures of Ardenweald! You can get some Radiant Groupers near the waterfalls. They're fast so you have to grab them as they swim by. Here's a net to use to subdue the Territorial Waders. They should follow you once you've caught them. Highland Runestags will let you ride them if you aren't aggressive. Bring a few here to me, please. Watch out for the bulls, they're not at all friendly. We will get others to help too. This sounds like fun.", ["objectivesText"] = "Bring 3 Highland Runestags, 8 Radiant Groupers and 4 subdued Territorial Waders to Niya . Progress: We need Radiant Groupers, Highland Runestags, and Territorial Waders please.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 168417, 176131, 183944 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 172352, ["x"] = 0.562, ["y"] = 0.556 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172352, ["x"] = 0.562, ["y"] = 0.556 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.562, ["y"] = 0.556 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1565 },
