[61478] = { ["id"] = 61478, ["name"] = "Humble Beginnings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 61478 }, ["series"] = { 61372 }, ["description"] = "With Humility's Guard whole once more, you may be able to coax Athanos back into the arena. Travel to Aspirant's Crucible, where your journey began so long ago. Seek Forgelite Sophone --she guides all those who seek an encounter with Athanos. Present the spear to her. She will know your intent and instruct you further.", ["objectivesText"] = "Bring Humility's Guard to Forgelite Sophone in Aspirant's Crucible. Progress: What is that you have there?", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 181471, 237812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 175295, ["x"] = 0.516, ["y"] = 0.808 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[61489] = { ["id"] = 61489, ["name"] = "Of Hearsay and Heresy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 61489 }, ["description"] = "Echthra has taken residence in one of the few remaining structures in the former House of Eyes in Maldraxxus. Bring the anointment oil to her, and she should allow you to capture her memory. Take caution, for she is well-known both as a master marksman and--perhaps more notably--for her quick trigger finger. Good luck, Maw Walker.", ["objectivesText"] = "Find Echthra in the House of Eyes in Maldraxxus. Progress: Be cautious. There are many in the House of Eyes who would not tolerate your presence.", ["rewardGold"] = 257400, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181273, 181701, 181706 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172515, ["x"] = 0.566, ["y"] = 0.116 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533, 1536 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[61490] = { ["id"] = 61490, ["name"] = "War of Information", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61490 }, ["series"] = { 61357 }, ["description"] = "Ah, the anointment oil. I had expected one of Adrestes' recruits. No matter. You seek my memory for your trials, yes? I am afraid mere oil will not suffice. With our house gone, we are left to fend for ourselves. Though this tower offers some protection, we are left cornered to any who may desire our end. Information is the key to survival. Use my anointed talisman to give me eyes across all the realms...even in Bastion. Follow the list precisely--no questions. Then can we resolve payment.", ["objectivesText"] = "Place Eyes of Hatred in the House of Rituals in Maldraxxus, Eonian Archives in Bastion, Tirna Vaal in Ardenweald, and Castle Nathria in Revendreth. Progress: There will be no negotiation in this matter.", ["rewardGold"] = 257400, ["rewardItems"] = { 178995, 179378, 180477, 180478, 180594, 180595, 181273, 181683, 181699, 181701 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 172515, ["x"] = 0.566, ["y"] = 0.116 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 172515, ["x"] = 0.566, ["y"] = 0.116 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.566, ["y"] = 0.116 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[61509] = { ["id"] = 61509, ["name"] = "Shinies of Bastion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61509 }, ["description"] = "Chordy is bored, boooored! You want to go look for luckydos? Go on adventure with Chordy ? We go to land of wing people, go look for valuable luckydos there. Ready?", ["objectivesText"] = "Use Chordy to locate and collect 10 valuable salvage around Bastion. Progress: Did we find anything good?", ["rewardXP"] = 8165, ["rewardItems"] = { 174101, 178554, 182489, 182498, 182507, 182516, 183744, 183804, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 161270, ["x"] = 0.55, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
