[61635] = { ["id"] = 61635, ["name"] = "Troubled Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61635 }, ["description"] = "News of our work here has spread, new souls have arrived seeking to join us! Take their requests for new construct bodies. We'll see if we can build them new constructs too!", ["objectivesText"] = "Take the construct requests from the souls present.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[61637] = { ["id"] = 61637, ["name"] = "Unity", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 61637 }, ["description"] = "A unique construct has chosen to join us, but its unethical creation leaves it most unsettled. The fusing of fragmented Kyrian souls within this construct, gives it pain and suffering. We must find a way to harmonize these souls so they can live together in peace. Create the Bindings of Wellbeing and bring ease to the Soulfused Construct.", ["objectivesText"] = "Bring ease to the Soulfused Construct. Progress: Have you helped this construct?", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 182074, 183717 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.55, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
