[61725] = { ["id"] = 61725, ["name"] = "Stolen Mementos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 61725 }, ["objectivesText"] = "Progress: I anticipate the timely return of our stolen merchandise, Maw Walker. Their pilfering leaves a blemish on what could otherwise be a perfectly satisfying event.", ["rewardItems"] = { 182186 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 171449, ["x"] = 0.425, ["y"] = 0.736 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 171449, ["x"] = 0.425, ["y"] = 0.736 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.425, ["y"] = 0.736 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
