[61842] = { ["id"] = 61842, ["name"] = "Vineroot Will Not Do", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 61842 }, ["description"] = "<Clearly bigger, the gorger looks at a vineroot you point to and you can see the hint of menace in its eye at being offered the root again. It looks longingly at the devourer mites nearby.>", ["objectivesText"] = "Collect Infused Endmire Fruit . Progress: Collect Infused Endmire Fruit from the Devourer Mites in the Endmire or Banewood.", ["rewardXP"] = 4085, ["rewardItems"] = { 182315, 182592 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[61845] = { ["id"] = 61845, ["name"] = "Edict of Doom: Devourers", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61845 }, ["description"] = "The infusion of anima within Revendreth has led to a resurgence in devourer infestations. These eaters of the world must be slain. By order of Prince Renathal and the rightful Court of Harvesters, this edict decrees the doom upon these aberrations. Complete this quota of destruction within Revendreth and receive a reward equal to your efforts.", ["objectivesText"] = "Destroy 20 Devourers in Revendreth.", ["rewardItems"] = { 181183, 181184, 181196, 181199, 181200, 181201, 181202, 181211, 181212, 181215, 181217, 181218, 181545, 181546, 181547, 181548, 181550, 181708, 184147, 184150, 184777, 185854 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173248, ["x"] = 0.716, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61846] = { ["id"] = 61846, ["name"] = "Edict of Doom: Dredbats", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61846 }, ["description"] = "The recent suffusion of anima in the region has led to an increase in dredbats being animated far and above any intended volume. By order of Prince Renathal and the true Court of Harvesters an edict of doom is declared on dredbats within Revendreth. Avoid those used for transport or assigned to specific duties, but slay any in the less tamed regions of the realm and a reward shall be proffered.", ["objectivesText"] = "Destroy 25 Dredbats in Revendreth. Progress: Maw Walker?", ["rewardItems"] = { 181175, 181176, 181180, 181181, 181185, 181194, 181197, 181199, 181200, 181201, 181202, 181203, 181204, 181205, 181206, 181217, 181218, 181545, 181546, 181547, 181548, 181550, 184147, 184150, 184777, 185854, 185942 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173248, ["x"] = 0.716, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61847] = { ["id"] = 61847, ["name"] = "Overdue Purging", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61847 }, ["description"] = "There are many duties of a stoneborn that have been forsaken by the plans of Denathrius. One such duty is the elimination of manifestations. The process venthyr use to extract anima from souls is not clean, and often leads to unresolved issues made manifest. These entities are dangerous if left unchecked, and increase in number thanks to your revivication of anima to these droughted lands. While you patrol Revendreth, destroy any manifestations you encounter and I shall provide you recompense.", ["objectivesText"] = "Destroy 30 Manifestations in Revendreth.", ["rewardItems"] = { 181175, 181176, 181177, 181185, 181192, 181194, 181196, 181198, 181200, 181203, 181206, 181217, 181218, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 184147, 184150, 184777, 185854, 185942 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173087, ["x"] = 0.715, ["y"] = 0.762 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173087, ["x"] = 0.715, ["y"] = 0.762 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.715, ["y"] = 0.762 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61848] = { ["id"] = 61848, ["name"] = "Edict of Doom: Sinstone Golems", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61848 }, ["description"] = "By order of the true Court of Harvesters an edict of doom is issued for any Sinstone Golems that have coalesced into dangerous sizes within the realm. These entities are the manifestation of unresolved sins of those souls who failed their redemption and were condemned to the Maw. With the recent suffusion of anima to the region they have grown dangerously strong. Expunge them from existence and recompense shall be provided.", ["objectivesText"] = "Destroy 4 Sinstone Golems in Revendreth.", ["rewardItems"] = { 181175, 181177, 181178, 181179, 181180, 181183, 181185, 181191, 181195, 181196, 181197, 181199, 181200, 181202, 181211, 181217, 181218, 181334, 181545, 181546, 181547, 181548, 181550, 181708, 182724, 184147, 184150, 184777, 185942 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173248, ["x"] = 0.716, ["y"] = 0.768 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.768 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61849] = { ["id"] = 61849, ["name"] = "Take the Bite Out of 'Em", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61849 }, ["description"] = "Right. So you got a quota of venthyr you need offed and I got a mean need for some payback. See, you may not think it to look at me but 'em venthyr loooove to chew on me specifically. Not sure what dark habit followed them across the veil but I just was a squishy bag of indulgence for far too long. As you go about offin' 'em venthyr for your normal... motivations... I'd ask you to bring me a bunch of fangs off 'em you off, as it were. I'll pay for payback!", ["objectivesText"] = "Collect 40 Venthyr Fangs . Progress: I'm gettin' quite a collection goin'.", ["rewardItems"] = { 181178, 181180, 181195, 181196, 181197, 181198, 181199, 181201, 181204, 181206, 181218, 181545, 181546, 181547, 181548, 181550, 181708, 182692, 184147, 184150, 184777, 185942 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173630, ["x"] = 0.712, ["y"] = 0.744 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173630, ["x"] = 0.712, ["y"] = 0.744 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.712, ["y"] = 0.744 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61851] = { ["id"] = 61851, ["name"] = "Shades of Muck", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61851 }, ["series"] = { 61762, 61763, 61764, 62361, 62985 }, ["description"] = "Yeah, this here muck pool's got everythin' we need to make your dredger butler. We'll make this one special just for you. Made to specifications, as the fangs say. First up, you gotta choose its color. Us dredgers comes in all kind of different shades of muck. Take a peek at some me fellow dredgers and let me know what color we should dredge up for your butler. We can recolor a dredger after-the-fact, but it ain't pleasant. < Rendle shudders at the thought.>", ["objectivesText"] = "Look at nearby dredgers to see color options, and then tell Rendle which color you want. Progress: What color you thinkin' of?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 182298 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
