[61892] = { ["id"] = 61892, ["name"] = "Ember Court Ambassador", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61892 }, ["description"] = "Expanding your influence is quite simple. Find someone. Ask them what they want. Give it to them. Congratulations. You now have influence with them. If we wish to engage the other realms and win them over to our side, we must do the same on a larger scale. So go to the other realms. Give them what they want. Expand our influence.", ["objectivesText"] = "Complete World Quests across the Shadowlands.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181521, 181524, 182342, 182343 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165453, ["x"] = 0.285, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165453, ["x"] = 0.285, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.285, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
