[61895] = { ["id"] = 61895, ["name"] = "Ember Court Ambassador", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61895 }, ["description"] = "Expanding your influence is quite simple. Find someone. Ask them what they want. Give it to them. Congratulations. You now have influence with them. If we wish to engage the other realms and win them over to our side, we must do the same on a larger scale. So go to the other realms. Give them what they want. Expand our influence.", ["objectivesText"] = "Complete World Quests across the Shadowlands.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181521, 181524, 182342, 182343 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165453, ["x"] = 0.285, ["y"] = 0.41 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165453, ["x"] = 0.285, ["y"] = 0.41 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.285, ["y"] = 0.41 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61896] = { ["id"] = 61896, ["name"] = "Undercover Security", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61896 }, ["description"] = "Do you know why the venthyr carve stoneborn into different shapes? Because diversity in form allows for diversity in strategy. Our different shapes give us different purpose. We need a new shape to solidify our court defenses. With the right training and tools, venthyr guards could be hidden in plain sight--posed as greeters. Able to be among the guests without raising concerns, they'd be the first to respond to active threats.", ["objectivesText"] = "Collect The Everyday Assassin training guide from Maldraxxus and 20 Enchanted Trickster Dust from Ardenweald. Progress: Undercover guards? Interesting idea...", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181530, 182363, 182364 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61898] = { ["id"] = 61898, ["name"] = "Small Bites", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61898 }, ["description"] = "The reviews are in, $p. Our menu is too Revendreth-centric! All the best courts have exotic appetizers, small plates, and other specialties that guests can look forward to every time they come. And for a court like ours, which boasts frequent guests from other realms, we simply must do better! Do not worry, after tireless research, I have drafted a very particular list of ingredients for you to find me. Bring them to me, and I will serve our guests eternity on a platter!", ["objectivesText"] = "Collect cheeses from Bastion and Sourbread Yeast Starter from Maldraxxus. Progress: Are you sure Picky Stefan wanted ALL of these things?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181532, 182355, 182356, 182357, 182365 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61899] = { ["id"] = 61899, ["name"] = "Anima Tastings", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61899 }, ["description"] = "You started a trend, $p! Your constant gallivanting around the different realms of the Shadowlands has inspired a new flair for the exotic among Revendreth's elite. If it's from outside Revendreth, the venthyr want to try it. And I know just what the next big thing will be: anima tastings! Think about it: we--and by 'we' I mean 'you'--bring back fresh anima from all the different realms you travel to. Then socialites get to sip it and pretend it tastes like wherever you got it from!", ["objectivesText"] = "Collect fresh anima from Ardenweald, Bastion, Maldraxxus, and Revendreth. Progress: That's a whole lot of anima you got there. That's all just for drinking?", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181533, 182358, 182359, 182360, 182361 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165494, ["x"] = 0.306, ["y"] = 0.418 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.306, ["y"] = 0.418 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61900] = { ["id"] = 61900, ["name"] = "Comfy Chairs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61900 }, ["description"] = "I want guests to sit. Standing is hard. I know 'cause I stand a lot. Guest should sit and be comfy. I make comfy chairs for all guests to sit. Guests be happy, stay longer!", ["objectivesText"] = "Collect 30 Soft Vulpin Fur from Bastion and 30 Reclaimed Wood from Ardenweald. Progress: Boot knows his stuff. If he says we should make chairs, we should make chairs.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 181535, 182354, 182362 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 164966, ["x"] = 0.28, ["y"] = 0.43 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[61916] = { ["id"] = 61916, ["name"] = "Restock: Fire Damage", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 61916 }, ["objectivesText"] = "Progress: Decorations not ready! Last Ember Court, those big fires from candles burn all the tablecloths. Bring me pretty cloth and I make new tablecloths. Then we can pick decorations for next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173202 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165493, ["x"] = 0.298, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
