[62094] = { ["id"] = 62094, ["name"] = "Restock: Exploratory Meals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62094 }, ["objectivesText"] = "Progress: I suffer yet another crisis in the kitchen, Maw Walker! You may recall that an excess of gnats swarmed our last Ember Court. Although initially repulsed, I have begun to ponder if there might be some culinary value to these creatures. I would like to attempt a few meals with them. I shall require a few things to steel myself for the culinary adventure. After that, I shall happily discuss refreshment options for our next court.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 173060 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165490, ["x"] = 0.29, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.29, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62095] = { ["id"] = 62095, ["name"] = "Restock: Medic's Tent", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62095 }, ["objectivesText"] = "Progress: I have an urgent matter to discuss. While the volunteer portion of our security showed tremendous bravery at the last Ember Court, it was clear that they were unprepared for the rigors of battle. They suffered tremendous injuries. We need to resupply our medical team to be ready for the next court. After that is resolved, we can discuss security options for future Ember Courts.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171267, 173192 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
