[62104] = { ["id"] = 62104, ["name"] = "Restock: Stoneborn Reserves", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62104 }, ["objectivesText"] = "Progress: I have an urgent matter to discuss. At the last Ember Court, many of our stoneborn suffered fractures and cracked limbs while defending our guests. We will need to repair them. Bring me the stone, and I will coordinate the repairs with our dredgers. After that is resolved, we can discuss security options for future Ember Courts.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171841 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62105] = { ["id"] = 62105, ["name"] = "Restock: Unconventional Weapons", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62105 }, ["objectivesText"] = "Progress: I have an urgent matter to discuss. Fighting alongside the Maldraxxi forces at the last Ember Court inspired me to strategize outside of the typical boundaries of venthyr warfare. I am certain you mortals have developed creative weapons. Bring me some, so that I may learn them. After that is resolved, we can discuss security options for future Ember Courts.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172903, 172904 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62106] = { ["id"] = 62106, ["name"] = "Restock: Enchantments", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62106 }, ["objectivesText"] = "Progress: I have an urgent matter to discuss. The Stone Legion's surprise attack on our last Ember Court revealed that I have been far too lax in pursuing enchantments for our troops' equipment. We must use every advantage at our disposal. Bring me any enchantment you can spare. After that is resolved, we can discuss security options for future Ember Courts.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 172416 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62108] = { ["id"] = 62108, ["name"] = "Restock: Strategic Codices", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62108 }, ["objectivesText"] = "Progress: I have an urgent matter to discuss. At the last Ember Court, the devourer's ambush tactics caught our guards by surprise. Their portals opened all around us and we were too slow to respond. We should stock up on supplies that will allow us to adapt to changing circumstances. After that is resolved, we can discuss security options for future Ember Courts.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184090 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62109] = { ["id"] = 62109, ["name"] = "Restock: Surveillance Equipment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62109 }, ["objectivesText"] = "Progress: I have an urgent matter to discuss. As you are aware, a murder occurred at the last Ember Court. That is an unacceptable failing on my part and I apologize. I would like to acquire additional surveillance equipment to ensure we are prepared if it happens again. After that is resolved, we can discuss security options for future Ember Courts.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 171264, 171266 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165496, ["x"] = 0.32, ["y"] = 0.415 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.32, ["y"] = 0.415 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
