[62182] = { ["id"] = 62182, ["name"] = "A Letter From Nadja", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62182 }, ["description"] = "The letter is addressed to Nadja's contact Dimwiddle in Darkhaven. It is clearly sealed with Nadja's mark. It is certainly of great import, you should make sure the letter is delivered.", ["objectivesText"] = "Return the letter to Darkhaven. Provided item:", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 182726 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 165859, ["x"] = 0.608, ["y"] = 0.624 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.624 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["startItems"] = { 182726 } },
[62183] = { ["id"] = 62183, ["name"] = "A Leaking Box Marked Perishable", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62183 }, ["description"] = "A very exact entity wanted this package to reach Ta'tru at the Night Market. It looks like Broker script. The package is clearly leaking, and it is marked perishable. Perhaps delivering it quickly would be best.", ["objectivesText"] = "Deliver the package to the Night Market. Provided item:", ["rewardGold"] = 514800, ["rewardXP"] = 1770, ["rewardItems"] = { 182727 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 171808, ["x"] = 0.51, ["y"] = 0.788 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.51, ["y"] = 0.788 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["startItems"] = { 182727 } },
[62184] = { ["id"] = 62184, ["name"] = "A Crate of Sinvyr Ore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62184 }, ["description"] = "The crate is fairly big and looks heavy, but it also looks like something someone would be willing to compensate for. Take the crate to Gibbo at the Old Gate. He should be expecting the recurring shipment.", ["objectivesText"] = "Deliver the crate to the Old Gate. Provided item:", ["rewardGold"] = 1500, ["rewardXP"] = 1060, ["rewardItems"] = { 171832, 182728 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 163161, ["x"] = 0.606, ["y"] = 0.398 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.398 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["startItems"] = { 182728 } },
[62187] = { ["id"] = 62187, ["name"] = "Satchel of Culexwood", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62187 }, ["description"] = "This lost satchel is filled with wood given by the nearby Culex trees. Fluttercatch would surely appreciate its return.", ["objectivesText"] = "Return the Satchel of Culexwood to Fluttercatch in the Banks of Life. Provided item:", ["rewardGold"] = 561800, ["rewardXP"] = 1770, ["rewardItems"] = { 174042, 179510, 179512, 179549, 179565, 180630, 180637, 180640, 180642, 180645, 180652, 180654, 180655, 180656, 180731, 180784, 182673, 182729, 182730, 182731, 183129, 184489, 184490 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 158489, ["x"] = 0.48, ["y"] = 0.244 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.48, ["y"] = 0.244 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 182731 } },
[62188] = { ["id"] = 62188, ["name"] = "Catch A Star", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62188 }, ["description"] = "I require your aid on a... delicate matter, <name>. Starfly Wings form a vital ingredient for some of our creations and our supply is exhausted. They are tiny things, very fragile, and I am ill able to handle them delicately. Could you obtain the Starflies for me? They must be caught alive in order for their wings to not spoil and we desperately need them. I'll ensure that you are compensated for your time, of course.", ["objectivesText"] = "Collect 13 Glittering Starflies .", ["rewardGold"] = 257400, ["rewardItems"] = { 175713, 175740, 179517, 179532, 179547, 179562, 179584, 181401, 181404, 181405, 181406, 181413, 181416, 181417, 181418, 181425, 181459, 181477, 181479, 181541, 182584, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62190] = { ["id"] = 62190, ["name"] = "It's a Dirty Job", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62190 }, ["description"] = "We gotta fix up this muck pool before we go makin' that dredger butler of yours. Looks like the anima shortage caused all sorts of problems for this pool. Them muck pools gotta have plenty of filth and fiber in 'em to grow good dredgers. But between them devourers and nasty elementals formin' from all that wild muck, I can't get close enough to feed it! Help me out and throw some of that filthy rubble into the pool, yeah?", ["objectivesText"] = "Throw 6 Filthy Rubble into the muck pool.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62194] = { ["id"] = 62194, ["name"] = "Fighting Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62194 }, ["description"] = "Throughout the Shadowlands, there is so much magic to learn! A threat in Bastion has put many of their ancient teachings in danger. I wish to study their scrolls before they are lost forever. We must travel there and safeguard what we can! Help me fight back the Forsworn at the Temple of Humility and save the scrolls within.", ["objectivesText"] = "Help Sabrina collect 8 Ancient Teachings and eliminate 8 Forsworn enemies.", ["rewardXP"] = 8165, ["rewardItems"] = { 182474, 182485, 182494, 182503, 182512, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159226, ["x"] = 0.548, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.688 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[62195] = { ["id"] = 62195, ["name"] = "The Last Word", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62195 }, ["description"] = "Inquisitor Darksion was an aspiring practitioner of the arcane arts before Denathrius locked her away. I've heard she will share her knowledge with anyone that releases her from imprisonment. I want to learn all she knows! We must free her!", ["objectivesText"] = "Help Sabrina free Inquisitor Darksion. Progress: Did we find anything good?", ["rewardXP"] = 8165, ["rewardItems"] = { 182474, 182485, 182494, 182503, 182512, 182957, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 159226, ["x"] = 0.548, ["y"] = 0.688 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
