[62216] = { ["id"] = 62216, ["name"] = "Training Program", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62216 }, ["description"] = "Sergeant Krashj is an adequate drill master, but these recruits need proper training with a real warrior. Someone who has been bloodied on the battlefield. Someone like me! And I know just the fight that will whip these troops into shape. Let's go teach them a thing or three.", ["objectivesText"] = "Slay Decadious .", ["rewardXP"] = 8165, ["rewardItems"] = { 178679, 182482, 182491, 182500, 182509, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 158301, ["x"] = 0.542, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62217] = { ["id"] = 62217, ["name"] = "Field Training", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62217 }, ["description"] = "Though it was not by our hand, Maldraxxus has dealt a great injustice to the kyrian of Bastion. We must do all that we can to make amends. The Forsworn menace continues to be a thorn in their side. Sounds like the perfect opportunity to both show our support and for our recruits to gain some combat experience.", ["objectivesText"] = "Eliminate 15 Forsworn forces at The Eternal Forge in Bastion.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 178679, 182482, 182491, 182500, 182509, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 158301, ["x"] = 0.542, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62218] = { ["id"] = 62218, ["name"] = "A Fountain for Fae", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62218 }, ["series"] = { 61361, 61362, 62219 }, ["description"] = "Nuuminuuru spends their days protecting and taking care of many faeries throughout Ardenweald. They have expressed concern about some faeries in their care whom they have not seen in some time. Report to Nuuminuuru and see if you can help them find their scattered sprites.", ["objectivesText"] = "Report to Nuuminuuru in Glitterfall Basin in Ardenweald. Progress: A greeting to you, ally of the soulbearers.", ["rewardGold"] = 309800, ["rewardItems"] = { 181275 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173710, ["x"] = 0.514, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533, 1565 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62219] = { ["id"] = 62219, ["name"] = "Fanciful Distractions", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62219 }, ["series"] = { 61361, 61362, 62218 }, ["description"] = "Ever chasing their fleets of fancy, my faerie friends are seldom seen. Their mercurial natures oft lead them astray, tracing them paths to distraction and dismay. Seek my friends, insist they return to my roots, and both you and they may receive recompense.", ["objectivesText"] = "Find Riverblossom , Lunarwind , and Flitterfly and convince them to return to Nuuminuuru . Progress: My wards know to return to my roost, to spin stories of their pursuits and strengthen their spirits. The longer they flit away, the deeper the creases of my concern grow.", ["rewardGold"] = 257400, ["rewardItems"] = { 182974 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173710, ["x"] = 0.514, ["y"] = 0.336 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173710, ["x"] = 0.514, ["y"] = 0.336 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.336 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62221] = { ["id"] = 62221, ["name"] = "My Own Death Pony!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 62221 }, ["objectivesText"] = "Progress: That is such a beautiful death pony, ever since I saw my first one I have dreamed of ...", ["rewardItems"] = { 183842 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
