[62223] = { ["id"] = 62223, ["name"] = "Ascension Calling: Mikanikos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62223 }, ["description"] = "<While this scroll mimics Kleia's invitation to the Path of Ascension, it is very clearly written in Sika's hand. It details an invitation for Mikanikos to participate in the Path, along with Bron. Perhaps you should bring this to Mikanikos .>", ["objectivesText"] = "Inform Mikanikos he is now able to participate in the Path of Ascension.", ["rewardGold"] = 33100, ["rewardXP"] = 1020, ["rewardItems"] = { 182975 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160391, ["x"] = 0.656286, ["y"] = 0.166571 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.656286, ["y"] = 0.166571 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 182975 } },
[62224] = { ["id"] = 62224, ["name"] = "A Thread Of Hope", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62224 }, ["description"] = "The Court of Night is akin to a thirsty flower, it quickly draws up its nutrients. If well supplied it will bloom and if its supply is depleted, it withers. Our roots are beginning to dry, we need more anima! I've sent workers out to place silk lined catchers along the roads and paths that cross Ardenweald. These catchers will collect a tiny bit of anima, not much but enough for what we need. Seek them out and return the Anima Infused Silk to us.", ["objectivesText"] = "Collect 13 Anima Infused Silk Progress: Were you able to find the silk?", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175740, 179532, 179562, 181402, 181407, 181408, 181409, 181410, 181429, 181458, 181477, 181479, 181541, 183041, 183486, 184378, 184381, 184382, 184383, 184384, 184487, 184519 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 173277, ["x"] = 0.596, ["y"] = 0.528 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.596, ["y"] = 0.528 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62232] = { ["id"] = 62232, ["name"] = "Arboreal Tactics", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62232 }, ["description"] = "The spriggan of Ardenweald have always been a nuisance. But under Mueh'zala's influence, they could grow into a threat that looms over all of the Shadowlands. Let's test these troops against a real opponent.", ["objectivesText"] = "Eliminate 12 Bristlecone Spriggan in Mistveil Tangle in Ardenweald.", ["rewardXP"] = 8165, ["rewardItems"] = { 178679, 182482, 182491, 182500, 182509, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 158301, ["x"] = 0.542, ["y"] = 0.685 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
