[62238] = { ["id"] = 62238, ["name"] = "Soul Led Astray", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62238 }, ["description"] = "Uther was a being of justice on your world. I am sure it was quite surprising for you to see his fate here, following a leader who embodies what he stood against in life. I believe you should witness this memory firsthand. Take it to my soul mirror. View the memories within.", ["objectivesText"] = "Use the Soul Mirror at the Eonian Archives to view Uther's arrival in Bastion . Progress: Sometimes the hard truths are the most important to witness.", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 }, { ["mapID"] = 1533, ["npcID"] = 173771, ["x"] = 0.402, ["y"] = 0.198 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 154629, ["x"] = 0.52, ["y"] = 0.195 }, { ["mapID"] = 1533, ["npcID"] = 173771, ["x"] = 0.402, ["y"] = 0.198 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.52, ["y"] = 0.195 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[62239] = { ["id"] = 62239, ["name"] = "Rodent Removal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 62239 }, ["description"] = "<The weapon buzzes with a dark, static energy. Whatever this Mawsworn was testing, it appears to have been somewhat successful on the nearby rodents. Further investigation may yield additional information.>", ["objectivesText"] = "Test the Tormentor's Rod on 8 Giant Mawrats in The Beastwarrens.", ["rewardItems"] = { 137663, 177698, 178874, 178881, 178882, 183105 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
