[62261] = { ["id"] = 62261, ["name"] = "Grinder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62261 }, ["description"] = "It's tough keeping these hands of mine razor sharp. With all the hacking and cleaving, they can grow dull so quickly! What's a girl to do? The House of the Chosen makes some very fine quality sharpening stones. I doubt they will just hand them over, but I'm sure my blades can persuade them otherwise. How about we pay them a visit and see how many stones they can spare?", ["objectivesText"] = "Collect 12 Sharpening Stones and 3 Bonesheared Grinders . Progress: Did you kill them all?", ["rewardXP"] = 8165, ["rewardItems"] = { 182484, 182493, 182502, 182511, 183127, 183138, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158259, ["x"] = 0.50275, ["y"] = 0.47825 }, { ["mapID"] = 1536, ["npcID"] = 159214, ["x"] = 0.544, ["y"] = 0.678 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.50275, ["y"] = 0.47825 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62262] = { ["id"] = 62262, ["name"] = "Fungal Feeding", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62262 }, ["description"] = "Just as I was making progress on our alternative defense research, my spore samples ran dry! The mushrooms I was using can only be found in a particularly unpleasant location to the southeast. To collect an appropriately sized sample, you'll have to--how do I put this--feed them. Don't ask me why, but apparently, they mature fastest with a nice, rotting corpse nearby. Try luring a few undead to our fungal friends. That should give 'em all the nutrients they need to grow big and strong.", ["objectivesText"] = "Collect 20 Mature Spore Samples from Gloomshrooms in Scourgeholme. Progress: Any luck with those samples?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183139 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167572, ["x"] = 0.716, ["y"] = 0.21 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167572, ["x"] = 0.716, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.716, ["y"] = 0.21 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[62263] = { ["id"] = 62263, ["name"] = "Go Beyond!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62263 }, ["description"] = "Ah, you're just in time. I've made quite the discovery. I've managed to make a connection even further out than I ever have before. How did I do it, you ask? Hard work, that's how! But you knew that. You're almost as hardworking as I am. That's what you're here for! Up for an even more exciting adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: I feel a breeze on the other side. I guess that means it's not underground.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181420, 181421, 181422, 181423, 181424, 181425, 181427, 181428, 181429, 181430, 181457, 181459, 181461, 181477, 181479, 181541, 184381, 184382, 184383, 184384, 194371, 194372, 194376, 194393, 194416, 199461, 200960, 204076, 204586, 204594, 204602, 204610, 210024, 211279 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62265] = { ["id"] = 62265, ["name"] = "A New Adventure Awaits", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 14, ["mapID"] = 1, ["storyline"] = { 62265 }, ["description"] = "<name>! You're needed in the present. Things have... well, you should just come back to see. I would finish what you're doing then head back. I can't keep you in the past for much longer!", ["objectivesText"] = "Return to Orgrimmar to embark on a new adventure. Chromie's magic will run out soon, returning you to Orgrimmar.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 183188 }, ["ends"] = { { ["mapID"] = 1, ["npcID"] = 190239, ["x"] = 0.558, ["y"] = 0.126 } }, ["coords"] = { ["mapID"] = 1, ["source"] = "quest_giver", ["x"] = 0.558, ["y"] = 0.126 }, ["mapCandidates"] = { ["npc"] = { 1 }, ["zone"] = { 14 } }, ["questType"] = "standard" },
[62276] = { ["id"] = 62276, ["name"] = "Drink to the Dead", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62276 }, ["description"] = "The Forsworn are ravaging the temples of Bastion, and the aspirants are leaving behind their supplies as they flee. All those wonderful bottles of nectar falling into the hands of the Forsworn? I think not! There's no way we can save all of the aspirants, but we can keep the Forsworn from taking those supplies. Besides... we could all use something to drink around here.", ["objectivesText"] = "24 Purified Nectar and 2 Stewards collected Progress: Did you find us some supplies?", ["rewardXP"] = 8165, ["rewardItems"] = { 174076, 181802, 183128, 183186, 183475, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 158298, ["x"] = 0.548, ["y"] = 0.686 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62280] = { ["id"] = 62280, ["name"] = "Limbo", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["mapID"] = 1533, ["storyline"] = { 62280 }, ["objectivesText"] = "First soul assessed Second soul assessed Third soul assessed", ["rewardXP"] = 8165, ["rewardItems"] = { 109076 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "world", ["db2Objectives"] = { { ["text"] = "First soul assessed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 174007, ["orderIndex"] = 0 }, { ["text"] = "Second soul assessed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 174008, ["orderIndex"] = 1 }, { ["text"] = "Third soul assessed", ["amount"] = 1, ["type"] = 0, ["objectID"] = 174029, ["orderIndex"] = 2 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1533, ["db2QuestInfoID"] = 109, ["db2QuestInfoName"] = "World Quest", ["db2WidgetSetID"] = 472 },
[62294] = { ["id"] = 62294, ["name"] = "One Lich's Trash...", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62294 }, ["description"] = "It is said that one person's trash, is another's treasure. When it comes to relics, the adage is particularly true. The House of Rituals is notoriously secretive, which means any knowledge we can glean from them will be all the sweeter. If we sift through their detritus, I'm sure there are all sorts of treasures we will find.", ["objectivesText"] = "Search through Piles of Debris within the House of Rituals for clues about its past, and recover an Intriguing Ancient Relic . Progress: Did you find anything of interest?", ["rewardXP"] = 8165, ["rewardItems"] = { 182486, 182495, 182504, 182513, 183142, 183398, 183596, 183744, 184843 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 159198, ["x"] = 0.552, ["y"] = 0.682 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167150, ["x"] = 0.55, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.552, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62295] = { ["id"] = 62295, ["name"] = "Cleaning Out the Vault", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62295 }, ["description"] = "The Scourge's rampant aggression has proven difficult to predict, even for us. By the time we knew they were upon us, it was too late. With our forces spread thin, we are left with what you see before you. Enter the vault. Slay our enemies where they stand. Soon the Shadow Vault will be ours once more.", ["objectivesText"] = "Purge the Shadow Vault of the Scourge presence.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[62296] = { ["id"] = 62296, ["name"] = "Into the Unknown", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62296 }, ["description"] = "Come to pay old Marasmius a visit? I have a special task for you. One of my shoots has found a strange place, a place even I've never seen before. I'm not entirely sure what's in there or if it's even safe. But that's what my trusty mushroomancers are for! What do you say, <name>? Up for an adventure?", ["objectivesText"] = "Investigate the unknown area. Progress: Keep your guard up. It could lead anywhere!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175728, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181398, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181414, 181415, 181416, 181417, 181418, 181419, 181420, 181421, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181430, 181457, 181458, 181459, 181477, 181479, 181541, 182469, 182605, 183132, 183167, 183466, 183473, 183479, 183482, 183485, 183487, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
