[62361] = { ["id"] = 62361, ["name"] = "Introductions are in Order", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62361 }, ["series"] = { 61762, 61763, 61764, 61851, 62985 }, ["description"] = "Now yous is all set with yer new dredger, go ahead call on them and officially introduce yerself.", ["objectivesText"] = "Talk with your new Dredger Butler .", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 157846, ["x"] = 0.708, ["y"] = 0.716 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.708, ["y"] = 0.716 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62362] = { ["id"] = 62362, ["name"] = "Volatile Reactions", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62362 }, ["description"] = "The living slime within Maldraxxus naturally produces a powerful catalyst used in many of the House of Eyes's poisons. There is always a need for the substance. It would be of great help if you could retrieve some for us.", ["objectivesText"] = "Collect 15 animated catalysts from the slime around Maldraxxus . Progress: Worry not, despite its appearance the catalyst is not toxic on its own.", ["rewardGold"] = 331700, ["rewardItems"] = { 181507, 181625, 181626, 181638, 181645, 181647, 181648, 181649, 181650, 181651, 181655, 181658, 181663, 181664, 181667, 181685, 181688, 181865, 183436, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[62363] = { ["id"] = 62363, ["name"] = "Heavy Lifting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62363 }, ["description"] = "The stronger members of the House of the Chosen tend to take a fairly specific form. No doubt you've seen the larger warriors in the house? They are the greatest threat in their collective force. Thin them out.", ["objectivesText"] = "Kill 20 warriors of the House of the Chosen.", ["rewardGold"] = 309800, ["rewardItems"] = { 181501, 181638, 181645, 181647, 181649, 181650, 181653, 181654, 181660, 181663, 181665, 181667, 181668, 181669, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[62364] = { ["id"] = 62364, ["name"] = "Dire Learning", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62364 }, ["description"] = "Necromancers and liches often use powerful tomes to assist in their rituals. Now that the House of Rituals has expanded their reach, the tomes can be found anywhere where their members are active. Find these books and destroy them. It won't end their vile experiments but it should at least delay them.", ["objectivesText"] = "Destroy 15 Tome of Rituals .", ["rewardGold"] = 257400, ["rewardItems"] = { 181502, 181503, 181507, 181625, 181626, 181638, 181645, 181647, 181648, 181649, 181650, 181651, 181658, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 167603, ["x"] = 0.512, ["y"] = 0.168 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.512, ["y"] = 0.168 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1536 },
[62365] = { ["id"] = 62365, ["name"] = "Careful Creations", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62365 }, ["description"] = "What better way to stop our enemies in their tracks than to use their own experiments against them? Lucky for us, some of our... friends have left a few samples unattended. And I know just where to test it... As menacing as they may be, those abominations down there are delicate creations. It would be a shame if you were to get your hands on some of their equipment and disrupt the process...", ["objectivesText"] = "Locate an Experimental Blightspreader . Fill it with Experimental Fluid . Use the blightspreader to destroy 3 Reconstructed Abominations at The Fleshwerks. Progress: Everything going as planned?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183442 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 173997, ["x"] = 0.354, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 173997, ["x"] = 0.354, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
