[62444] = { ["id"] = 62444, ["name"] = "Aid the Covenant", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62444 }, ["description"] = "I hear amazing things about the realm beyond this garden, but honestly I am too old to wish to place myself in danger. You are young and vibrant! Head out across the realm, and return to me with the stories of your adventures!", ["objectivesText"] = "Complete a World Quest in Ardenweald. Progress: Head out into the Shadowlands. Return to me with stories of your exploits.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62445] = { ["id"] = 62445, ["name"] = "A Spirit's Pride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62445 }, ["description"] = "I seek to understand more about the prideful beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.", ["objectivesText"] = "Place a Prideful Spirit into a wildseed. Progress: Find a prideful spirit to restore. That is what I wish to see today.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62447] = { ["id"] = 62447, ["name"] = "A Rare and Unusual Spirit", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62447 }, ["description"] = "I have a mystery for you, <name>! Who doesn't savor a good mystery? We have found a spirit unlike any other, one who does not respond to being placed in a wildseed. Each of us who touched it experienced a dream in which we saw you battling a great beast. Only when you defeated it did the spirit begin on its path to rebirth. We think we know the beast. Are you up for discovering if these dreams were a portent?", ["objectivesText"] = "Defeat Tred'ova in Mists of Tirna Scithe.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 183704, 183805, 183806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
