[62450] = { ["id"] = 62450, ["name"] = "A Spirit's Heart", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62450 }, ["description"] = "I seek to understand more about the Untamed beings in this realm. If you could place one in a wildseed, as you did for me, I could observe the restoration process.", ["objectivesText"] = "Place an Untamed Spirit into a wildseed. Progress: Find an Untamed spirit to restore. That is what I wish to see today.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 176832, 176921, 176922 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
