[62473] = { ["id"] = 62473, ["name"] = "What's Old is New", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62473 }, ["description"] = "These damn Scourge make me sick! <Brollen spits on the ground.> They're only good fer one thing--bein' dead! Head tae the valley southwest o' here. Plenty o' gear fer the pickin' over there! Gather up what ye can. I'll make do with what ye find.", ["objectivesText"] = "Gather 8 Jagged Blades and 8 Battleworn Chainmail from the Conflagration. Progress: Find somethin' worth smeltin'?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183757, 183758 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167577, ["x"] = 0.72, ["y"] = 0.206 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167577, ["x"] = 0.72, ["y"] = 0.206 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.72, ["y"] = 0.206 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[62477] = { ["id"] = 62477, ["name"] = "Blueprint: Skystrider Glider", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62477 }, ["description"] = "<You have discovered plans for a single use glider, invented by Dresaelus. Dactylis should be able to help you with crafting this kit.>", ["objectivesText"] = "Bring the Blueprint: Skystrider Glider to Dactylis . Provided item:", ["rewardItems"] = { 183761 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 183761 } },
[62483] = { ["id"] = 62483, ["name"] = "Steward Mail Pouch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62483 }, ["description"] = "<The pouch is well constructed, with plenty of room for scrolls and a division to keep letters flat. The stitching is clean, and the strap is adjustable to fit your steward 's size. You are certain your steward will love it.>", ["objectivesText"] = "Summon your steward companion via Summon steward , then give them the Steward Mail Pouch . Provided item:", ["rewardItems"] = { 184577 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["startItems"] = { 184577 } },
[62484] = { ["id"] = 62484, ["name"] = "Werk In Progress", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62484 }, ["description"] = "We received an... unusual delivery recently. I'm still in a bit of shock. Some sort of flying contraption released a huge crate just overhead, parachute and all. If it weren't for the wind it would have landed nearby. Instead, it drifted down the hill below. They left a note too. It would have been lost had it not been wrapped around a sizeable rock. < Darkrider Arly massages a spot on her forehead.> I don't know what it is, but if it'll help clear out the area, I'm all for it.", ["objectivesText"] = "Locate the delivery. Use the device on a Reconstructed Abomination, then destroy the Scourge presence at the Fleshwerks. Progress: Any luck locating that thing?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183795 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 173997, ["x"] = 0.354, ["y"] = 0.664 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 173997, ["x"] = 0.354, ["y"] = 0.664 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.354, ["y"] = 0.664 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[62486] = { ["id"] = 62486, ["name"] = "Blueprint: Empyrean Refreshment", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62486 }, ["description"] = "<You have discovered plans for a table of refreshing snacks that would be quite useful while out adventuring. Dactylis should be able to help you with the crafting.>", ["objectivesText"] = "Bring the Blueprint: Empyrean Refreshment to Dactylis . Provided item:", ["rewardItems"] = { 183794 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 183794 } },
[62536] = { ["id"] = 62536, ["name"] = "The Lost of Teldrassil", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1565, ["storyline"] = { 62536 }, ["description"] = "I learned that Sylvanas burned Teldrassil. I felt my heart break for the night elves. And that was only the beginning. We know now that the souls lost that day did not go to their intended rest. But you have the power to begin to correct that, Maw Walker. If you find yourself in the Maw, look for any of those lost. Please, bring them home.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 171138, ["x"] = 0.46, ["y"] = 0.566 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.46, ["y"] = 0.566 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[62539] = { ["id"] = 62539, ["name"] = "Stygian Incinerator", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 62539 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2VignetteID"] = 4568, ["db2VignetteName"] = "Stygian Incinerator" },
[62544] = { ["id"] = 62544, ["name"] = "From a Dark Place", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62544 }, ["description"] = "You rescued some of the night elves from the Maw before. While the danger is still great, I must ask you to do it again. I have to believe that we can save them. As many of them as possible. Please, go and see if you can recover any more lost souls.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls.", ["rewardGold"] = 315900, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[62546] = { ["id"] = 62546, ["name"] = "No Wisp Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62546 }, ["description"] = "More of the Kaldorei souls still languish in the Maw. I ask you once again, Maw Walker, to find them. Help correct this wrong.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[62549] = { ["id"] = 62549, ["name"] = "No Wisp Left Behind", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62549 }, ["description"] = "More of the Kaldorei souls still languish in the Maw. I ask you once again, Maw Walker, to find them. Help correct this wrong.", ["objectivesText"] = "Travel to the Maw and rescue Lost Souls from the Tremaculum and the Planes of Torment.", ["rewardGold"] = 309800, ["rewardXP"] = 6815, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[62553] = { ["id"] = 62553, ["name"] = "Delaying Their Efforts", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62553 }, ["description"] = "The Scourge continue to replenish their weapons of war from blighted grounds. Stopping their workers slows their production, but a decisive blow to their stockpiles would be far more effective. Take these and head to the area southeast of here. Plant the bombs, then make a quick exit. Weakening their supply lines should provide us ample time to retaliate.", ["objectivesText"] = "Plant the bombs at the Northern, Eastern and Western sites of The Bombardment. Remove 12 Decrepit Laborers from the area.", ["rewardGold"] = 234000, ["rewardXP"] = 6815, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 167045, ["x"] = 0.71, ["y"] = 0.22 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.71, ["y"] = 0.22 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
