[62559] = { ["id"] = 62559, ["name"] = "Sootible Hat: Crown of the Righteous", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 62559 }, ["objectivesText"] = "Progress: I knows what I needs! Everybody gonna bow down when they sees me in a Crown of the Righteous .", ["rewardItems"] = { 180751, 180752, 180760, 180780, 180781, 180782, 180783 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[62560] = { ["id"] = 62560, ["name"] = "Growing in Power", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62560 }, ["description"] = "Wonderful news, <name>! You have gathered enough Anima. The Queen is now able to empower the Heart of the Forest!", ["objectivesText"] = "Witness the Winter Queen empower the Heart of the Forest. Progress: I am so excited!", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["rewardItems"] = { 180290, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[62561] = { ["id"] = 62561, ["name"] = "My Heart is Full", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62561 }, ["description"] = "<name>! Can you believe it? We have enough Anima that the Winter Queen can fully restore the Heart of the Forest! You've done so much for us!", ["objectivesText"] = "Witness the Winter Queen empower the Heart of the Forest. Progress: I am so excited!", ["rewardGold"] = 30900, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[62563] = { ["id"] = 62563, ["name"] = "Back Again!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62563 }, ["description"] = "Gorgantus just won't give up! We've defeated her several times already, but the scavengers salvage the body, fix her up and send her right back in here! She thinks this time she will defeat us... prove her wrong.", ["objectivesText"] = "Defeat Gorgantus the Gutter", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 37829, 181501, 181502, 181503, 181507, 181625, 181638, 181645, 181646, 181647, 181648, 181649, 181651, 181652, 181653, 181654, 181655, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181667, 181668, 181669, 181670, 181672, 181675, 181676, 181677, 181679, 181680, 181689, 181695, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 160523, ["x"] = 0.514, ["y"] = 0.162 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 160523, ["x"] = 0.514, ["y"] = 0.162 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.514, ["y"] = 0.162 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62567] = { ["id"] = 62567, ["name"] = "Adventurers Wanted: Chromie's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "alliance", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 62567 }, ["description"] = "Chromie is seeking veteran adventurers to embark on expeditions through time and space. This is your opportunity to experience the legendary adventures of the past--today! Speak with Chromie near the Stormwind Embassy for more information.", ["objectivesText"] = "Speak with Chromie in Stormwind.", ["rewardGold"] = 200, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167032, ["x"] = 0.561, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[62568] = { ["id"] = 62568, ["name"] = "Adventurers Wanted: Chromie's Call", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "horde", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 1519, ["mapID"] = 84, ["storyline"] = { 62568 }, ["description"] = "Chromie is seeking veteran adventurers to embark on expeditions through time and space. This is your opportunity to experience the legendary adventures of the past--today! Speak with Chromie near the Orgrimmar Embassy for more information.", ["objectivesText"] = "Speak with Chromie in Orgrimmar .", ["rewardGold"] = 1230, ["rewardXP"] = 175, ["ends"] = { { ["mapID"] = 84, ["npcID"] = 167032, ["x"] = 0.561, ["y"] = 0.174 } }, ["coords"] = { ["mapID"] = 84, ["source"] = "quest_giver", ["x"] = 0.561, ["y"] = 0.174 }, ["mapCandidates"] = { ["npc"] = { 84 }, ["zone"] = { 1519 } }, ["questType"] = "standard" },
[62584] = { ["id"] = 62584, ["name"] = "Frontline Resupply", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 210, ["mapID"] = 118, ["storyline"] = { 62584 }, ["description"] = "This forward camp relies heavily on our supply line from the tournament grounds. A recent shipment was attacked while in transit through the valley below us. Salvage what you can, and if possible, eliminate the threat so this does not happen again.", ["objectivesText"] = "Recover 6 Salvaged Goods and kill 3 Retched Watchers in The Valley of Fallen Heroes. Progress: Caught in the frozen wastes, cold and alone... I only hope our allies put up a fight. < Crusader Renn shakes her head.> Were you able to salvage any of the shipment?", ["rewardGold"] = 257400, ["rewardXP"] = 6815, ["rewardItems"] = { 183832 }, ["starts"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 118, ["npcID"] = 170467, ["x"] = 0.45, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 118, ["source"] = "quest_giver", ["x"] = 0.45, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 118 }, ["zone"] = { 210 } }, ["questType"] = "standard", ["db2PoiMapID"] = 571, ["db2PoiUiMapID"] = 118 },
[62587] = { ["id"] = 62587, ["name"] = "In Search of Inner Calm", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62587 }, ["description"] = "I have always had dreams. Special dreams you could say. Any place of tranquility or calm can come to me in a dream. Even those that may have danger nearby, as calm can be found anywhere, if you know how. Now I dream of your world, your Azeroth. I cannot travel to your realm. Help me connect to my latest dream through your eyes. I have dreamed of a high place. A very high place. Do you know it?", ["objectivesText"] = "Travel to Highmountain in search of calm", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62588] = { ["id"] = 62588, ["name"] = "In Search of Inner Calm", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62588 }, ["description"] = "You return. This pleases me. More places of tranquility have come to me in dreams. I see a sandy beach, Sunsets. I cannot travel to your realm. Help me connect to my latest dream through your eyes.", ["objectivesText"] = "Travel to Zuldazar to meditate.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62589] = { ["id"] = 62589, ["name"] = "In Search of Inner Calm", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62589 }, ["description"] = "I am glad you wish to continue your meditations. It will help you be more centered. I have had another dream. A warm dream of a cold place. It is wrapped in white. Do you know of it? Venture there and experience the vista I saw in my dream.", ["objectivesText"] = "Meditate in Winterspring", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62590] = { ["id"] = 62590, ["name"] = "In Search of Inner Calm", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62590 }, ["description"] = "Thank you for returning. I have had another dream. Another vision of your realm. In this dream the sky danced above me. On the edge of a cliff, in a northern land. Such a sight to behold. You must experience it for yourself.", ["objectivesText"] = "Meditate in Howling Fjord", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62591] = { ["id"] = 62591, ["name"] = "In Search of Inner Calm", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62591 }, ["description"] = "We have already experienced so much together. I am grateful to have a companion on this voyage of discovery. You walk where I can only project. You touch that which I can only see. I have had another dream. Another coast. A statue. A large statue of a little one. Go, seek out the view from my dream.", ["objectivesText"] = "Meditate in Booty Bay", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62592] = { ["id"] = 62592, ["name"] = "Master of Inner Calm", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62592 }, ["description"] = "You have come a long way. You are almost prepared to access your inner calm anywhere. Just one more journey under my guidance. It is a short one. Peace was here in this garden all along. One more location of calm to experience. Then you shall shed your spiritual shackles. I shall be proud.", ["objectivesText"] = "Find the new meditation location within the Queen's Conservatory .", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 183856 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62593] = { ["id"] = 62593, ["name"] = "Hunt: Death Elementals", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62593 }, ["rewardGold"] = 514800, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62597] = { ["id"] = 62597, ["name"] = "Bonesmith Heirmir", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62597 }, ["description"] = "<Alexandros Mograine left you a very straightforward letter of introduction for a certain Bonesmith Heirmir in Maldraxxus. What aid might she be able to offer the Ember Court?>", ["objectivesText"] = "Deliver Alexandros Mograine's letter to Bonesmith Heirmir in Maldraxxus. Provided item:", ["rewardGold"] = 70225, ["rewardXP"] = 2040, ["rewardItems"] = { 177241, 183844 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["startItems"] = { 183844 } },
[62598] = { ["id"] = 62598, ["name"] = "Forgelite Sophone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62598 }, ["description"] = "<Polemarch Adrestes left you a very formal letter of introduction for Forgelite Sophone in Bastion. What aid might she be able to offer the Ember Court?>", ["objectivesText"] = "Deliver Polemarch Adrestes's letter to Forgelite Sophone in Bastion. Provided item:", ["rewardGold"] = 70225, ["rewardXP"] = 2040, ["rewardItems"] = { 177243, 183845 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 }, { ["mapID"] = 1533, ["npcID"] = 174719, ["x"] = 0.528, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 183845 } },
[62599] = { ["id"] = 62599, ["name"] = "Gormsmith Cavina", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62599 }, ["description"] = "<Hunt-Captain Korayn left you a terse letter of introduction to Gormsmith Cavina in Ardenweald. What aid might he be able to offer the Ember Court?>", ["objectivesText"] = "Deliver Hunt-Captain Korayn's letter to Gormsmith Cavina in Ardenweald. Provided item:", ["rewardGold"] = 70225, ["rewardXP"] = 2040, ["rewardItems"] = { 183846 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183846 } },
[62600] = { ["id"] = 62600, ["name"] = "Finding Inner Peace", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62600 }, ["description"] = "This is a lovely spot don't you think? I knew the myths of Ardenweald. Even glimpsed it in dream. Yet it swells with tranquility unimagined. Calm is what my kind live for. Even in chaos. You can always find calm. I can show you if you would like? I can sense a nearby convergence of calm. That will provide a suitable demonstration.", ["objectivesText"] = "Travel out into Ardenweald to commune with the calm of the land.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62601] = { ["id"] = 62601, ["name"] = "Forgy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62601 }, ["description"] = "<Rendle left you a crumpled envelope addressed to Forgy in Darkhaven. On the outside of the envelope are very specific orders to tell Forgy that Rendle sent you. What aid might Forgy be able to offer the Ember Court?>", ["objectivesText"] = "Deliver Rendle's letter to Forgy in Darkhaven. Provided item:", ["rewardGold"] = 70225, ["rewardXP"] = 2040, ["rewardItems"] = { 177242, 183848 }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161931, ["x"] = 0.632, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard", ["startItems"] = { 183848 } },
[62603] = { ["id"] = 62603, ["name"] = "A Rare and Unusual Spirit", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62603 }, ["description"] = "I'm glad to see you again, friend! We have found another inert spirit gripped by dark dreams. Nasty stuff! In this dream, a noble figure that once embodied loyalty has been consumed by their own doubts, leading them down a dark path. If you were to defeat the fallen paragon, I bet we'll be able to revive this poor spirit. Will you help us once more, <name>?", ["objectivesText"] = "Defeat Devos in the Spires of Ascension.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["rewardItems"] = { 183704, 183805, 183806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62606] = { ["id"] = 62606, ["name"] = "A Blackthorn Blend", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62606 }, ["description"] = "Ah, just the mushroomancer I wanted to see! Mind getting me some clay? There's all kinds of different soil, you know. It's not all just dirt! And clay... clay is something special. You ever try growing through clay? Oh, I guess not. It's hard work to break down, but once you do the flavor is incomparable! My roots are looking forward to the challenge. Blackthorn Grove has a particularly bitter and complex clay that is just what I'm craving. I'm sure they won't mind if you ask them for some.", ["objectivesText"] = "Collect 6 Blackthorn Clay in Blackthorn Grove. Progress: If they give you any trouble, just tell 'em Marasmius sent you. I bet someone there is old enough to remember me.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175740, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 181398, 181399, 181400, 181401, 181402, 181415, 181416, 181417, 181455, 181458, 181459, 181477, 181479, 181541, 181980, 182648, 183184, 183202, 183467, 183483, 183488, 183840, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62607] = { ["id"] = 62607, ["name"] = "Glittering Gritty Goodness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62607 }, ["description"] = "Well, hello there! Fancy helping me out today? You ever been to Shimmerbough? Ever wonder why it's called that? I was there when it was named, you know. Lots of people think it's the trees or the water, and they're right. But the secret to the shimmering is in the silt. The soil soaks and gains excess anima from the water, until the ground itself practically sparkles. I could really go for some shimmersilt right now. Would you let an old mushroom relive his youth?", ["objectivesText"] = "Collect 6 Shimmersilt in Shimmerbough. Progress: Oooh, I always used to get tingly all over when I had shimmersilt . And that's a lot of tingling!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179500, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 180932, 181399, 181401, 181402, 181406, 181414, 181415, 181416, 181417, 181418, 181420, 181429, 181455, 181477, 181479, 181541, 182201, 182460, 182584, 182686, 182752, 183184, 183470, 183484, 183485, 183488, 183500, 183507, 183514, 183836, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62608] = { ["id"] = 62608, ["name"] = "A Royal Treat", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62608 }, ["description"] = "So nice to see you again. I've got a special request for you. The Winter Queen herself used to tend directly to groves, in the early times. Everything she touched burst with life and power. Even the ground she walked on. Over time, the Queen's Garden came to be known as the Garden of Night, for the Queen had not tended to her garden in so long. But the ground is still potent with her power. It's the finest meal I've ever had. I know this is indulgent, but you and I both know I deserve it!", ["objectivesText"] = "Collect 6 Royal Peat in the Garden of Night. Progress: Sometimes you just need to treat yourself to something nice.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175740, 181399, 181400, 181401, 181402, 181403, 181405, 181406, 181407, 181410, 181422, 181423, 181424, 181425, 181428, 181457, 181459, 181477, 181479, 181498, 181511, 181541, 181740, 182344, 182460, 182466, 182584, 182621, 182755, 183167, 183468, 183470, 183478, 183505, 183837, 184381, 184382, 184383, 184384, 184587 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62609] = { ["id"] = 62609, ["name"] = "Necrolord Arsenal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62609 }, ["description"] = "<Bonesmith Heimir begins reading the letter you hand her.> Hmm. Mograine usually has more sense than this... <Bonesmith Heimir finishes the letter and shreds it with her bony fingers.> An order's an order. I'll arrange for a shipment of raw materials and forging equipment to be delivered to your court. While you wait, Mograine asks that you clear out some of our enemies to help cover for my absence. It was in the letter. Shame it's all shredded up so you can't read it.", ["objectivesText"] = "Complete World Quests in Maldraxxus.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 177241 }, ["starts"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157676, ["x"] = 0.418667, ["y"] = 0.698 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.418667, ["y"] = 0.698 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[62610] = { ["id"] = 62610, ["name"] = "Hyphae Patrol: The Stalks", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62610 }, ["description"] = "< Marasmius sighs.> They're at it again, up in the Stalks. Seems like we didn't give them enough of a thrashing the first time, eh? What say you and I team up again and teach those younglings a lesson they won't forget? Let me know when you're ready and we'll get 'em, just like before!", ["objectivesText"] = "Ride the fae rings and slay 30 Masked Invaders in The Stalks. Progress: Let's go, before they do any more damage!", ["rewardGold"] = 286500, ["rewardXP"] = 8165, ["rewardItems"] = { 175740, 179562, 181398, 181399, 181400, 181401, 181402, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181415, 181416, 181417, 181418, 181420, 181421, 181425, 181455, 181477, 181479, 181541, 181736, 182304, 182649, 182657, 182769, 183184, 183486, 183487, 183488, 183489, 183514, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62611] = { ["id"] = 62611, ["name"] = "Hyphae Patrol: Heartwood Grove", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62611 }, ["description"] = "Those masked fiends have taken over Heartwood Grove, and I mean to stop their plans. Heartwood Grove was so beautiful before. And now, it's... No matter. We're going to fix this, you and me. Right now. Come, join me in battle. We'll give those monsters a thrashing that will make their masters think twice before desecrating that sacred place again!", ["objectivesText"] = "Ride the fae rings and slay 30 Possessed Desecrators in Heartwood Grove. Progress: Hurry up. I won't stand to let them spend one moment more in that grove.", ["rewardGold"] = 89550, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 175740, 179500, 179508, 179517, 179537, 179547, 179562, 179584, 179604, 181407, 181409, 181410, 181418, 181422, 181423, 181424, 181425, 181430, 181457, 181458, 181459, 181477, 181479, 181506, 181541, 182480, 182649, 183167, 183468, 183469, 183473, 183486, 183489, 184381, 184382, 184383, 184384, 184587 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62612] = { ["id"] = 62612, ["name"] = "Venthyr Arsenal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62612 }, ["description"] = "< Forgy reads the letter you hand him.> Ah, Rendle sent you. Should've said so. No problem. I'll get you everything you need to be bashing skulls at that court. Gonna need some help convincing my boss for the time off, though. Real stick in the muck, yeah? Say you take care of some of the troubles around here, tell everyone it's for me--that'll do it.", ["objectivesText"] = "Complete World Quests in Revendreth.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 177242, 183848 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 161931, ["x"] = 0.632, ["y"] = 0.625 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 161931, ["x"] = 0.632, ["y"] = 0.625 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.632, ["y"] = 0.625 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62613] = { ["id"] = 62613, ["name"] = "Kyrian Arsenal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62613 }, ["description"] = "< Forgelite Sophone reads the letter you hand her.> I see. Wherever I may serve, I will go. Are you willing to do the same? Will you serve Bastion where it has need?", ["objectivesText"] = "Complete World Quests in Bastion.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 177243 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 }, { ["mapID"] = 1533, ["npcID"] = 174719, ["x"] = 0.528, ["y"] = 0.834 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 158807, ["x"] = 0.535, ["y"] = 0.8325 }, { ["mapID"] = 1533, ["npcID"] = 174719, ["x"] = 0.528, ["y"] = 0.834 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.535, ["y"] = 0.8325 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[62614] = { ["id"] = 62614, ["name"] = "Hyphae Patrol: Eventide Grove", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62614 }, ["description"] = "I hope you're ready to fight. The Drust are bolstering their forces in Eventide Grove. Most of Ardenweald doesn't remember them, but I do. You have to completely root them out to be rid of their presence, or they'll grow right back, tougher than ever. Come with me. We're going to exterminate every last one of them. Let me know when you're ready.", ["objectivesText"] = "Ride the fae rings and slay 30 Possessed Invaders in Eventide Grove. Progress: Quickly, before they spread any further into Ardenweald . Now's our chance.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 179508, 179513, 179517, 179532, 179547, 181399, 181400, 181401, 181402, 181407, 181409, 181410, 181418, 181419, 181420, 181421, 181430, 181459, 181464, 181467, 181477, 181479, 181541, 182449, 182464, 182480, 182657, 183465, 183468, 183469, 183478, 183499, 184381, 184382, 184383, 184384, 184587 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62615] = { ["id"] = 62615, ["name"] = "Hyphae Patrol: Gossamer Cliffs", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["storyline"] = { 62615 }, ["description"] = "Bad news from the Gossamer Cliffs. We need to help. The varmints terrorizing the poor silk striders have become more cruel and aggressive lately. The silk striders are important to Ardenweald ; more important than almost anyone else knows. We can't lose any more. Let me know when you're ready to go and we'll scare those gits away for good!", ["objectivesText"] = "Ride the fae rings and slay 30 Blackthorn Assailants in the Gossamer Cliffs. Progress: Quickly! The striders are counting on us!", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 175713, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 181389, 181403, 181404, 181405, 181406, 181417, 181418, 181426, 181427, 181428, 181429, 181458, 181459, 181477, 181479, 181508, 181511, 181541, 181698, 182441, 182466, 182478, 182610, 182621, 183167, 183464, 183473, 183479, 183490, 183491, 183496, 184381, 184382, 184383, 184384 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62616] = { ["id"] = 62616, ["name"] = "Night Fae Arsenal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62616 }, ["description"] = "< Gormsmith Cavina reads the letter you hand him.> I'm not surprised the Hunt-Captain sent you to me. I am the finest gormsmith in all of Ardenweald, afterall. Her orders are clear and I'm happy to help. We'll need you to take on some extra patrols to make up for the lost time and resources. Sound fair?", ["objectivesText"] = "Complete World Quests in Ardenweald.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 177244 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165382, ["x"] = 0.515, ["y"] = 0.34 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.515, ["y"] = 0.34 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62618] = { ["id"] = 62618, ["name"] = "Odalrik", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 62618 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2VignetteID"] = 4573, ["db2VignetteName"] = "Odalrik" },
[62619] = { ["id"] = 62619, ["name"] = "A Meandering Story", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62619 }, ["description"] = "<A quick glance at this heavy tome reveals flowery language and a plot that doesn't seem to go anyplace. At least not in the first few chapters. There is some dirt on the cover, but the damage isn't too bad. This book doesn't seem to have found itself in too much trouble-- a bit like its plot. Archivist Dreyden would probably be pleased to have his book back.>", ["objectivesText"] = "Bring the Meandering Story to Archivist Dreyden in the Grove of Memory. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 183877 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183877 } },
[62620] = { ["id"] = 62620, ["name"] = "A Wandering Tale", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "loremaster" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62620 }, ["description"] = "<This book might have a point, but the author is taking every possible detour along the way. Or maybe it's about the journey and not the destination... In any case, Archivist Dreyden would probably be pleased to have his book back.>", ["objectivesText"] = "Bring the Wandering Tale to Archivist Dreyden in the Grove of Memory. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 183878 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183878 } },
[62621] = { ["id"] = 62621, ["name"] = "An Escapist Novel", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62621 }, ["description"] = "<Action, adventure, thrills, chills... This book has it all! Penned by a mortal soul who led an amazing life, this book is a page-turner. But is it true? Could one person fight conspiracies, ancient evils, vast enemy armies, demons and even gods in a single lifetime? On further reflection, it could be true, but what is a \"duck\" this book speaks of? That part sounds fake. Still... it was a good story. Archivist Dreyden would probably be pleased to have his book back.>", ["objectivesText"] = "Bring the Escapist Novel to Archivist Dreyden in the Grove of Memory. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 183879 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183879 } },
[62622] = { ["id"] = 62622, ["name"] = "A Travel Journal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62622 }, ["description"] = "<This book appears to be a travelogue of this book's personal journey around Ardenweald ! And self-written and published no less! Flipping towards the end you see yourself enter the picture as a villain, unjustly attacking the book and opening it. You read \"This book appears to be a travelogue of this book's personal journey around Ardenweald ! And Self-written and-\" You hurriedly close the book, feeling queasy. It should go back to Archivist Dreyden .>", ["objectivesText"] = "Bring the Travel Journal to Archivist Dreyden in the Grove of Memory. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 109076, 182729, 183880 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183880 } },
[62623] = { ["id"] = 62623, ["name"] = "A Naughty Story", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62623 }, ["description"] = "<You have held this book for less than five minutes and it has already escaped once, bitten you twice and somehow managed to steal some gold. This is not what you were expecting from a \"Naughty Story\" but then again, maybe you should have. You bind the book closed so it will hopefully cause a minimum of mischief. Time to bring it to Archivist Dreyden .>", ["objectivesText"] = "Bring the Naughty Story to Archivist Dreyden in the Grove of Memory. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 183881 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 165867, ["x"] = 0.636, ["y"] = 0.226 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.636, ["y"] = 0.226 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard", ["startItems"] = { 183881 } },
[62624] = { ["id"] = 62624, ["name"] = "The Queen's Conservatory", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 62624 }, ["description"] = "I have heard that you are aiding us in restoring our sanctum, <name>. There is a very special magical grove that we know as The Queen's Conservatory . Within this magical sanctuary we nurture the spirits of old deities back to life. But its magic has waned with the anima drought. It is in need of your help. It would mean the world to us if you could start the restoration process by acquiring the resources we need.", ["objectivesText"] = "Speak to Zayhad to unlock the Queen's Conservatory . Progress: You can go and Speak to Zayhad in your Sanctum to unlock the Queen's Conservatory once you have collected sufficient resources.", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[62625] = { ["id"] = 62625, ["name"] = "A Rare and Unusual Spirit", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62625 }, ["description"] = "It's a joy to see the progress you've made in the restoration of the conservatory, <name>! But there's still more work to be done. We have found another inert spirit. A dark dream is preventing its awakening. In this dream, the spirit is caught in the midst of a feud between ancient beings. Both are a bit on the unsavory side, but one is much, much worse than the other! If you were to defeat the Father of Sleep, it should nudge the spirit from its slumber. Will you help?", ["objectivesText"] = "Defeat Mueh'zala in De Other Side.", ["rewardGold"] = 309800, ["rewardXP"] = 10205, ["rewardItems"] = { 183704, 183805, 183806 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62626] = { ["id"] = 62626, ["name"] = "Mullby's Marker", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62626 }, ["description"] = "The Marker looks like it might be important to this Mulby fellow. Returning it to him in Maldraxxus might net you a finder's fee.", ["objectivesText"] = "Return the marker to the Challenger's Promenade in Maldraxxus.", ["rewardGold"] = 823680, ["rewardItems"] = { 181765 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 161710, ["x"] = 0.544667, ["y"] = 0.494667 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.544667, ["y"] = 0.494667 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["startItems"] = { 181765 } },
[62627] = { ["id"] = 62627, ["name"] = "All Spirits Great and Small", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62627 }, ["description"] = "This is a most curious place. So much energy of rebirth. A fusion of different forms of magic. Not what I expected. I too was committed to rebirth among my kind. This magic is both known to me, and like nothing I have seen before. Yet it all serves to balance. It is not just great spirits of import that help to maintain the cosmic balance. Even the smallest of creatures can play a role. I can show you if you like? Visit the remains of one such creature, and we shall rekindle its spirit.", ["objectivesText"] = "Travel to Frostfire in search of the remains Progress: Return to me when you have found the remains that birthed the spirit animal.", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62628] = { ["id"] = 62628, ["name"] = "Vole's Voucher", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62628 }, ["description"] = "<The voucher spells it all out, if you take the voucher to Au'narim at the Challenger's Promenade outside the Theater of Pain in Maldraxxus he should dispense the funds to you from Grandmaster Vole's credit.>", ["objectivesText"] = "Take the voucher to the Challenger's Promenade in Maldraxxus. Progress: You wish to make a transaction?", ["rewardGold"] = 3088800, ["rewardItems"] = { 181761 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 159830, ["x"] = 0.536, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.536, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["startItems"] = { 181761 } },
[62629] = { ["id"] = 62629, ["name"] = "All Spirits Great and Small", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62629 }, ["description"] = "The time has come for us to rekindle another animal spirit. This one was lost to fire and raiding in a distant land. Go. Commune with the creature's remains . Release its spirit so that it may return here.", ["objectivesText"] = "Travel to Kun-Lai Summit in search of the remains", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
[62630] = { ["id"] = 62630, ["name"] = "All Spirits Great and Small", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13367, ["storyline"] = { 62630 }, ["description"] = "The time has come for us to rekindle another animal spirit. While appearing normal to you, and to the great winged creature that ate it, this creature was in fact somewhat special among its kind. You should travel to its grisly resting place and commune with its spirit so that it may join us in the conservatory.", ["objectivesText"] = "Travel to Tiragarde Sound in search of the remains", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13367 } }, ["questType"] = "standard" },
