[62733] = { ["id"] = 62733, ["name"] = "The Sweetest Tribute", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62733 }, ["series"] = { 62730 }, ["description"] = "Purian good to eat, yes, but better to give. You find locked Silver Strongbox near steward statue. Give Ripe Purian fruit as tribute. Then get nice surprise! You try?", ["objectivesText"] = "Place a Ripe Purian fruit in the steward statue Tribute Tray. Progress: You give Purian yet?", ["rewardGold"] = 316013, ["rewardXP"] = 6125, ["rewardItems"] = { 178915, 179327, 182729, 184486 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 170284, ["x"] = 0.532, ["y"] = 0.464 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 170284, ["x"] = 0.532, ["y"] = 0.464 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.532, ["y"] = 0.464 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
