[62797] = { ["id"] = 62797, ["name"] = "The Vessels of Metal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62797 }, ["description"] = "You have the bearing of one familiar with the art of smithing. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Smith Au'berk in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62798] = { ["id"] = 62798, ["name"] = "The Vessels of Leather and Bone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62798 }, ["description"] = "You have the bearing of one familiar with the art of leatherworking. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Tanner Au'qil in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62799] = { ["id"] = 62799, ["name"] = "The Vessels of the Thread", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62799 }, ["description"] = "You have the bearing of one familiar with the art of thread work. But perhaps you have more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Stitcher Au'phes in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 172230, 172439, 173202, 173204, 178787 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62800] = { ["id"] = 62800, ["name"] = "The Vessels of Jewels", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "legendary" }, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62800 }, ["description"] = "You have the bearing of a lapidary. Though familiar with the art of jewelcraft, perhaps there is yet more to learn. Vessels that hold the power of the runes can be crafted by a hand such as yours. But this I cannot teach you. Hmm, there is a way. I will entrust you with a memory of my recipes for the vessels. Take it to a master of your craft and they will show you the way. What's that? Do not worry. It is merely an echo of my memory. What you restored to me remains intact.", ["objectivesText"] = "Bring the memory back to Appraiser Au'vesk in Oribos.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62801] = { ["id"] = 62801, ["name"] = "The Call of Fate", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 62801 }, ["description"] = "I am the Arbiter's fatescribe. It is my duty to observe the strands of destiny that the Purpose lays before us. Fate flows through you, mortal, as you journey through the Shadowlands. And now it offers you... a choice. Return to Oribos , <name>, that I might help guide your path. The Purpose is our way.", ["objectivesText"] = "Meet Fatescribe Roh-Tahl in Oribos .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[62804] = { ["id"] = 62804, ["name"] = "Filling the Tanks", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62804 }, ["description"] = "<The containment pack appears to be intact, albeit empty. Perhaps refilling it with the appropriate mixture of liquids will render it functional once more. Slaying the correct combination of slimes should provide all the fluid necessary.>", ["objectivesText"] = "Slay the variety of slimes to fill the tanks with fluid.", ["rewardGold"] = 289300, ["rewardXP"] = 8165, ["rewardItems"] = { 184155, 184156 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 157945, ["x"] = 0.59, ["y"] = 0.738 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.59, ["y"] = 0.738 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard", ["startItems"] = { 184155 } },
[62807] = { ["id"] = 62807, ["name"] = "Forest Refugees", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11510, ["mapID"] = 1565, ["storyline"] = { 62807 }, ["description"] = "Some of those displaced by the fallen groves have made a home for themselves at the base of the Heart of the Forest. Hibernal Hollow is fortunate. We have supplies, when they may not. If you would, bring these to Flwngyrr . They care for the refugees there.", ["objectivesText"] = "Bring Hibernal Hollow supplies to Flwngyrr in the Heart of the Forest. Provided item:", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 184157 }, ["starts"] = { { ["mapID"] = 1565, ["npcID"] = 160894, ["x"] = 0.599, ["y"] = 0.534 } }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 168032, ["x"] = 0.484, ["y"] = 0.505 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.599, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 11510 } }, ["questType"] = "standard" },
[62849] = { ["id"] = 62849, ["name"] = "Paragon of the Court of Harvesters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10413, ["mapID"] = 1525, ["storyline"] = { 62849 }, ["description"] = "Maw Walker. Your efforts have provided the Court of Harvesters a decisive edge in their ongoing conflict with the zealots and sycophants who cling to the lost cause of Sire Denathrius. If you will join me in Darkhaven we can express our gratitude to you in a more... physical... way. With treasure, of course.", ["objectivesText"] = "Speak with Mistress Mihaela in Darkhaven.", ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 156822, ["x"] = 0.614, ["y"] = 0.638 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.638 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 10413 } }, ["questType"] = "standard" },
[62850] = { ["id"] = 62850, ["name"] = "Paragon of the Ascended", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62850 }, ["objectivesText"] = "Speak with Adjutant Nikos in Hero's Rest in Bastion .", ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 160470, ["x"] = 0.522, ["y"] = 0.47 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.522, ["y"] = 0.47 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[62851] = { ["id"] = 62851, ["name"] = "Paragon of the Undying Army", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 62851 }, ["description"] = "Your continued advancement of the Undying Army objectives has earned you the continued respect of our forces. I have been authorized to provide you with a portion of recent spoils of war in gratitude. Please join me at the Seat of the Primus to collect these spoils at your earliest convenience.", ["objectivesText"] = "Speak with Nalcorn Talsen at the Theater of Pain.", ["rewardItems"] = { 172924 }, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 173003, ["x"] = 0.506, ["y"] = 0.534 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.506, ["y"] = 0.534 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
