[62855] = { ["id"] = 62855, ["name"] = "Edict of the Eternal Ones", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 62855 }, ["description"] = "Death appears to function differently for you, Maw Walker. Alas, you have shed some of your stygia. Return to the place of your passing, and you shall find what you left behind.", ["objectivesText"] = "Recover your Dropped Stygia from your corpse.", ["rewardGold"] = 37050, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62886] = { ["id"] = 62886, ["name"] = "A Call to Service", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 62886 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006, 63101 }, ["description"] = "The Heart of the Forest requires anima to be renewed and to grow. The Wild Hunt will need your help to recover what we need. Together we strand strong. Speak with Blodwyn. She has been guiding assistance to where it is most needed.", ["objectivesText"] = "Speak with Blodwyn.", ["rewardGold"] = 25740, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[62916] = { ["id"] = 62916, ["name"] = "Your Next Best Friend", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62916 }, ["description"] = "You looking for a new friend? Hoo-hoo! Lots of stewards who are happy to be friend. Plus, current friend can take break! Maybe go to Cliffs of Respite, rest feet, eat cake... < Sika gets lost in a daydream.> Hoo! Right! I call stewards. You make new friend!", ["objectivesText"] = "Select a new steward companion, then return to Sika . Progress: New friends, new friends! Stewards love making new friends!", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 175426, ["x"] = 0.53, ["y"] = 0.475 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 175426, ["x"] = 0.53, ["y"] = 0.475 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.53, ["y"] = 0.475 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[62928] = { ["id"] = 62928, ["name"] = "Blueprint: Ring of Warding", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 62928 }, ["description"] = "<You have discovered plans for a defensive ward that may give your soulbinds an edge in the Path of Ascension. Dactylis should be able to help you with crafting this piece of equipment.>", ["objectivesText"] = "Bring the Blueprint: Ring of Warding to Dactylis . Provided item:", ["rewardItems"] = { 184348 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 184348 } },
[62951] = { ["id"] = 62951, ["name"] = "Path of Ascension: Kleia", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62951 }, ["description"] = "Artemede has been personally training Kleia , running her through combat meditations and drills. She has come far, and she is prepared to take on another trial in the Path of Ascension. Return to the coliseum and guide her as her tactician so that she may reach victory.", ["objectivesText"] = "Win any Path of Ascension trial as Kleia .", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62952] = { ["id"] = 62952, ["name"] = "Path of Ascension: Pelagos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62952 }, ["description"] = "Though combat is not his strong suit, Pelagos has been reading, meditating, and training to better himself on the Path. We believe he is ready to seek victory. He requests you by his side to help him strategize. He is stronger with the help of his friends.", ["objectivesText"] = "Win any Path of Ascension trial as Pelagos .", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62953] = { ["id"] = 62953, ["name"] = "Path of Ascension: Mikanikos", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62953 }, ["description"] = "Mikanikos has been hard at work at the Eternal Forge, calibrating Bron and tuning his combat procedures. He is confident in his recent changes, and requests permission to attempt another trial. Enter the Path with Mikanikos so that he may assess his goliath's strengths and weaknesses.", ["objectivesText"] = "Win any Path of Ascension trial as Mikanikos .", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
[62954] = { ["id"] = 62954, ["name"] = "Path of Ascension: Kalisthene", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 62954 }, ["description"] = "Your soulbinds request your strategic mind in another trial. Their sights this week are set on Kalisthene , that they may learn from the lessons her memory teaches. When you are able, report to Artemede to return to the Path of Ascension. Aid your soulbinds in defeating Kalisthene to prove their growth.", ["objectivesText"] = "Defeat Kalisthene in the Path of Ascension with any soulbind.", ["rewardItems"] = { 184812 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168485, ["x"] = 0.628, ["y"] = 0.164 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard" },
