[63000] = { ["id"] = 63000, ["name"] = "Blueprint: Charm of Focus", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63000 }, ["description"] = "<You have discovered plans for a charm that seems to energize your soulbinds in the Path of Ascension. Dactylis should be able to help you with crafting this charm.>", ["objectivesText"] = "Bring the Blueprint: Charm of Focus to Dactylis . Provided item:", ["rewardItems"] = { 181238 }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 168430, ["x"] = 0.63, ["y"] = 0.16 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.63, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard", ["startItems"] = { 181238 } },
[63031] = { ["id"] = 63031, ["name"] = "Acquisition: Crystallized Stygia", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63031 }, ["description"] = "<This shard of crystal appears to have broken off of one of the massive crystalline structures throughout the area. It thrums with untapped energy. Ve'nari would likely be interested in any of these shards you come across.>", ["objectivesText"] = "Collect 10 Crystallized Stygia and return it to Ve'nari in the Maw . Progress: What have you collected, <class>?", ["rewardItems"] = { 184510 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63034] = { ["id"] = 63034, ["name"] = "The Elysian Fields", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 63034 }, ["series"] = { 62707, 62723, 62729 }, ["description"] = "You must travel to Bastion , eternal home of the winged kyrian. Do not be fooled by their golden fields and shining spires--the kyrian have been weakened by the great anima drought, and face the brink of civil war against their own fallen brethren. They will benefit greatly from your aid. Seek one known as Kalisthene in your new sanctum, Elysian Hold. She will direct you further. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Kalisthene at Elysian Hold in Bastion .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63035] = { ["id"] = 63035, ["name"] = "A Fresh Blade", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1536, ["storyline"] = { 63035 }, ["series"] = { 62738, 62748, 62761 }, ["description"] = "Though they were once unified in defending the Shadowlands, the houses of Maldraxxus have turned against each other. Their armies clash within their realm and have even orchestrated an assault on Bastion. Now only the Necrolords remain loyal to the Primus. Speak to Secutor Mevix at the Seat of the Primus in Maldraxxus . His tactical skills will ensure you are sent where you are most needed. Pathscribe Roh-Avonavi in the Ring of Transference above can provide you with transportation.", ["objectivesText"] = "Speak to Secutor Mevix at the Seat of the Primus in Maldraxxus .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 175008, ["x"] = 0.528, ["y"] = 0.682 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.528, ["y"] = 0.682 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63036] = { ["id"] = 63036, ["name"] = "Restoring Balance", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["mapID"] = 1565, ["storyline"] = { 63036 }, ["series"] = { 62739, 62763, 62776 }, ["description"] = "Ardenweald is crucial to the cycle of rebirth for nature spirits that enter their realm. Unfortunately, the anima drought has led to the loss of entire groves--souls that will never complete their cycle. Now foes seek to destroy what remains of the once tranquil forests, threatening the already beleaguered Court of Night. Lady Moonberry of the Court has requested aid. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Lady Moonberry at the Heart of the Forest in Ardenweald .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["rewardItems"] = { 211279 }, ["ends"] = { { ["mapID"] = 1565, ["npcID"] = 172431, ["x"] = 0.492, ["y"] = 0.522 } }, ["coords"] = { ["mapID"] = 1565, ["source"] = "quest_giver", ["x"] = 0.492, ["y"] = 0.522 }, ["mapCandidates"] = { ["npc"] = { 1565 }, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63037] = { ["id"] = 63037, ["name"] = "Dark Aspirations", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 63037 }, ["series"] = { 62740, 62778, 62779 }, ["description"] = "Prince Renathal has started a daring rebellion against his father, the nefarious Sire Denathrius who betrayed us all by pouring Revendreth 's vast anima stores into the Maw. You must travel to Revendreth and aid Renathal in his efforts. He is our best hope at restoring Revendreth to order. Pathscribe Roh-Avonavi in the Ring of Transference above can provide transport.", ["objectivesText"] = "Speak to Prince Renathal in Sinfall in Revendreth .", ["rewardGold"] = 28090, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[63039] = { ["id"] = 63039, ["name"] = "A Monument to Vengeance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63039 }, ["description"] = "<Corpses of Ebon Blade knights litter the Crucible of the Damned, displaying the aftermath of your first foray into this desolate place. Their sacrifice should not be forgotten.>", ["objectivesText"] = "Collect 8 Ebon Runeblades and build a monument to the Ebon Blade's sacrifice in the Crucible of the Damned. Progress: <This precipice is highly visible throughout the Maw . Building the monument here will surely draw the Jailer's ire.>", ["rewardItems"] = { 184511 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 175807, ["x"] = 0.222, ["y"] = 0.478 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.478 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63041] = { ["id"] = 63041, ["name"] = "Short-Supply Reward", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 63041 }, ["rewardItems"] = { 69903, 90818, 103533, 120334, 128803, 140591, 141701, 160054, 184522, 201326, 224573, 259086 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63043] = { ["id"] = 63043, ["name"] = "Sundered Souls", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63043 }, ["description"] = "The traps... they didn't affect us before. Too many souls... escaping. They... made new traps... tear apart fleeing souls... ...too late for me. Destroy... so others might escape!", ["objectivesText"] = "Destroy 10 Soulrend Traps in the Tremaculum.", ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 175813, ["x"] = 0.282, ["y"] = 0.145 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 }, { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.282, ["y"] = 0.145 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63044] = { ["id"] = 63044, ["name"] = "Ratgusher", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["storyline"] = { 63044 }, ["rewardXP"] = 8165, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2VignetteID"] = 4603, ["db2VignetteName"] = "Ratgusher" },
[63046] = { ["id"] = 63046, ["name"] = "The End and the Beginning", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["storyline"] = { 63046 }, ["description"] = "I am so happy you restored our connection to the Queen's Conservatory! In light of this accomplishment, the Winter Queen has requested you attend her at the Grove of Awakening! You will see first hand the purpose of Ardenweald and gain a greater understanding of our sacred charge before you too, take it upon yourself. Hurry! Don't keep everyone waiting!", ["objectivesText"] = "Learn about Wildseeds from the Winter Queen .", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 129258, 129259, 129260, 129346, 129347, 129348, 129349, 141393, 175176, 175177, 175178, 175179, 175208, 175209, 175210, 175211, 237812 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard" },
[63047] = { ["id"] = 63047, ["name"] = "Acquisition: Runeforged Shackles", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63047 }, ["description"] = "<The chains here are carved with domination runes, imbuing them with the magic needed to subdue the most powerful of the Mawsworn's prisoners. No doubt Ve'nari could find some use in studying these runes.>", ["objectivesText"] = "Collect 9 Runeforged Shackles and return them to Ve'nari in the Maw . Progress: Another transaction?", ["rewardItems"] = { 184552 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63050] = { ["id"] = 63050, ["name"] = "Acquisition: Blazing Ingots", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63050 }, ["description"] = "<The runesmiths have imbued this ingot with an enchantment that causes it to burn with inextinguishable flames. It is likely that this metal is used to empower the Mawsworn protectors of Zovaal's Cauldron. Bringing some samples of this ore to Ve'nari could aid her attempts at unlocking the Jailer's secrets.>", ["objectivesText"] = "Collect 12 Blazing Ingots and return them to Ve'nari in the Maw . Progress: What's this?", ["rewardItems"] = { 184556 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63056] = { ["id"] = 63056, ["name"] = "Sanctum Upgrade: Mirror Network", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1699, ["storyline"] = { 57531, 57532, 57533, 57534, 57535, 57536, 57571, 59427, 63056 }, ["series"] = { 57531, 60051 }, ["description"] = "Right. So, we got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work. Thing is, after you going to need a proper mirror maker to get 'em up an' workin'. Prince Renathal might know a fang with the right skills. Best speak with him.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to conjure a Mirror Network. Progress: Enough anima in the right hands and we can construct whatever is needed in Revendreth .", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1699, ["questLines"] = { { ["id"] = 1223, ["name"] = "Mirror Maker of the Master", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63058] = { ["id"] = 63058, ["name"] = "Abominable Stitching and Me", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11462, ["mapID"] = 1536, ["storyline"] = { 63058 }, ["description"] = "Constructs have formed the backbone of Maldraxxi armies in more wars than anyone can count. A well-constructed body can turn any soul into a potent frontline weapon. There is an old abominable stitching table outside of the sanctum that could be used to build our own constructs. With the anima you've secured for our covenant, we should be able to restore it. Report to Miggsie once the work has begun. You can find her at Butchers Block.", ["objectivesText"] = "Activate the Abomination Factory. Progress: You made the right choice.", ["rewardGold"] = 154900, ["rewardXP"] = 4085, ["ends"] = { { ["mapID"] = 1536, ["npcID"] = 175967, ["x"] = 0.548, ["y"] = 0.686 } }, ["coords"] = { ["mapID"] = 1536, ["source"] = "quest_giver", ["x"] = 0.548, ["y"] = 0.686 }, ["mapCandidates"] = { ["npc"] = { 1536 }, ["zone"] = { 11462 } }, ["questType"] = "standard" },
[63060] = { ["id"] = 63060, ["name"] = "Rule 6 Footnote: Don't Forget Anything", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63060 }, ["series"] = { 63022 }, ["description"] = "In the Maw , you must never forget to take everything with you. Many things crawl within the Beastwarrens. The runes you brought back indicate that something of interest may have been left behind by the brokers who were taken there. See if you can find it.", ["objectivesText"] = "Look for whatever was left behind by the brokers in the Beastwarrens.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["rewardItems"] = { 182955 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 175703, ["x"] = 0.57, ["y"] = 0.575 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63062] = { ["id"] = 63062, ["name"] = "Torment for the Taking", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63062 }, ["description"] = "<A broker device has been abandoned here. It seems like it was being used to siphon energy from rifts of soul energy that have erupted in the area. The brokers surely would not have sought to harness this energy if it didn't have a use. Perhaps you should finish what they started.>", ["objectivesText"] = "Fill the Phasic Siphoner from the Soul Fissures in Detrithos and return it to Ve'nari in the Maw .", ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63063] = { ["id"] = 63063, ["name"] = "Sanctum Upgrade: Mirror Network", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 63063 }, ["description"] = "We got a Scroll of Dark Empowerment ready for youz that should manifest 'em mirror frames for you. Pre'y standard work. Once you do the conjurin', then ol' Laurent should be able to work 'is magic as it were. Right proper glass guy he is.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to conjure a Mirror Network.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[63065] = { ["id"] = 63065, ["name"] = "Sanctum Upgrade: The Ember Court", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 10986, ["storyline"] = { 63065 }, ["series"] = { 59660 }, ["description"] = "We got a Scroll of Dark Empowerment ready for youz that should provide you with enough resources to get one of 'em fancy parties the fangs are fond of. The Mad Duke is the one you should chat with 'bout this one. He used to run all the court parties back before he got roasted.", ["objectivesText"] = "Use the Scroll of Dark Empowerment to begin the Ember Court.", ["rewardGold"] = 28090, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard" },
[63068] = { ["id"] = 63068, ["name"] = "Settling Disputes", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10534, ["mapID"] = 1533, ["storyline"] = { 63068 }, ["description"] = "In my search to find kyrian that would fit our purposes here, I have landed on two in particular -- Pelodis and Nemea . However, the two are involved in quite the rivalry, and struggle to focus their attention elsewhere. I propose that you aid them in settling their dispute so that they may focus on the task at hand. I doubt they shall work together, however, so you will need to pick one to aid us.", ["objectivesText"] = "Meet with Pelodis at Forgefire Outpost or Nemea at Nemea 's Retreat.", ["rewardGold"] = 28090, ["rewardXP"] = 175, ["rewardItems"] = { 42997 }, ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 160389, ["x"] = 0.648, ["y"] = 0.164 } }, ["ends"] = { { ["mapID"] = 1533, ["npcID"] = 157696, ["x"] = 0.568, ["y"] = 0.442667 }, { ["mapID"] = 1533, ["npcID"] = 158765, ["x"] = 0.5565, ["y"] = 0.438 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.164 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 10534 } }, ["questType"] = "standard" },
[63069] = { ["id"] = 63069, ["name"] = "What They Know", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63069 }, ["description"] = "<It looks like this broker was gathering information before he met his unfortunate end. Ve'nari would likely be very interested in what he found. Unfortunately, his notes look to have been scattered far and wide by the local beasts.>", ["objectivesText"] = "Collect 18 Torn Journal Pages in the Hungering Wastes and return them to Ve'nari in the Maw . Progress: That book... that is a pathfinder's journal you carry!", ["rewardGold"] = 280900, ["rewardXP"] = 4115, ["rewardItems"] = { 184579 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63072] = { ["id"] = 63072, ["name"] = "Acquisition: Stygic Ore", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63072 }, ["description"] = "<The rock columns in this area are teeming with veins of a glowing, otherworldly metal. The Mawsworn have employed souls to mine it, but it looks like they didn't last long. Ve'nari could certainly find use for some of this ore, if you can manage to mine it.>", ["objectivesText"] = "Collect 15 pieces of Stygic Ore in Marrow's Coppice and return them to Ve'nari in the Maw . Progress: What do you carry, Maw Walker?", ["rewardItems"] = { 184585 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63100] = { ["id"] = 63100, ["name"] = "Misery's Company", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63100 }, ["description"] = "<The husk of this poor soul has been stripped of everything, down to near nonexistence. This suffering cannot continue. Save the others from their misery.>", ["objectivesText"] = "Kill 10 Hopeless Vessels in Gorgoa: River of Souls.", ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 176069, ["x"] = 0.247, ["y"] = 0.455 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.247, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543 },
[63101] = { ["id"] = 63101, ["name"] = "XX REUSEME", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63101 }, ["series"] = { 58160, 60287, 60289, 61355, 61391, 62693, 62697, 62882, 62883, 62884, 62886, 62890, 62891, 62892, 62893, 62902, 62903, 62904, 62905, 63006 }, ["description"] = "As you grow in renown across the Shadowlands, the Heart of the Forest shall grow with you. Seek out Laurel, our Keeper of Renown. She will acquaint you with the magic that we bestow upon our huntsmen and huntresses.", ["objectivesText"] = "Seek out Laurel the Heart of the Forest.", ["rewardGold"] = 25270, ["rewardXP"] = 1020, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63132] = { ["id"] = 63132, ["name"] = "Constellan Writ", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63132 }, ["description"] = "<The writing on the scroll changes rapidly. It likely holds ancient secrets that Ve'nari may find intriguing.>", ["objectivesText"] = "Bring the Constellan Writ to Ve'nari at Ve'nari 's Refuge. Provided item:", ["rewardGold"] = 280900, ["rewardXP"] = 8165, ["rewardItems"] = { 175769 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["startItems"] = { 175769 } },
