[63340] = { ["id"] = 63340, ["name"] = "Sinfall Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 63340, 63341 }, ["description"] = "Sinfall's influence grows thanks to your triumphs, <name>! Your accomplishments have not gone unnoticed, even beyond the borders of Revendreth. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1211, ["name"] = "Sinfall Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63341] = { ["id"] = 63341, ["name"] = "Sinfall Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 63340, 63341 }, ["description"] = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, <name>. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1211, ["name"] = "Sinfall Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63342] = { ["id"] = 63342, ["name"] = "Necrolord Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 63342, 63343 }, ["description"] = "The might of the Necrolords grows thanks to you, <name>. Your accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1212, ["name"] = "Necrolord Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63343] = { ["id"] = 63343, ["name"] = "Necrolord Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 63342, 63343 }, ["description"] = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1212, ["name"] = "Necrolord Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63344] = { ["id"] = 63344, ["name"] = "Kyrian Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63344, 63345 }, ["description"] = "Bastion is healing thanks to you, <name>. The path is clear. Your accomplishments have not gone unnoticed, even beyond the borders of Bastion. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1213, ["name"] = "Kyrian Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63345] = { ["id"] = 63345, ["name"] = "Kyrian Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 63344, 63345 }, ["description"] = "Look around you, <name>. Elysian Hold stands as a testament to the progress we have made thanks to you. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1213, ["name"] = "Kyrian Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63346] = { ["id"] = 63346, ["name"] = "Night Fae Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 63346, 63347 }, ["description"] = "Ardenweald is safer than it has been in quite some time, thanks to you. Your accomplishments have not gone unnoticed, even beyond the borders of Ardenweald. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1214, ["name"] = "Night Fae Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[63347] = { ["id"] = 63347, ["name"] = "Night Fae Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 63346, 63347 }, ["description"] = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1214, ["name"] = "Night Fae Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[63418] = { ["id"] = 63418, ["name"] = "Exploited Explorers", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63418 }, ["description"] = "Chuck explains that something weird is happening in the jungle, and that his group has been captured by wild fungarians. He asks you to rescue his friends to help find out what's going on with the jungle.", ["objectivesText"] = "Rescue Chuck's friends", ["rewardGold"] = 169800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63419] = { ["id"] = 63419, ["name"] = "Spores Galore", ["level"] = 10, ["requiredLevel"] = 10, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 63419 }, ["description"] = "Chuck goes over again how the jungle seems to be alive and all wrong. He asks you to recover the spores that are on the fungarians and the beasts they've infected. Chuck is worried whatever is happening isn't natural.", ["objectivesText"] = "Collect 12 strange", ["rewardGold"] = 309800, ["rewardXP"] = 1415, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[63435] = { ["id"] = 63435, ["name"] = "Temple Throwdown", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 5841, ["mapID"] = 379, ["storyline"] = { 63435 }, ["description"] = "My parents are busy defending the Shrine of the... Eight... Coconuts? I wasn't paying attention. That's probably why they left me here. They told me I could train with the big white cat! I'm going to be a ninja! < Anthea kicks several times in your direction.> Ya! Kya! You better watch out! ... I'm bored, do you want to pet battle? I brought all of my favorite pets with me.", ["objectivesText"] = "Defeat Anthea in a pet battle. Progress: I'm gonna get you! < Anthea punches the air several times.> Biff! Pow!", ["rewardGold"] = 341600, ["rewardXP"] = 200, ["rewardItems"] = { 184866 }, ["starts"] = { { ["mapID"] = 379, ["npcID"] = 176655, ["x"] = 0.704, ["y"] = 0.514 } }, ["ends"] = { { ["mapID"] = 379, ["npcID"] = 176655, ["x"] = 0.704, ["y"] = 0.514 } }, ["coords"] = { ["mapID"] = 379, ["source"] = "quest_giver", ["x"] = 0.704, ["y"] = 0.514 }, ["mapCandidates"] = { ["npc"] = { 379 }, ["zone"] = { 5841 } }, ["questType"] = "standard" },
[63447] = { ["id"] = 63447, ["name"] = "Fear No Evil", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "alliance", ["requiredRaces"] = { 32 }, ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 6170, ["mapID"] = 37, ["storyline"] = { 63447 }, ["description"] = "Have you embraced the Holy Light yet, <brother/sister>? It is through the Holy Light that we are saved! It is through the Holy Light that I am able to heal these overly demanding soldiers! And it is through the Holy Light that you will be able to venture out into the field to the north and rescue our fallen brothers! Take this prayer book with you into the field and cast the Light's healing touch on the injured.", ["objectivesText"] = "Revive 4 Injured Stormwind Soldiers.", ["rewardGold"] = 2000, ["rewardXP"] = 200, ["rewardItems"] = { 57256, 57257, 57258, 65733, 131874 }, ["starts"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["ends"] = { { ["mapID"] = 37, ["npcID"] = 951, ["x"] = 0.485, ["y"] = 0.381 } }, ["coords"] = { ["mapID"] = 37, ["source"] = "quest_giver", ["x"] = 0.485, ["y"] = 0.381 }, ["mapCandidates"] = { ["npc"] = { 37 }, ["zone"] = { 6170 } }, ["questType"] = "standard" },
[63455] = { ["id"] = 63455, ["name"] = "Dead On Their Feet", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63455 }, ["description"] = "As the Jailer twists the souls here to his will, there are still some that continue to resist him. I shall give you the ability to aid them in their resistance. Through Necrotic Cohesion we shall bind the runes, armor, and bones that reside here to create bodies for these souls. Bodies that will allow them to fight for us and their freedom! Bind the Zealous souls and build us an army!", ["objectivesText"] = "Use the Cohesion Crystal to create bodies for 10 Defiant Souls .", ["rewardItems"] = { 181501, 181502, 181507, 181645, 181647, 181649, 181653, 181659, 181660, 181661, 181662, 181663, 181671, 181672, 181673, 181674, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181682, 182610, 182753, 184305, 184772, 184773, 184774, 184775, 184776, 184876 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177076, ["x"] = 0.335, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.335, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63543] = { ["id"] = 63543, ["name"] = "Necrolord Assault", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63543 }, ["description"] = "The Jailer's forces have been caught off guard by our attack. We shall overrun Perdition Hold and defeat his champions at the Altar of Domination! Your help is needed Maw Walker. Assist our forces on the battlefield!", ["objectivesText"] = "Complete 1 quests in Perdition Hold and the Face of Oblivion.", ["rewardItems"] = { 185720, 185992 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 11400 } }, ["questType"] = "standard", ["db2DetailThemeID"] = 29, ["db2Objectives"] = { { ["text"] = "Report to Draka at the gates of Perdition Hold", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177674, ["orderIndex"] = 0 }, { ["text"] = "Help Maldraxxi forces assault Perdition Hold", ["amount"] = 1, ["type"] = 14, ["objectID"] = 92362, ["orderIndex"] = 1 }, { ["text"] = "Use Draka's Battlehorn to signal the advance", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177290, ["orderIndex"] = 2 }, { ["text"] = "Advance to the Altar of Domination", ["amount"] = 1, ["type"] = 0, ["objectID"] = 177532, ["orderIndex"] = 3 } }, ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1543, ["db2QuestInfoID"] = 268, ["db2QuestInfoName"] = "Threat Wrapper" },
[63545] = { ["id"] = 63545, ["name"] = "Putting A Plan Together", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63545 }, ["description"] = "While Maldraxxus pushes the main gate, we can take the side gate with the help of our Centurions. The remains of many Corrupted Centurions taken by the Jailor litter this area. Their parts could be used to build new ones to help in the assault. See if you can locate the parts we need to build a new Centurion.", ["objectivesText"] = "Deliver 3 Centurion Parts and 15 Automaton Bolts to Mikanikos Progress: Have you found the parts I requested?", ["rewardItems"] = { 180935, 181377, 181572, 181573, 181581, 181599, 181609, 181610, 181703, 181843, 181866, 182127, 182385, 182470, 182667, 183132, 183480, 183506, 184294, 184362, 184363, 184513, 184766, 184767, 184768, 184839, 185685, 186573, 186603, 186604, 187508 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3975, ["y"] = 0.5425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
