[63621] = { ["id"] = 63621, ["name"] = "Pulling His Chain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63621 }, ["description"] = "They call this one the Keeper of Chains . Do not underestimate his power. He has bound nearby souls in preparation for an attack against our position. I need you to eliminate this threat, Maw Walker, before it moves against our forces.", ["objectivesText"] = "Eliminate the Keeper of Chains . Progress: Have you eliminated this threat?", ["rewardItems"] = { 181368, 181571, 181572, 181573, 181576, 181580, 181581, 181589, 181599, 181601, 181603, 181604, 181609, 181610, 181614, 181704, 181745, 184294, 184362, 184363, 184513, 184767, 184768 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.537 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "group" },
[63625] = { ["id"] = 63625, ["name"] = "Here's an Axe, Get to Work!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63625 }, ["description"] = "Our troops are meeting stiff resistance! Maw Walker, grab a weapon and take the fight to them! Eliminate the Mawsworn forces and their commander defending these gates.", ["objectivesText"] = "Eliminate 15 Mawsworn forces and Commander Mallamort .", ["rewardItems"] = { 181501, 181502, 181507, 181625, 181626, 181645, 181647, 181649, 181688, 181689, 181691, 181693, 181697, 181865, 183490, 184195, 184305, 184513, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.338, ["y"] = 0.548 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63664] = { ["id"] = 63664, ["name"] = "Get to the Point", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63664 }, ["description"] = "Our position near the bridge to the Altar of Domination is under heavy attack! We can not afford to lose the ballista we have set up there. Maw Walker, I need you to defend that position till our troops can push forward!", ["objectivesText"] = "Defend the forward position inside Perdition Hold. Progress: Is our position safe?", ["rewardGold"] = 309800, ["rewardXP"] = 8165, ["rewardItems"] = { 180896, 181501, 181502, 181625, 181647, 181649, 181651, 181652, 181654, 181656, 181671, 181672, 181673, 181674, 182464, 184305, 184772, 184773, 184774, 184775 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177126, ["x"] = 0.332, ["y"] = 0.57 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.332, ["y"] = 0.57 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63669] = { ["id"] = 63669, ["name"] = "Somebody Feed Kevin", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63669 }, ["description"] = "My family of slimes is always hungry for anima. Thankfully the bodies of the defeated here are a good source! The more the slimes consume the larger they grow. Then what remains of the fallen will become part of our wonderful, happy family. Take Kevin and let him consume fallen enemies till he is fully grown, then unleash him upon our foes!", ["objectivesText"] = "Consume 8 fallen enemies to grow Kevin to full size.", ["rewardGold"] = 58650, ["rewardXP"] = 8165, ["rewardItems"] = { 181503, 181645, 181647, 181649, 181651, 181660, 181661, 181662, 181663, 181664, 181665, 181666, 181675, 181676, 181677, 181678, 181679, 181680, 181681, 181686, 181689, 181734, 181864, 182470, 182667, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 163295, ["x"] = 0.328, ["y"] = 0.568 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177072, ["x"] = 0.338, ["y"] = 0.548 }, { ["mapID"] = 1543, ["npcID"] = 177685, ["x"] = 0.322, ["y"] = 0.579333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.328, ["y"] = 0.568 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
