[63827] = { ["id"] = 63827, ["name"] = "Encouraging Words", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63827 }, ["description"] = "Our forces have been battling relentlessly for hours. No doubt they grow tired and disheartened. Take this codex and recite the words within to our troops. Do not be fooled. Though the prose may seem meaningless, it holds immense power. Hearing these words will reinvigorate our exhausted Protectors with hope.", ["objectivesText"] = "Recite the words within the codex to 8 Exhausted Protectors .", ["rewardItems"] = { 180933, 181368, 181377, 181464, 181511, 181569, 181571, 181575, 181576, 181577, 181580, 181589, 181591, 181596, 181604, 181605, 181608, 181610, 181627, 181628, 181630, 181631, 181632, 181633, 181634, 181635, 181636, 181637, 181702, 181703, 181704, 181738, 181745, 181845, 182128, 182187, 182203, 182344, 182385, 182466, 182621, 182622, 182675, 183044, 183402, 183468, 183479, 183481, 183504, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 185775 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63828] = { ["id"] = 63828, ["name"] = "Mine's Bigger", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63828 }, ["description"] = "The Jailer has deployed a large number of newly forged constructs to oppose our forces. Fortunately, I was completely prepared for this possibility. I have readied our largest Centurion to repel this threat. Please Maw Walker, ride with our Centurion and direct it in combat.", ["objectivesText"] = "Use the Centurion Demolisher to eliminate the Jailer's constructs. Progress: Have we driven back their constructs?", ["rewardItems"] = { 181368, 181377, 181455, 181509, 181569, 181570, 181571, 181574, 181576, 181577, 181580, 181589, 181591, 181596, 181601, 181604, 181605, 181608, 181610, 181614, 181709, 181745, 182139, 182304, 182608, 182769, 183184, 183488, 183514, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840, 190641 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177175, ["x"] = 0.3975, ["y"] = 0.5425 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3975, ["y"] = 0.5425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63829] = { ["id"] = 63829, ["name"] = "No One Floats Down Here", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63829 }, ["description"] = "Now is our chance to free those we had assumed were lost! Many of our aspirants were seized by the Jailer to make troops for his army. Those that resisted him are locked in the cages that float above us, left there till their souls are broken. Shatter the Chains of Domination and free the Trapped Aspirants from the cages.", ["objectivesText"] = "8 Trapped Aspirants rescued.", ["rewardItems"] = { 181368, 181377, 181569, 181576, 181577, 181589, 181591, 181603, 181612, 181703, 184294, 184363, 184765, 184767, 184768, 184839 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63833] = { ["id"] = 63833, ["name"] = "Terrorizing the Tremaculum", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63833 }, ["description"] = "I am certain that my compatriots and generals have more specific tasks they require of you. But my request is simple. Our enemies currently surround us on all sides. Push them back and give us more room to operate.", ["objectivesText"] = "Kill 30 enemies in the Tremaculum. Progress: Our enemies surround us on all sides. You need not search far.", ["rewardItems"] = { 181176, 181179, 181185, 181186, 181199, 181200, 181202, 181211, 181212, 181224, 181504, 181545, 181546, 181547, 181548, 181550, 182724, 184147, 184150, 184777, 185854 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178006, ["x"] = 0.3, ["y"] = 0.17 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63834] = { ["id"] = 63834, ["name"] = "Weapons of the Tremaculum", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63834 }, ["description"] = "The venthyr of Sinfall do not waste souls, and her stoneborn do not waste armaments. Retrieve the tools of our enemies so that we may repurpose them for our army.", ["objectivesText"] = "Collect 6 Mawsworn Weapons , 6 Ghastly Crowns , and 6 Shade Eyes . Progress: Every weapon can be made to serve.", ["rewardItems"] = { 181176, 181178, 181182, 181187, 181189, 181192, 181193, 181196, 181198, 181203, 181204, 181210, 181211, 181212, 181215, 181216, 181217, 181334, 181545, 181546, 181547, 181548, 181550, 181756, 181776, 182137, 182141, 182201, 182681, 182686, 182752, 183197, 183484, 183507, 184147, 184150, 184777, 185911, 185912, 185913 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178066, ["x"] = 0.3, ["y"] = 0.17 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.3, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63835] = { ["id"] = 63835, ["name"] = "Wrath of the Party Herald", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63835 }, ["description"] = "Oh, you're back so soon, $p! ...Or have we not already met? It is difficult to remember at times... Regardless, I trust you are making progress with Cryptkeeper Kassir's plan to weaken our adversaries. Details of the plan escape me, but I am certain Temel was involved. I hear he fancies himself a \"party herald\" nowadays... < The Curator looks beyond you for a moment.> \"Party herald\"... I must have been gone from Revendreth for longer than I thought.", ["objectivesText"] = "Help Temel, the Party Herald, throw poison bombs at 50 enemies in the Tremaculum. Progress: You can find Temel on the ramparts near the Curator .", ["rewardItems"] = { 180847, 181175, 181185, 181192, 181193, 181200, 181201, 181205, 181206, 181217, 181467, 181510, 181545, 181546, 181547, 181548, 181550, 181708, 181827, 181836, 182109, 182325, 182448, 182449, 182480, 183469, 183499, 184147, 184150, 184777, 185942 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178078, ["x"] = 0.304, ["y"] = 0.165333 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178006, ["x"] = 0.3, ["y"] = 0.17 }, { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.304, ["y"] = 0.165333 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63836] = { ["id"] = 63836, ["name"] = "Fangcrack's Fan Club", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63836 }, ["description"] = "Fangcrack is the strongest dredger I e'er seen! He's incredible! He's down there, reaching into dat big Torghast portal, pulling the baddies right out o' their home! They don't even know what's happenin' half the time, ha ha! Me and Cudgelface joined his fan club soon as we got here. You want in? You gotta earn your membership same as everyone else: go down there and fight whatever he pulls out of the portal!", ["objectivesText"] = "Kill 12 Torghast enemies pulled out of the portal by Fangcrack. Progress: Looking for Fangcrack? Follow the cheering of his fans.", ["rewardItems"] = { 181175, 181176, 181180, 181182, 181185, 181188, 181194, 181197, 181198, 181200, 181204, 181205, 181206, 181545, 181546, 181547, 181548, 181550, 181708, 184147, 184150, 184777, 186969 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178112, ["x"] = 0.312, ["y"] = 0.154 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.312, ["y"] = 0.154 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63837] = { ["id"] = 63837, ["name"] = "A Tea for Every Occasion", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63837 }, ["description"] = "My dear $p! I knew you would arrive in the nick of time to save us all from the brink of boredom! I was just telling Niya here about the time you saved me from the Ember Ward through the healing power of tea! She is a bit skeptical. Perhaps you can help Tubbins and Gubbins show her that, through tea, all things are possible!", ["objectivesText"] = "Help Tubbins and Gubbins deliver tea to 15 allies in the Tremaculum. Progress: Tubbins is up on the ramparts with Theotar .", ["rewardItems"] = { 181176, 181177, 181182, 181183, 181190, 181192, 181193, 181198, 181199, 181205, 181206, 181210, 181211, 181545, 181546, 181547, 181548, 181550, 184147, 184150, 184777, 185942 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178178, ["x"] = 0.295, ["y"] = 0.179 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178006, ["x"] = 0.3, ["y"] = 0.17 }, { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.179 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63838] = { ["id"] = 63838, ["name"] = "Duelist's Challenge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63838 }, ["description"] = "<Nadjia continues to parry attacks from enemy Mawsworn while she turns to face you.> As you can see, we have our hands full here on the barricade. I will hold the line while you challenge the champions of the Mawsworn army. Defeat them in full view of their underlings. No mercy, $p. Demoralize them.", ["objectivesText"] = "Ask Boot the Beaut to throw you to the upper ramparts, then duel the champions of the Mawsworn army. Progress: Boot the Beaut can throw you up to the ramparts if needed.", ["rewardItems"] = { 181179, 181181, 181186, 181187, 181192, 181195, 181202, 181203, 181211, 181217, 181469, 181545, 181546, 181547, 181548, 181550, 181866, 182127, 182667, 182724, 183132, 184147, 184150, 184777, 185854 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178105, ["x"] = 0.315, ["y"] = 0.15 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.315, ["y"] = 0.15 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63839] = { ["id"] = 63839, ["name"] = "If Even One is Worthy", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63839 }, ["description"] = "I have seen firsthand that worthy souls have been unjustly cast into the Maw. Gresit here was almost cast in himself by the Lord Chamberlain's minion. He has more than proven himself under my care. Look among the souls that the Jailer's filth have deemed \"unworthy\". Inspect each to confirm that they deserve their fate. Even if we examine every soul in the Tremaculum and find only a single worthy one to bring back to Revendreth, it will still be valuable.", ["objectivesText"] = "Inspect Unworthy Souls in the Tremaculum until you find one that is truly worthy.", ["rewardItems"] = { 180847, 180943, 181176, 181177, 181178, 181181, 181182, 181183, 181184, 181187, 181189, 181192, 181193, 181195, 181196, 181198, 181200, 181203, 181204, 181212, 181215, 181218, 181334, 181467, 181498, 181506, 181545, 181546, 181547, 181548, 181550, 181708, 181842, 182126, 182338, 182460, 182480, 182584, 182648, 182736, 182750, 183476, 183482, 183500, 183502, 184147, 184150, 184587, 184777 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178063, ["x"] = 0.308, ["y"] = 0.16 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.308, ["y"] = 0.16 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63840] = { ["id"] = 63840, ["name"] = "They Grow Up So Quickly", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63840 }, ["description"] = "I know what you're thinking, but I have these gormlings completely under control! I picked up a trick or two at the venthyr's Ember Court for suppressing and controlling these troublemakers. If you wish to use their power to aid our battle, I will loan you my staff. With it you can choose a gormling that can be ordered to feed on the corpses of our enemies and grow in strength and size. You won't need many. Gormling grow quickly.", ["objectivesText"] = "Grow a gormling by feeding it corpses and ride it to victory! Progress: If you have lost your gormling, Niya up on the ramparts will have found it.", ["rewardItems"] = { 175740, 179513, 179517, 181403, 181404, 181405, 181406, 181457, 181459, 181477, 181479, 181541, 182605, 184378, 184381, 184382, 184383, 184384, 184519, 186089 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178179, ["x"] = 0.295, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178715, ["x"] = 0.255, ["y"] = 0.176 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.295, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63841] = { ["id"] = 63841, ["name"] = "The Skyhunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63841 }, ["description"] = "Boot the Beaut and the other large dredgers are being hit hard from air assaults. The dredgers may not be able to reach them, but the Wild Hunt can reach any prey. Take my spear and use it to ground the Mawsworn in the sky above the western bridge. Once they are grounded, they will be easy to dispatch. My trappers will help slow them down for you.", ["objectivesText"] = "Use Korayn's Spear to pull 8 Mawsworn Skylurkers to the ground and kill them. Progress: The Mawsworn flyers appear to be focusing their attention on the western bridge.", ["rewardItems"] = { 175728, 179562, 179604, 181399, 181402, 181403, 181404, 181405, 181406, 181407, 181410, 181457, 181459, 181477, 181479, 181541, 183489, 184378, 184381, 184382, 184383, 184384, 184519, 185949 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178180, ["x"] = 0.294, ["y"] = 0.18 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.294, ["y"] = 0.18 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63842] = { ["id"] = 63842, ["name"] = "That's a Good Trick", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63842 }, ["description"] = "These cruel tormentors make me so mad... The Jailer's bullies torture good souls sent here unjustly because no one will stand up to them! Well, I am here now, and I have the perfect plan to make them pay. What do you say? Want to help me turn the tables on these bullies?", ["objectivesText"] = "Shrink 15 enemies and enlarge 4 Mawrats to eat them in the Tremaculum! Progress: Well, if Lady Moonberry thinks it wise...", ["rewardItems"] = { 179537, 179562, 179584, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181414, 181416, 181418, 181419, 181420, 181421, 181459, 181477, 181479, 181541, 181738, 184378, 184381, 184382, 184383, 184384, 184519, 186102 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178172, ["x"] = 0.298, ["y"] = 0.17 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178228, ["x"] = 0.285, ["y"] = 0.154 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.298, ["y"] = 0.17 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63843] = { ["id"] = 63843, ["name"] = "Heart and Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63843 }, ["description"] = "The Forsworn that serve the Jailer dominate the skies above, but we know their weakness and shall use it against them. Under my direction Mikanikos has created a supply of Trueheart Spears for our Protectors. When hit by these spears the Mawsworn will be weakened with their soul laid bare as they face their true self. Collect the Trueheart Spears and use them to defeat the Mawsworn Myrmidons that fly above us.", ["objectivesText"] = "Collect 6 Trueheart Spears and defeat 6 Mawsworn Myrmidons . Progress: Have the Forsworn been defeated?", ["rewardItems"] = { 180944, 181368, 181377, 181569, 181577, 181587, 181591, 181603, 181605, 181627, 181632, 181633, 181635, 181636, 181637, 181702, 181704, 181738, 181745, 182128, 182203, 182385, 182675, 182736, 182743, 183402, 183481, 183482, 184294, 184362, 184765, 184766, 184767, 184768, 185829 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177226, ["x"] = 0.396, ["y"] = 0.537 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.396, ["y"] = 0.537 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63846] = { ["id"] = 63846, ["name"] = "The Ember Count", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63846 }, ["description"] = "Theotar's brilliance is undeniable, but far too many overlook the ingenuity of his dredger helpers, Gubbins and Tubbins. Look to that ridge beyond us. The Jailer's forges over there are spewing out Soulsteel Embers . We could accomplish many things with a mirror made from them... Gubbins has already crafted a special parasol, capable of shielding its wielder from any falling embers. Meet him by the forges and obtain some of those Soulsteel Embers !", ["objectivesText"] = "Slay 4 Enraged Forgeshard and Collect 4 Soulsteel Embers . Progress: Have you acquired the embers?", ["rewardItems"] = { 181176, 181178, 181184, 181189, 181191, 181192, 181196, 181198, 181200, 181202, 181224, 181545, 181546, 181547, 181548, 181550, 181712, 181769, 182469, 182743, 183467, 184147, 184150, 184777, 185839, 185942 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178091, ["x"] = 0.43, ["y"] = 0.442 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178091, ["x"] = 0.43, ["y"] = 0.442 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.43, ["y"] = 0.442 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63853] = { ["id"] = 63853, ["name"] = "Kill the Flame", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63853 }, ["description"] = "Can you see it? Just out of the corner of my eye, it's always there... glowing so brightly! How is one supposed to relax and enjoy a cup of tea while that reminder of fire and ash is around. Please Maw Walker do me a favor... remove it so that we may all enjoy a cup of my favorite blend!", ["objectivesText"] = "Kill Infernus the Infinite for Theotar . Progress: Have you killed that dreadful creature?", ["rewardItems"] = { 180943, 181178, 181184, 181191, 181193, 181196, 181545, 181546, 181547, 181548, 181550, 181640, 181708, 181842, 182338, 182584, 183468, 183470, 184147, 184150, 184587, 185829, 185942 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63858] = { ["id"] = 63858, ["name"] = "Courage of the Soul", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63858 }, ["description"] = "In this time of conflict, we are all tested, Maw Walker. It takes great bravery and strength of soul to confront our enemies without fear. Wade into their lines and show them the power of your courage.", ["objectivesText"] = "Eliminate 15 of the Jailer's forces in Cocyrus and Zovaal's Cauldron.", ["rewardItems"] = { 181368, 181377, 181435, 181569, 181571, 181572, 181574, 181577, 181580, 181581, 181585, 181589, 181591, 181594, 181596, 181599, 181602, 181604, 181605, 181606, 181608, 181609, 181611, 181614, 181627, 181630, 181632, 181633, 181635, 181636, 181637, 181702, 181703, 181704, 181745, 182584, 183476, 184294, 184362, 184765, 184766, 184767, 184768, 184839, 190641 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178227, ["x"] = 0.408, ["y"] = 0.503333 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.408, ["y"] = 0.503333 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63859] = { ["id"] = 63859, ["name"] = "Saved By The Bells", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63859 }, ["description"] = "Our stewards are preparing Reinforcement Bells to summon additional Kyrian to aid in our assault. However, the Mawsworn have been attacking the stewards in order to disrupt their efforts. We need you to defend our stewards while they complete their work, then ring each bell to call in reinforcements.", ["objectivesText"] = "Defend and ring the Reinforcement Bell West , East, and South.", ["rewardItems"] = { 181377, 181573, 181574, 181575, 181576, 181583, 181585, 181587, 181601, 181602, 181603, 181609, 181610, 181611, 181612, 181614, 181627, 181628, 181629, 181630, 181631, 181632, 181634, 181636, 181637, 181745, 182336, 182441, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 184839, 184840 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.448 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63860] = { ["id"] = 63860, ["name"] = "Talisman of the Eternal Scholar", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63860 }, ["description"] = "<The talisman is dented and spattered with muck. Whoever stashed this here handled it roughly. Archivist Roh-Suir has a spot for this talisman in the Reliquary of Remembrance.>", ["objectivesText"] = "Bring the Damaged Talisman to Archivist Roh-Suir in the Reliquary of Remembrance. Provided item:", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 185914 } },
[63861] = { ["id"] = 63861, ["name"] = "Beginning the Collection", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63861 }, ["description"] = "Let us continue our work by retrieving the most important item of any scholarly study--the lost codex. It will take some time, but as we continue our work the pages of this work will continue to grow and flourish, just as Korthia has itself for eons. As for its location, it previously resided deep within the underbelly of Korthia itself inside the Cavern of Contemplation to the south. We can only hope the Jailer's forces have yet to locate it.", ["objectivesText"] = "Recover the Codex of Memories for Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Have you found the codex? I hope we're not too late.", ["rewardItems"] = { 185636, 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[63863] = { ["id"] = 63863, ["name"] = "United In Pride", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63863 }, ["description"] = "Despite our competitive differences, Nemea and I work as a team when faced with greater threats. The pride and the phalynx are both fierce fighters upon the battlefield. We would both be honored to assist you in the battle that lies ahead. Please allow either Andira or Gatamatos to assist you in defeating the Jailer's champions that threaten our forces.", ["objectivesText"] = "Defeat Malfestus , Domonous , and Furis. Progress: With those champions defeated our forces can push forward.", ["rewardItems"] = { 181368, 181377, 181569, 181573, 181574, 181583, 181585, 181602, 181610, 181611, 181628, 181629, 181630, 181631, 181632, 181634, 181745, 182107, 182307, 182469, 182743, 183467, 183479, 183483, 184294, 184362, 184363, 184765, 184766, 184767, 184768, 185829 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178353, ["x"] = 0.428, ["y"] = 0.455 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 177900, ["x"] = 0.428, ["y"] = 0.448 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.428, ["y"] = 0.455 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63864] = { ["id"] = 63864, ["name"] = "The Dreadful Blend", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63864 }, ["description"] = "Gravedust and Stipple Weed is a dreadful flavor combination, and Tubbins made a very large batch of tea with those ingredients. It was so horrid that I tossed the entire pot of tea on the fire. It turns out to be very wet, and an excellent extinguisher of flames! Tubbins will haul the entire batch with you. Put it to good use, by tossing it on the Volatile Embersparks around Zovaal's Cauldron.", ["objectivesText"] = "Extinguish 30 Volatile Embersparks . Progress: Please, I hope you did not drink that.", ["rewardItems"] = { 181175, 181177, 181183, 181184, 181185, 181190, 181191, 181192, 181193, 181199, 181200, 181201, 181205, 181206, 181211, 181224, 181545, 181546, 181547, 181550, 184147, 184150, 184777 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178005, ["x"] = 0.429, ["y"] = 0.445 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.429, ["y"] = 0.445 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63892] = { ["id"] = 63892, ["name"] = "Diviner's Rune Chits", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63892 }, ["description"] = "<Inside the pouch is a single rune chit . It rotates and flips as if moved by an unseen hand. Runes vaguely reminiscent of the Vrykul language are delicately carved into the stone. On the back of the chit is an indication that it is part of a set.>", ["objectivesText"] = "Collect 20 rune chits , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Goodness, is that a pouch of rune chits ? How many do you have?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185968, 185971, 186101, 186157, 186685, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187154, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187055 } },
[63899] = { ["id"] = 63899, ["name"] = "Book of Binding: The Mad Witch", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63899 }, ["description"] = "<You hear a muffled voice speaking from within this book, interspersed with crackling static. Though the utterances are mostly unintelligible, you can make out the repeated request to recover crimson pages . Flipping through the volume, you note that many of its pages are missing. If the pages were retrieved, the book could be returned to the Archivist and reassembled.>", ["objectivesText"] = "Collect 12 Crimson Pages , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: Is that book... speaking?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185962, 185963, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187055, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187206 } },
[63903] = { ["id"] = 63903, ["name"] = "Storming the Sanctum", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63903 }, ["description"] = "The Jailer has seized the sigils of all four covenants. It is clear he means to escape the Maw and steal the Arbiter's sigil from Oribos. We cannot allow this to happen. Atop Torghast sits the Sanctum of Domination , the Jailer's seat of power. The time has come to enter this dark domain. No doubt Sylvanas Windrunner will command the forces that will attempt to thwart us. We must defeat her... and save Anduin Wrynn from her grasp. Gather your forces, <name>. The Ebon Blade will stand with you.", ["objectivesText"] = "Defeat Sylvanas Windrunner in the Sanctum of Domination . Progress: How fares the battle in the Sanctum?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 187175 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 177228, ["x"] = 0.629, ["y"] = 0.246 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.629, ["y"] = 0.246 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "raid" },
