[63919] = { ["id"] = 63919, ["name"] = "Book of Binding: The Tormented Sorcerer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63919 }, ["description"] = "<You hear a muffled voice speaking from within this book, interspersed with crackling static. Though the utterances are mostly unintelligible, you can make out the repeated request to recover azure pages . Flipping through the volume, you note that many of its pages are missing. If the pages were retrieved, the book could be returned to the Archivist and reassembled.>", ["objectivesText"] = "Collect 10 azure pages , then bring them to Archivist Roh-Suir in the Reliquary of Remembrance. Progress: I find these strange speaking tomes... discomfiting.", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186731, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179956, ["x"] = 0.608, ["y"] = 0.348 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.608, ["y"] = 0.348 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187210 } },
