[63945] = { ["id"] = 63945, ["name"] = "The Soul Blade", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63945 }, ["description"] = "The runeblade of a Necrolord can be a potent weapon in this realm. An abundance of souls are willing to contribute their anima to end their own suffering and bring defeat to the Jailer. Take one of my runeblades and charge it with the anima of the willing souls you find here. Once charged, use it lay waste to their forces here.", ["objectivesText"] = "Charge Heirmir's Runeblade with Willing Souls and use it to slay the Eye of Gorgoa . Progress: Has my blade tasted victory?", ["rewardGold"] = 808800, ["rewardXP"] = 12280, ["rewardItems"] = { 181501, 181503, 181506, 181626, 181645, 181647, 181649, 181671, 181672, 181673, 181674, 181675, 181686, 184305, 184772, 184773, 184774, 184775, 184776, 186097 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178690, ["x"] = 0.222, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178887, ["x"] = 0.221333, ["y"] = 0.447333 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63951] = { ["id"] = 63951, ["name"] = "A Shady Place", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63951 }, ["description"] = "Existence is not a simple thing, $p. It is layers upon layers of realities. The Jailer's traps are pulling our troops into one such rift, hidden from normal sight. I have obtained an Unbalanced Riftstone . It will give you the ability to enter the rift and destroy the traps keeping our troops trapped inside, before they are lost forever. After you've destroyed the Rift-Veiled Traps , exit the rift and pull the trapped soldiers back into our reality.", ["objectivesText"] = "Use the Unbalanced Riftstone to enter the rift and break Rift-Veiled Traps to free $1a Riftbound Vorkai . Progress: There is much we cannot see.", ["rewardItems"] = { 181503, 181507, 181625, 181638, 181645, 181649, 181651, 181652, 181653, 181654, 181655, 181664, 181665, 181666, 181667, 181670, 181681, 181682, 181688, 181689, 181690, 181691, 181693, 181694, 181697, 184305, 184772, 184773, 184774, 184775, 184776, 186190, 186191, 186300, 186310, 186713, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178890, ["x"] = 0.225, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178890, ["x"] = 0.225, ["y"] = 0.432 }, { ["mapID"] = 1543, ["npcID"] = 178891, ["x"] = 0.223333, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63952] = { ["id"] = 63952, ["name"] = "Heavy-Handed Tactics", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63952 }, ["description"] = "We need more constructs on the front lines, but we have no bodies, heads, or legs! Rathan's making the best constructs possible with what we DO have... a lot of hands. Don't ask questions! There are enemies in Calcis that we need dead. Take the hands and kill things!", ["objectivesText"] = "Slay 8 Mawsworn Soulbreakers , 4 Crystalline Guardians , Lady Nalis , and Glassmaker . Progress: Rathan is nothing if not resourceful.", ["rewardItems"] = { 181503, 181507, 181625, 181647, 181649, 181656, 181657, 181658, 181659, 181685, 181688, 181691, 184305, 184772, 184773, 184774, 184775, 184776 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178745, ["x"] = 0.228, ["y"] = 0.425 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178891, ["x"] = 0.223333, ["y"] = 0.444 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.425 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63953] = { ["id"] = 63953, ["name"] = "Korrak's Revenge", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "none", ["categories"] = { "bonusobjective" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["storyline"] = { 63953 }, ["rewardItems"] = { 172022, 172023 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard", ["db2QuestInfoID"] = 283, ["db2QuestInfoName"] = "Bonus Objective with Completion Toast" },
[63954] = { ["id"] = 63954, ["name"] = "Sealed Secrets", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63954 }, ["description"] = "Ah, Korthia . What secrets will be revealed? My associates have been hard at work, seeking to discover and procure various small items of interest throughout this broken land. Nothing of great importance, I assure you. They have secured those items in designated drop boxes, and those now await pickup in Seeker's Quorum. Don't worry, they are locked with an impenetrable seal to protect both the contents and the deliverer. Bring those sealed containers to me, and I will reward you handsomely.", ["objectivesText"] = "Retrieve 5 Sealed Containers from the Seeker's Quorum. Progress: Do you have the sealed containers ?", ["rewardItems"] = { 184374, 185855, 185856, 185857, 185858, 185859, 185860, 185861, 185862, 185863, 185864, 185865, 185866, 185867, 185868, 185869, 185870, 185871, 185872, 185873, 185874, 185875, 185876, 185877, 185878, 185879, 185880, 185881, 185882, 185883, 185884, 185885, 185886, 185887, 185888, 185889, 185890, 185891, 185893, 185894, 185895, 185896, 185897, 185898, 185899, 185900, 185901, 185903, 185905, 185941, 185944, 186017, 186155, 186156, 186167, 186175, 186201, 186205, 186206, 186663, 186664, 186665, 186666, 186667, 186668, 186669, 186670, 186734, 186735, 186736, 186737, 186738, 186739, 186740, 186741, 186742, 186743, 186744, 186745, 186746, 186747, 186748, 186749, 186750, 186751, 186752, 186753, 186754, 186755, 186756, 186757, 186758, 186759, 186760, 186761, 186762, 186763, 186764, 186765, 186766, 186767, 186768, 186769, 186770, 186771, 186976, 187506, 187507 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178845, ["x"] = 0.645333, ["y"] = 0.254667 } }, ["coords"] = { ["mapID"