[63969] = { ["id"] = 63969, ["name"] = "Looming Darkness", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63969 }, ["description"] = "The Winter Queen called for a hunt in this location due to reports of a massive, unnatural darkness swelling in its upper regions. The Wild Hunt is brave, but not foolish. We must learn what we can about this darkness before we charge into it. Search the bodies of our enemies nearby for clues.", ["objectivesText"] = "Collect 1 Mawsworn Ritual Book , 10 Mawsworn Missive Scraps , and 15 Dark Marrow . Progress: Have you learned anything regarding the darkness yet?", ["rewardItems"] = { 175713, 175740, 179513, 179517, 179532, 181398, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181422, 181423, 181424, 181425, 181426, 181427, 181428, 181429, 181459, 181477, 181479, 181541, 182624, 183396, 183473, 183491, 184378, 184381, 184382, 184383, 184384, 184519, 186300, 186309, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 }, { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.225, ["y"] = 0.433 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63970] = { ["id"] = 63970, ["name"] = "No Soul Left Behind", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63970 }, ["description"] = "Do you hear the cries of tormented souls trapped in Gorgoa? The twisted river of souls flows before us, swelling with cruelty and the torment of undeserving victims. Our brave regiment of druid spirits led the charge into the river to seek out those lost souls, but I fear many have instead joined in their suffering. Summon your courage and take my cradle with you into the river. Load the lost souls you find onto the cradle, then order the cradle to come back to me.", ["objectivesText"] = "Use Thiernax 's Rescue Cradle to rescue 12 Lost Druids in Gorgoa and send them back to Thiernax . Progress: I admire Thiernax 's dedication to even the least among us.", ["rewardItems"] = { 179508, 179513, 179517, 179532, 179537, 179547, 181405, 181426, 181427, 181428, 181429, 181455, 181477, 181479, 181541, 181735, 181736, 182136, 182657, 182769, 183487, 183488, 184378, 184381, 184382, 184383, 184384, 184519, 186300, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178884, ["x"] = 0.228, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178884, ["x"] = 0.228, ["y"] = 0.432 }, { ["mapID"] = 1543, ["npcID"] = 178892, ["x"] = 0.224, ["y"] = 0.451 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.228, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63971] = { ["id"] = 63971, ["name"] = "Snail Stomping", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63971 }, ["description"] = "Careful where you step. You wouldn't want to accidentally squish a Mawsworn, would you? Of course you would! It's so fun! < Lady Moonberry giggles and points at the snails around her.> It's so much easier to squish Mawsworn after you've transformed them into stinky little snails. Here, take my wand and try it out on whatever you like. You may need to weaken them a bit first, but it'll work on almost anything!", ["objectivesText"] = "Use Lady Moonberry's Wand to transform 15 weakened enemies into snails, and then squish them! Progress: Lady Moonberry never ceases to surprise me.", ["rewardItems"] = { 137663, 175728, 181398, 181413, 181430, 181457, 181477, 181479, 181541, 184378, 184381, 184382, 184383, 184384, 184519, 186199 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 178885, ["x"] = 0.226, ["y"] = 0.436 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.436 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63972] = { ["id"] = 63972, ["name"] = "Just Don't Ask Me to Spell It", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63972 }, ["description"] = "It's getting dangerous out there for druid spirits! Thankfully, we always have room for another friend in our group, and this fine tirnenn has offered to help me and the gang get around the battlefield safely. <The tirnenn behind Choofa begins speaking slowly, but Choofa just talks louder.> Good ol' Kirriprkar- I mean, Karripkraker- I mean, Krackerkrisp... < Choofa laughs.> Let's just call her \"Big K\"! Hop on, everybody!", ["objectivesText"] = "Help Krrprripripkraak and her friends sow chaos in the Crucible of the Damned. Progress: Krrprripripkraak and Choofa are teaming up? This, I must see.", ["rewardItems"] = { 175740, 179508, 179513, 179517, 179532, 179547, 181398, 181399, 181403, 181404, 181405, 181406, 181407, 181408, 181409, 181410, 181411, 181412, 181413, 181421, 181458, 181459, 181477, 181479, 181541, 184378, 184381, 184382, 184383, 184384, 184519, 186654 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179066, ["x"] = 0.22, ["y"] = 0.432 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 }, { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.22, ["y"] = 0.432 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63973] = { ["id"] = 63973, ["name"] = "Double Dromans", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63973 }, ["description"] = "Relax, $p. Breathe. < Dreamweaver inhales and exhales slowly.> Things are getting tense around here, but that doesn't mean YOU need to be tense. Everything is going to be okay. If you don't believe me, let the mighty deeds of Droman Aliothe and Droman Tashmur reassure you. They headed up the hill together to clear a path for the rest of us. They'll have everything taken care of in no time.", ["objectivesText"] = "Help Droman Aliothe defeat enemies along her path and kill Lord Dretnal . Progress: You can find the droman up the hill from here.", ["rewardItems"] = { 175713, 175740, 179500, 179508, 179513, 179517, 179532, 179537, 179547, 179562, 179584, 179604, 181399, 181400, 181401, 181402, 181403, 181404, 181405, 181406, 181413, 181477, 181479, 181541, 182456, 182686, 183484, 184378, 184381, 184382, 184383, 184384, 184519, 186300, 186310, 187012, 187347 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179067, ["x"] = 0.226, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.226, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63974] = { ["id"] = 63974, ["name"] = "That's Going to Sting", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 63974 }, ["description"] = "< Niya speaks loudly to be heard over the buzzing coming from the collection of needler nests behind her.> I've caught Moonberry trying to steal these nests for her pranks over ten times already! The other faeries said I was crazy to bring the needlers out here. Too wild! Too unpredictable! But that's exactly why we need them. Lord Herne 's scouts report powerful Heralds among our enemy's forces. Take one of these nests, and use it to surprise the Heralds!", ["objectivesText"] = "Use an Angry Needler Nest to weaken and kill Herald Gkeca , Herald Throgtu , and Herald Duarri . Progress: Niya is proving to be quite the clever tactician...", ["rewardItems"] = { 175713, 175728, 175740, 179562, 181398, 181411, 181412, 181413, 181457, 181458, 181459, 181477, 181479, 181541, 182559, 184378, 184381, 184382, 184383, 184384, 184519, 186569 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179065, ["x"] = 0.222, ["y"] = 0.435 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 178828, ["x"] = 0.225, ["y"] = 0.433 }, { ["mapID"] = 1543, ["npcID"] = 178829, ["x"] = 0.222, ["y"] = 0.45 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.222, ["y"] = 0.435 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[63989] = { ["id"] = 63989, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 63989 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! Can you take Plaguey with you and test their ability to infect organic life forms?", ["objectivesText"] = "Help Plaguey test their infection ability in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 137663, 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64012] = { ["id"] = 64012, ["name"] = "Supplies from Death's Advance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64012 }, ["description"] = "Your work toward stopping the Jailer's advances has not gone unnoticed. If it is power you seek to continue your efforts I believe I can be of some assistance.", ["objectivesText"] = "Speak with Duchess Mynx at Keeper's Respite in Korthia .", ["rewardItems"] = { 186650 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2471, ["threshold"] = 10000 } } } },
[64015] = { ["id"] = 64015, ["name"] = "Into the Meat Grinder", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64015 }, ["description"] = "All these mawsworn have got me excited for some slaughter! I've got a plan that probably won't end in you dying. Are you in?", ["objectivesText"] = "Lay a trap for the Mawsworn.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.275 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178805, ["x"] = 0.6, ["y"] = 0.275 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6, ["y"] = 0.275 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64016] = { ["id"] = 64016, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64016 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Ooz, I'd like to know if they are able to consume organic material and increase in size.", ["objectivesText"] = "Help Ooz test their growth ability on Shardhide in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 137663, 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64017] = { ["id"] = 64017, ["name"] = "Oozing with Character", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64017 }, ["description"] = "Apprentice! I've been looking for you. Kevin has been such a wonderful helper in our experiments, I'd like to train my other oozes to be able to assist as well! For Bloop, I'd like to know if their ooze is capable of propagation. Take them with you, and find those bears. Give them the command to inject the life form with their ooze and see what happens.", ["objectivesText"] = "Help Bloop test their propagation ability in the Mauler's Outlook. Progress: They're good oozes, <name>.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 186548, 187000, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178806, ["x"] = 0.605, ["y"] = 0.277 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.605, ["y"] = 0.277 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64018] = { ["id"] = 64018, ["name"] = "The Weight of Stone", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64018 }, ["description"] = "The campaign continues, $p. The Stone Legion is here to turn the tide of battle. First, we must deliver supplies to our allies. The broken land of Korthia means we are the only ones who can keep our troops supplied. Second, we must deal with the mawsworn and the devourers. I have a very simple strategy. We are going to drop anima onto the mawsworn. That will attract the devourers to attack. Either they kill the mawsworn, or the mawsworn kills them. Regardless, we win.", ["objectivesText"] = "Assist the Stone Legion in delivering supplies and anima.", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178794, ["x"] = 0.615, ["y"] = 0.251 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178794, ["x"] = 0.615, ["y"] = 0.251 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.251 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64080] = { ["id"] = 64080, ["name"] = "Down to Earth", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64080 }, ["description"] = "I can hear the wings of the Mawsworn in the sky up above, taunting us. But a bird in the hand can be crushed. Take my spear and prove your aim. Pull a few down and smite them. Be sure to use the spear. Do not traipse among them so that they will chase you back down to the ground. That's not the point. I want to see you drag them out of the sky.", ["objectivesText"] = "Use Korayn's Javelin to spear 4 Mawsworn Harbingers.", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 186474, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178841, ["x"] = 0.609, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178841, ["x"] = 0.609, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.609, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64083] = { ["id"] = 64083, ["name"] = "Sinfall Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 64083, 64325 }, ["description"] = "Sinfall is gaining more respect than Denathrius could have ever hoped to earn! It is all thanks to your efforts, <name>. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1256, ["name"] = "Sinfall Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64084] = { ["id"] = 64084, ["name"] = "Necrolord Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 64084, 64324 }, ["description"] = "You have brought great honor to the Necrolords. Such honor attracts the attention of others yet again. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1254, ["name"] = "Necrolord Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64085] = { ["id"] = 64085, ["name"] = "Night Fae Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 64085, 64322 }, ["description"] = "Your bravery has allowed Ardenweald to grow once again. It has also once again drawn the attention of brokers. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1255, ["name"] = "Night Fae Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64086] = { ["id"] = 64086, ["name"] = "Kyrian Tactician", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 64086, 64323 }, ["description"] = "Look around you, <name>. Elysian Hold stands as a testament to the progress we have made thanks to you. Zo'sorg", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1253, ["name"] = "Kyrian Combatant", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64103] = { ["id"] = 64103, ["name"] = "Old Tricks Work Best", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64103 }, ["description"] = "$p. Here we are again, fighting alongside each other to protect the Shadowlands. We're waging a losing war, but we might be able to turn the tide. I need you to seek out some very specific commanders of the Mawsworn forces. In every army, there's good commanders and bad ones. By taking out the good ones, only the bad ones advance, weakening the force as a whole. Our Eyes have brought us the names. Now I just need you to kill them.", ["objectivesText"] = "Kill Moros , Oizys , and Apate , commanders of the Mawsworn.", ["rewardItems"] = { 185011, 185012, 185013, 185014, 185015, 185016, 185017, 185018, 185019, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178808, ["x"] = 0.606, ["y"] = 0.28 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178808, ["x"] = 0.606, ["y"] = 0.28 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.28 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64104] = { ["id"] = 64104, ["name"] = "Think of the Critters", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64104 }, ["description"] = "The wildlife of Korthia have been through so much. Some of them can't seem to find enough to eat. I've saved some extra food that we can share with them. But I'm worried that they might be too shy to trust us, and I don't blame them! Here. Take these treats and see if you can get close enough to them to feed them properly. Even small creatures are so important.", ["objectivesText"] = "Approach and feed Hungry Gromits in Korthia .", ["rewardItems"] = { 71076, 182180, 183395, 184396, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 186561, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178839, ["x"] = 0.614, ["y"] = 0.215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178839, ["x"] = 0.614, ["y"] = 0.215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64129] = { ["id"] = 64129, ["name"] = "Charge of the Wild Hunt", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64129 }, ["description"] = "Ever since I joined the Wild Hunt I've learned so much about how to fight and how to defend the realms. I admit I'm still learning. But I am so glad to be learning alongside you, and my runestag friend, Aldermeigh . Aldermeigh is being trained to charge into battle with the bravery of a vorkai, but he needs practice. Will you take him out for a ride, and mow down all the Mawsworn you can?", ["objectivesText"] = "Mount Aldermeigh and slay Mawsworn in Korthia .", ["rewardItems"] = { 182180, 184948, 184949, 184950, 184951, 184952, 184953, 184954, 184955, 184956, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178840, ["x"] = 0.61, ["y"] = 0.212 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.61, ["y"] = 0.212 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64166] = { ["id"] = 64166, ["name"] = "Random Memory Access", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64166 }, ["description"] = "When the Jailer snared Korthia and dragged it toward the Maw, he destroyed so much in this place. Not only mountains and buildings, but the people, too. Those people had lives, hopes, memories. I have to think that they can't all be gone, and we might be able to save something of them that lingers. Here, take some of my power. See if you can collect those memories. Bring them to me, and I'll keep them safe. No one should be forgotten.", ["objectivesText"] = "Collect Korthian Memories using the Ephemeral Wings .", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 186672, 187184, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179134, ["x"] = 0.618, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64167] = { ["id"] = 64167, ["name"] = "Pets Detective", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 7502, ["storyline"] = { 64167 }, ["description"] = "I'm so glad you're here, <name>! I've been expecting a delivery of pet supplies and some new pets. But my distribution manager, Zantini has not reported in. I suspect foul play. There's been some shady people eyeballing my store for a while now. But I haven't been able to leave the store and track them down. You can. Take my pet cat, Fiona, and find these well hidden spies.", ["objectivesText"] = "Investigate the city of Dalaran with Breanni 's special spy catching cat, Fiona. Progress: What have you learned, <name>?", ["rewardGold"] = 29500, ["rewardXP"] = 25, ["rewardItems"] = { 186553, 186695, 186772, 187128 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard" },
[64184] = { ["id"] = 64184, ["name"] = "Missing Friend", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "none", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10472, ["storyline"] = { 64184 }, ["rewardXP"] = 2090, ["rewardItems"] = { 31666 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10472 } }, ["questType"] = "standard" },
[64194] = { ["id"] = 64194, ["name"] = "War Prototype", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64194 }, ["description"] = "As Forgelite Prime, I always work to make something better! But largest centurions, they are much too large to bring to Korthia . This, I fix. Here is Atleos , field colossus prototype. Vanguard of the Kyrian! It needs testing. More testing. Must be perfect against a powerful opponent. Go, take Atleos and defeat a great Maw beast! Press all the buttons!", ["objectivesText"] = "Use the Atleos prototype in the Windswept Aerie to defeat Kraxis . Progress: You have work still, yes?", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64196] = { ["id"] = 64196, ["name"] = "Pet Up", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7502, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "It sounds like some group of pet poachers are up to no good in the Eye of Azshara . My supply manager's flight path takes him right over that area! Zantini and his pets, Strigfellow and Speedy IV , were bringing back a rare murloc pet, along with some other pets and supplies. <name>, please find Zantini and his pets. Help them out. Then we can try to recover the pets and the supplies.", ["objectivesText"] = "Find and help Zantini and his pets along the coast of the Eye of Azshara .", ["rewardGold"] = 34100, ["rewardXP"] = 25, ["rewardItems"] = { 79869, 87399, 89125, 91086, 116415, 143753, 151191, 163036, 165835, 169665, 174360, 184373, 184374, 186553, 186695, 186772, 187128, 198725, 198726, 237812, 263871 }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7502 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64202] = { ["id"] = 64202, ["name"] = "Gotta Hand It To Ya", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["storyline"] = { 64202 }, ["description"] = "Your power Maw Walker... it rivals even mine before Zovaal separated my body. This is but a small part of my whole, but more than enough... Allow me to aid you in your efforts against Zovaal. In doing so my vengeance will be fulfilled.", ["objectivesText"] = "Accept Nilganihmaht's help.", ["rewardItems"] = { 184513, 185972, 185973, 186653, 186654, 186713, 226506 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = {} }, ["questType"] = "standard" },
[64203] = { ["id"] = 64203, ["name"] = "The Coast is Clear", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "I was on the last leg of a supply run when we were shot down! They took the pets, but the supplies are scattered over this stretch of beach. I don't know what they're planning, but I know we gotta get our supplies. You an' me, we ain't subtle.... But Speedy IV ... He won't cause all them pirates to go into hiding. He can get the supplies while Stringfellowe surveils the area from the air. Speedy's fond of you, so chat him up and let's try to recover the smoldering supplies before they all burn up.", ["objectivesText"] = "Gather pet supplies along the shores of Eye of Azshara with Speedy IV . Progress: Supplies are always in need.", ["rewardGold"] = 154900, ["rewardXP"] = 100, ["rewardItems"] = { 183395, 184396, 186553, 186695, 186730, 186772, 187005, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 1, ["flags"] = 0 } } },
[64215] = { ["id"] = 64215, ["name"] = "Paw Patrol", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "While Speedy IV was collecting supplies, Stringfellowe was scouting the rest of the Eye of Azshara . Turns out there is a whole mess of pirates to the west. That must be where the pets are at. Head over there and rescue the pets.", ["objectivesText"] = "Obtain keys from the Violetsail pirates along the west coast of the Eye of Azshara . Then set the captured pets free. Progress: Have you found them, <name>?", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 55053, 77532, 82960, 130250, 159825, 159826, 171441, 186553, 186695, 186772, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["ends"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 790, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 2, ["flags"] = 0 } } },
[64237] = { ["id"] = 64237, ["name"] = "Gurgl and the Bandit", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 7578, ["mapID"] = 790, ["storyline"] = { 64196, 64203, 64215, 64237 }, ["description"] = "We've got all the pets back except Gurgl . <name>, we need to get that pet back for Breanni . Stringfellowe saw a nook where we think the leader of these pet poachers is hiding out. Let's get 'em!", ["objectivesText"] = "Find and battle the leader of the pet poachers.", ["rewardGold"] = 309800, ["rewardXP"] = 200, ["rewardItems"] = { 93040, 186553, 186695, 186772, 187128 }, ["starts"] = { { ["mapID"] = 790, ["npcID"] = 179566, ["x"] = 0.732, ["y"] = 0.748 } }, ["coords"] = { ["mapID"] = 790, ["source"] = "quest_giver", ["x"] = 0.732, ["y"] = 0.748 }, ["mapCandidates"] = { ["npc"] = { 790 }, ["zone"] = { 7578 } }, ["questType"] = "standard", ["db2PoiMapID"] = 1220, ["db2PoiUiMapID"] = 627, ["questLines"] = { { ["id"] = 1251, ["name"] = "Stolen Pet Supplies", ["orderIndex"] = 3, ["flags"] = 0 } } },
[64240] = { ["id"] = 64240, ["name"] = "Flight of the Kyrian", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64240 }, ["description"] = "We've engaged in a heavy battle at the entrance to the Vault of Secrets! Our forces could use some reinforcement. Please, guide my fellow Ascended to give support to our fighters there. The fighters on the ground can handle the clean-up, but they need shields and healing. Good luck!", ["objectivesText"] = "Assist covenant forces from the air at the Vault of Secrets. Progress: Have you helped our forces at the Vault of Secrets?", ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 186201, 186205, 186206, 187184, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179194, ["x"] = 0.616, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.616, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64255] = { ["id"] = 64255, ["name"] = "Party Time", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13329, ["mapID"] = 1525, ["storyline"] = { 64255 }, ["objectivesText"] = "Progress: Oh neat that looks like Temel's hat!", ["rewardItems"] = { 180752 }, ["starts"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["ends"] = { { ["mapID"] = 1525, ["npcID"] = 173721, ["x"] = 0.364, ["y"] = 0.466 } }, ["coords"] = { ["mapID"] = 1525, ["source"] = "quest_giver", ["x"] = 0.364, ["y"] = 0.466 }, ["mapCandidates"] = { ["npc"] = { 1525 }, ["zone"] = { 13329 } }, ["questType"] = "standard" },
[64266] = { ["id"] = 64266, ["name"] = "Supplies from The Archivists' Codex", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64266 }, ["description"] = "I have no words to express the warmth that fills me knowing your dedication has ensured Korthia's history remain intact. Please. Allow me to share my gratitude.", ["objectivesText"] = "Speak with Archivist Roh-Suir in the Reliquary of Remembrance in Korthia.", ["rewardItems"] = { 187028 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2473, ["threshold"] = 10000 } } } },
[64267] = { ["id"] = 64267, ["name"] = "Mysterious Gifts from Ve'nari", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = { "emissary", "paragon" }, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64267 }, ["description"] = "I'm impressed by your sheer tenacity to survive while remaining somewhat useful, Maw Walker. You remind me of myself when I was much younger and naive. Take this and continue your work... somewhere less conspicuous.", ["objectivesText"] = "Speak with Ve'nari at Ve'nari 's Refuge in the Maw.", ["rewardItems"] = { 187029 }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard", ["worldSystems"] = { ["paragonReputation"] = { { ["factionID"] = 2474, ["threshold"] = 10000 } } } },
[64271] = { ["id"] = 64271, ["name"] = "A More Civilized Way", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64271 }, ["description"] = "Ah, $p. I have a matter to discuss with you. But not here. <Nadjia eyes the other denizens of Keeper's Respite suspiciously.> Meet me where the road enters Korthia from the Maw and I will explain.", ["objectivesText"] = "Meet Nadjia near the road leading into Korthia .", ["rewardItems"] = { 185073, 185074, 185075, 185076, 185077, 185078, 185079, 185080, 185107, 185108, 185109, 185110, 185111, 185112, 185113, 185114, 185115, 186201, 186205, 186206, 187329, 187330, 187331, 187467 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178795, ["x"] = 0.618, ["y"] = 0.252 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.618, ["y"] = 0.252 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64282] = { ["id"] = 64282, ["name"] = "Full of Surprises", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64282 }, ["description"] = "You continue to surprise me Maw Walker, your presence here is most unexpected! Since we are both here, I believe we should work together. The Jailer has a vault full of valuables, somewhere in this rift. Locate it for me, or bring it here to be opened and we'll share the wealth together!", ["objectivesText"] = "Locate Zovaal's Vault. Progress: Have you found the vault?", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 180817, 186731, 186969, 187113 }, ["starts"] = { { ["mapID"] = 1543, ["npcID"] = 179904, ["x"] = 0.447, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 179904, ["x"] = 0.447, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.447, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[64286] = { ["id"] = 64286, ["name"] = "Paragon of Death's Advance", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64286 }, ["description"] = "The call to action has been answered, yet again. Your efforts shall not go unnoticed. Let us see if we cannot find a fitting reward for your efforts.", ["objectivesText"] = "Speak with Duchess Mynx at Keeper's Respite in Korthia .", ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64287] = { ["id"] = 64287, ["name"] = "Paragon of The Archivists' Codex", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64287 }, ["description"] = "You have gone to great lengths to restore that which we cherish most dearly, Maw Walker. Meet me in my chamber when you are ready. We have one final matter to discuss.", ["objectivesText"] = "Speak with Archivist Roh-Suir at the Reliquary of Remembrance in Korthia.", ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64288] = { ["id"] = 64288, ["name"] = "Paragon of Ve'nari", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11400, ["mapID"] = 1543, ["storyline"] = { 64288 }, ["description"] = "Come, Maw Walker. Meet me at my refuge. We have one final matter to discuss. ...and do make sure you are not followed.", ["objectivesText"] = "Speak with Ve'nari at Ve'nari 's Refuge in The Maw .", ["ends"] = { { ["mapID"] = 1543, ["npcID"] = 162804, ["x"] = 0.468, ["y"] = 0.416 } }, ["coords"] = { ["mapID"] = 1543, ["source"] = "quest_giver", ["x"] = 0.468, ["y"] = 0.416 }, ["mapCandidates"] = { ["npc"] = { 1543 }, ["zone"] = { 11400 } }, ["questType"] = "standard" },
[64289] = { ["id"] = 64289, ["name"] = "Picking Up the Pieces", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64289 }, ["description"] = "Much was lost when Korthia was pulled into the Maw. Priceless relics were torn asunder. I have seen creatures carrying the remnants of these items. They must be recovered. Confront the Jailer's forces and search what remains of Korthia for these fragments of our once glorious vault.", ["objectivesText"] = "Recover 50 Relic Fragments from rare creatures and treasures throughout Korthia.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64290] = { ["id"] = 64290, ["name"] = "Collecting Research", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64290 }, ["description"] = "You have done well to collect these fragments. They will go a long way to restoring our archives. I can use what you have found to gather more research about what was lost within Korthia. Afterwards, it will be up to you to find more fragments and relics within Korthia to boost our archives.", ["objectivesText"] = "Speak with Archivist Roh-Suir to turn in any Korthian Relics for Cataloged Research. Progress: We thank you for your aid so far, Maw Walker.", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186664, 186665, 186716, 186734, 186735, 186741, 186742, 186750, 186751, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64292] = { ["id"] = 64292, ["name"] = "Maelie, The Wanderer", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64292 }, ["description"] = "I can't thank you enough for finding Maelie! You know, I think she's just a little bit more than I can handle. Would you mind watching over her? I think she's really taken a liking to you!", ["objectivesText"] = "Accept responsibility for Maelie.", ["rewardItems"] = { 184513, 186643 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179930, ["x"] = 0.606, ["y"] = 0.218 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179930, ["x"] = 0.606, ["y"] = 0.218 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.218 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64322] = { ["id"] = 64322, ["name"] = "Night Fae Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12858, ["mapID"] = 1670, ["storyline"] = { 64085, 64322 }, ["description"] = "Ardenweald is safer than it has been in quite some time, thanks to you. Your accomplishments have not gone unnoticed, even beyond the borders of Ardenweald. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12858 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1255, ["name"] = "Night Fae Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64323] = { ["id"] = 64323, ["name"] = "Kyrian Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 11012, ["mapID"] = 1533, ["storyline"] = { 64086, 64323 }, ["description"] = "Bastion is healing thanks to you, <name>. The path is clear. Your accomplishments have not gone unnoticed, even beyond the borders of Bastion. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["starts"] = { { ["mapID"] = 1533, ["npcID"] = 176100, ["x"] = 0.648, ["y"] = 0.202 } }, ["coords"] = { ["mapID"] = 1533, ["source"] = "quest_giver", ["x"] = 0.648, ["y"] = 0.202 }, ["mapCandidates"] = { ["npc"] = { 1533 }, ["zone"] = { 11012 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1253, ["name"] = "Kyrian Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64324] = { ["id"] = 64324, ["name"] = "Necrolord Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 12876, ["mapID"] = 1670, ["storyline"] = { 64084, 64324 }, ["description"] = "The might of the Necrolords grows thanks to you, <name>. Your accomplishments have not gone unnoticed, even beyond the borders of Maldraxxus. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 12876 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1254, ["name"] = "Necrolord Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
[64325] = { ["id"] = 64325, ["name"] = "Sinfall Veteran", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10986, ["mapID"] = 1670, ["storyline"] = { 64083, 64325 }, ["description"] = "Sinfall's influence grows thanks to your triumphs, <name>! Your accomplishments have not gone unnoticed, even beyond the borders of Revendreth. Tales of your victories have echoed through the halls of Oribos. Zo'sorg , the Master of Conflict, has requested a meeting with you in the Enclave. They have a keen interest in the art of war. I suggest you don't keep them waiting.", ["objectivesText"] = "Meet with Zo'sorg in the Enclave in Oribos.", ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10986 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1670, ["questLines"] = { { ["id"] = 1256, ["name"] = "Sinfall Combatant", ["orderIndex"] = 0, ["flags"] = 0 } } },
