[64519] = { ["id"] = 64519, ["name"] = "Lost Vaults", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64519 }, ["description"] = "I have finished my research on more relics that may still exist in Korthia. I believe they are still within our smaller vaults. With your help, I can recreate devices that are capable of repairing the entrances to these vaults. Take note of the echoes of relics that are still missing. Please review them so you know what to look for.", ["objectivesText"] = "Examine the missing relics within the Reliquary of Remembrance. Progress: Have you seen the missing relics?", ["rewardItems"] = { 185735, 185757, 185759, 185760, 185914, 185916, 185971, 186101, 186157, 186716, 186984, 187047, 187052, 187103, 187104, 187117, 187119, 187150, 187159, 187177, 187200, 187201, 187202, 187203, 187204, 187205, 187206, 187207, 187210, 187612, 187613, 187614 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64521] = { ["id"] = 64521, ["name"] = "Helsworn Battle Plans", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64521 }, ["description"] = "<These battle plans detail possible movements into Korthia , and include detailed reports of the defensive capabilities of the Death's Advance in the region. Duchess Mynx in Keeper's Respite would be able to spread this information rapidly to those who need it.>", ["objectivesText"] = "Deliver Helsworn Battle Plans to Duchess Mynx in Keeper's Respite. Provided item:", ["rewardItems"] = { 186201, 186205, 186206, 187275 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187275 } },
[64522] = { ["id"] = 64522, ["name"] = "Stolen Korthian Supplies", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64522 }, ["description"] = "<These supplies are marked with the seal of the Death's Advance, stolen from the Rift without being noticed. Duchess Mynx in Keeper's Respite would be very grateful to have this returned.>", ["objectivesText"] = "Deliver Stolen Korthian Supplies to Duchess Mynx in Keeper's Respite. Provided item:", ["rewardItems"] = { 187276, 187551 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179321, ["x"] = 0.634, ["y"] = 0.235 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.634, ["y"] = 0.235 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187276 } },
[64526] = { ["id"] = 64526, ["name"] = "Mysterious Rifts", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64526 }, ["description"] = "Thank you so much for your aid, <name>. I have uncovered more relics from the codex that remain intact. The key to finding these relics rests within the strange rifts within Korthia. I can now craft a way for you to enter these rifts, in order to gain access to these missing relics. As before, take note of the echoes to understand what these relics look like. Please be sure to examine them before you depart.", ["objectivesText"] = "Examine the missing relics within the Reliquary of Remembrance and purchase a Repaired Riftkey from Roh-Suir. Progress: Have you seen the missing relics?", ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[64527] = { ["id"] = 64527, ["name"] = "Observing the Chase", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 64527 }, ["description"] = "In our observations of your kind's conflict, we have noticed a high rate of escape among the prey. This is unadvantageous to our observation efforts. The Observer has acquired a tool we believe will improve your ability to force conflict. Before I give it to you, we ask that you prove your willingness to participate in such conflicts, so that we know we will receive a worthy return on this investment.", ["objectivesText"] = "Enable War Mode and slay 1 player within the world. Progress: Your hesitation to set out and hunt your prey is not promising, <name>...", ["rewardItems"] = { 163604 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "pvp" },
[64528] = { ["id"] = 64528, ["name"] = "Wilderling Saddle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64528 }, ["description"] = "<As you slipped off of the escaped wilderling's back, it shook its saddle off at your feet. It reluctantly left your side as the night fae led it back to Keeper's Respite. Reldorn in Keeper's Respite might know what to make of this gesture.>", ["objectivesText"] = "Deliver Wilderling Saddle to Reldorn in Keeper's Respite. Provided item:", ["rewardItems"] = { 186492, 187281 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 180340, ["x"] = 0.606, ["y"] = 0.21 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.606, ["y"] = 0.21 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187281 } },
[64529] = { ["id"] = 64529, ["name"] = "Intact Aquilon Core", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64529 }, ["description"] = "<The massive devourer was clutching this aquilon power core in its fist when it died, no doubt ripped from one of the destroyed aquilon around it. The power core appears to be almost entirely intact. Deos in Keeper's Respite would be able to help you locate an aquilon that you could power with it.>", ["objectivesText"] = "Deliver Intact Aquilon Core to Deos in Keeper's Respite. Provided item:", ["rewardItems"] = { 186483, 187282 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 180339, ["x"] = 0.62, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187282 } },
[64530] = { ["id"] = 64530, ["name"] = "Gravewing Crystal", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64530 }, ["description"] = "<This large crystal fragment shattered off of the massive construct's body. Flashes of energy crackle inside of it. The Stonewright in Keeper's Respite would be able to use this crystal to empower a gravewing for you.>", ["objectivesText"] = "Deliver Gravewing Crystal to the Stonewright in Keeper's Respite. Provided item:", ["rewardItems"] = { 186479, 187283 }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 180334, ["x"] = 0.62, ["y"] = 0.248 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.62, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["startItems"] = { 187283 } },
