[64562] = { ["id"] = 64562, ["name"] = "We Need a Healer - You!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64562 }, ["description"] = "There are too many wounded on the battlefield! Not everyone can 'bash it and make better.' We need more healers. You, take my device and get our wounded back on their feet!", ["objectivesText"] = "Restore 10 Wounded Covenant Allies in Seeker's Quorum.", ["rewardGold"] = 257400, ["rewardXP"] = 8165, ["rewardItems"] = { 184983, 184984, 184985, 184986, 184987, 184988, 184989, 184990, 185009, 185754, 186170, 186201, 186205, 186206, 187184, 187328, 187334, 187336, 187436, 187437, 187438, 187439, 187466, 187504 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 179216, ["x"] = 0.615, ["y"] = 0.24 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.615, ["y"] = 0.24 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2222, ["db2PoiUiMapID"] = 1961 },
[64567] = { ["id"] = 64567, ["name"] = "The Missing Scholar", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 64567 }, ["series"] = { 63731, 63732 }, ["description"] = "Ah, Maw Walker. Your return blesses us with great optimism, and much needed assistance. Several scholars remain unaccounted for. We believe they were last seen studying in the great court. We fear they may be lost, or worse, taken by those who seek to disrupt our way of life. Return to me when you have answers. May the path guide you.", ["objectivesText"] = "Locate Scholar Roh-Suir in Korthia.", ["rewardGold"] = 28090, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 177927, ["x"] = 0.628, ["y"] = 0.248 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178694, ["x"] = 0.59, ["y"] = 0.58 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.628, ["y"] = 0.248 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
