[64597] = { ["id"] = 64597, ["name"] = "Sanctum of Domination - Damned If You Don't", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13561, ["storyline"] = { 64597 }, ["description"] = "I feel Kel'Thuzad's presence in these halls. Claim shards from his phylactery and I'll be able to open a new pathway into his chambers. Four shards should be enough. We wouldn't want him coming back again would we?", ["objectivesText"] = "Collect 4 Phylactery Shards from Kel'Thuzad within the Sanctum of Domination on Normal Difficulty. Progress: Four shards should allow us to access his chamber.", ["rewardGold"] = 514800, ["rewardXP"] = 10205, ["rewardItems"] = { 187529 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13561 } }, ["questType"] = "raid" },
