[64607] = { ["id"] = 64607, ["name"] = "Tazavesh: A Hard Bargain", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13577, ["storyline"] = { 64607 }, ["description"] = "Ah, my work looks marvelous on you. You are the very image of legitimacy! And now that I've provided you with my talents, you shall provide me with yours. Seek out my business associate, Fe'tajid , at the Gilded Landing and offer him your assistance. I look forward to hearing of your success.", ["objectivesText"] = "Seek out Au'manal 's business associate and offer your assistance. Progress: Have you spoken with my associate?", ["rewardGold"] = 1029600, ["rewardXP"] = 16330, ["rewardItems"] = { 185953, 185954, 186637, 187552 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13577 } }, ["questType"] = "dungeon" },
