[64710] = { ["id"] = 64710, ["name"] = "Whispering Felflame Crystal", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "weekly", "repeatable" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 7502, ["storyline"] = { 64710 }, ["description"] = "The crystal pulses with an eerie, felfire green glow. Holding it, you hear faint echoes of guttural demonic voices. Although the words are jumbled, one is both decipherable and repeated often: Dalaran . Perhaps someone in the city floating over the Broken Isles can tell you more about this crystal and its purpose.", ["objectivesText"] = "Bring the Whispering Felflame Crystal to Aridormi in Dalaran , floating above the Broken Isles.", ["rewardGold"] = 280900, ["rewardXP"] = 200, ["rewardItems"] = { 129747, 129928, 133377, 133378, 143776, 167921, 167922, 187611, 225348 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 7502 } }, ["questType"] = "standard", ["startItems"] = { 187611 } },
[64717] = { ["id"] = 64717, ["name"] = "Materials of Creation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64717 }, ["description"] = "The large metal spheres that litter the landscape of Zereth Mortis are spent forges, discarded during the creation process. The spheres near the Forge of Afterlives contain trace amounts of materials unique to that location. I have modified my Forge-Tap to harvest those materials. Use it near the forges I have identified. The rare Eidolic Fragments have the greatest chance to be found on the largest of Progenitor Forges .", ["objectivesText"] = "Collect 10 Eidolic Fragments and 300 Minor Enigmet . Progress: Have you collected what we need?", ["rewardXP"] = 8165, ["rewardItems"] = { 187516, 187527, 187728, 187779, 187782, 187787, 187788, 187789, 187790, 187791, 187908, 188231, 189544, 190062, 190189, 190341, 190342, 190343, 190345, 190346, 190347, 190348, 190350, 190352, 190353, 190354, 190355, 190356, 190357, 190358, 190360, 190361, 190362, 190363, 190364, 190365, 190366, 190367, 190368, 190369, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192427 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64783] = { ["id"] = 64783, ["name"] = "Dance Dance Darkmoon", ["level"] = 1, ["requiredLevel"] = 1, ["faction"] = "both", ["categories"] = { "seasonal" }, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["event"] = "Darkmoon Faire", ["expansion"] = 8, ["zoneID"] = 5861, ["storyline"] = { 64783 }, ["description"] = "Simon says, \"Are you ready to dance?\" Step on in and show off your sweet moves, <class>. The rules are simple. Your opponent will perform a series of stylish moves, then you gotta match 'em. Earn enough accolades and then come back to ol' Simon. Just know that the more challenging the opponent, the more accolades you can earn. Simon says, \"Are you up for the challenge?\"", ["objectivesText"] = "Earn accolades by competing in the dance competition. Progress: Simon says, \"Show me what you got.\"", ["rewardItems"] = { 93724, 187689 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 5861 } }, ["questType"] = "standard" },
[64785] = { ["id"] = 64785, ["name"] = "Overgrown Story", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 64785 }, ["description"] = "Since our arrival here the Untamed Verdure has been a mystery waiting to be solved. The lush foliage of the area grows on everything as the creatures run amok without purpose. There could be valuable research data to be obtained from these creatures. Use a Containment Trap to subdue the elemental creatures. Once subdued, examine them for research data.", ["objectivesText"] = "Gaiagantic and 12 Geomentals examined for research data. Progress: Have you completed the research?", ["rewardXP"] = 8165, ["rewardItems"] = { 187684, 187700, 187908, 187909, 189544, 190189, 190341, 190344, 190345, 190348, 190349, 190351, 190352, 190355, 190359, 190360, 190363, 190367, 190368, 190371, 190605, 190632, 190633, 190634, 190635, 192424 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[64846] = { ["id"] = 64846, ["name"] = "Torghast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 64846 }, ["description"] = "Countless souls are tortured in the halls of Torghast. They need your help!", ["objectivesText"] = "Speak with Tal-Inara .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 176 },
[64849] = { ["id"] = 64849, ["name"] = "Tower of the Damned", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 64849 }, ["series"] = { 64850, 65035 }, ["description"] = "We know little of Torghast. However, Fatescribe Roh-Tahl claims there is work that must be done there. He believes there is a path for you to reach this place... and that someone there requires your aid. Do what you must to reach Torghast and aid anyone who is within.", ["objectivesText"] = "Travel to Torghast by jumping into the Ring of Transference, then find any entity there that needs your aid.", ["rewardGold"] = 30900, ["rewardXP"] = 850, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard" },
[64850] = { ["id"] = 64850, ["name"] = "Traversing Torghast", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "daily" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13400, ["mapID"] = 1911, ["storyline"] = { 64850 }, ["series"] = { 64849, 65035 }, ["description"] = "I've heard of you, the Maw Walker! You must know of me, the legendary Ve'nish . I am here to find great treasures within Torghast with the aid of my box. I can see you admiring it. Perhaps we can work together. Why don't you go into Torghast ahead of me to scout ahead? I shall even reward you for anything you discover within.", ["objectivesText"] = "Aid Ve'nish 's exploration of Torghast by completing a wing within Torghast. Use the wayfinder within Torghast to access different wings. Progress: How goes exploring the darkness of Torghast?", ["rewardGold"] = 52350, ["rewardXP"] = 13630, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 13400 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2453, ["db2PoiUiMapID"] = 1911 },
