[65031] = { ["id"] = 65031, ["name"] = "Battlegrounds", ["level"] = 50, ["requiredLevel"] = 50, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 10565, ["storyline"] = { 65031 }, ["description"] = "Champions of the Horde and Alliance continue to fight across countless battlegrounds. The brokers of Cartel Zo are paying combatants in order to observe their tactics. Will you answer the call and join the fray?", ["objectivesText"] = "Speak with Tal-Inara .", ["rewardGold"] = 25740, ["rewardXP"] = 850, ["rewardItems"] = { 254677, 268490 }, ["mapCandidates"] = { ["npc"] = {}, ["zone"] = { 10565 } }, ["questType"] = "standard", ["db2AdventureMapPoiID"] = 177 },
