[65072] = { ["id"] = 65072, ["name"] = "Not Safe for Work", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65072 }, ["description"] = "Rana's discovery of Progenitor relics at the Ageless Shards has created quite a stir among the Enlightened. These relics predate our earlier discoveries, and through them we may gain a deeper understanding of the workings of Zereth Mortis . Rana is collecting the relics, but I fear she is in danger. Agents of Cartel Xy have been spotted in the area, and will likely attempt to steal the relics. Please travel to the Ageless Shards, and help Rana collect the relics.", ["objectivesText"] = "Assist Rana in her search and collect 8 Progenitor Relics . Progress: Have you collected the Progenitor Relics ?", ["rewardXP"] = 8165, ["rewardItems"] = { 187944, 189544, 190189, 190343, 190345, 190346, 190352, 190353, 190358, 190361, 190366, 190368, 190369, 190370, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192426, 192427, 192440, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180630, ["x"] = 0.614, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.614, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65080] = { ["id"] = 65080, ["name"] = "Anima, Diverted", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 65080 }, ["description"] = "Now, for the moment of truth. Deposit any anima on your person at the Field Anima Diverter behind me. With any luck, you will not experience any side effects - loss of anima, loss of consciousness, loss of memory. That sort of thing.", ["objectivesText"] = "Deposit anima at the Field Anima Diverter in the Reliquary of Remembrance. Progress: Were you able to deposit your anima at the Field Anima Diverter?", ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
