[65142] = { ["id"] = 65142, ["name"] = "Portal Play", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65142 }, ["description"] = "To aid in my studies, I have used a network of travel portals to install monitoring devices all over Zereth Mortis . My devices have been quite successful at collecting large amounts of research data. It's time now to collect the data they have obtained. Use my portal network to locate my Prying Eyes and collect any data they have gathered. I'll give you a portal initiator as well, allowing you to re-enter the portal network, incase you find yourself lost!", ["objectivesText"] = "12 Prying Eye's research data collected. Progress: Have you collected all the data?", ["rewardXP"] = 8165, ["rewardItems"] = { 188170, 189544, 190189, 190343, 190344, 190345, 190348, 190349, 190351, 190352, 190353, 190355, 190356, 190358, 190359, 190360, 190363, 190364, 190366, 190367, 190368, 190371, 190372, 190605, 190633, 190634, 192422, 192423, 192424, 192428, 192430, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
