[65177] = { ["id"] = 65177, ["name"] = "Fruit of the Bloom", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65177 }, ["description"] = "We never know when something new may emerge from the confluence of creation and energy. The Catalyst Gardens have blossomed with a new crop of fruit. Their seeds may have special properties, and we wish to understand them. Please gather what you can find, and make the gardens safer for the future.", ["objectivesText"] = "Gather Catamelon Seeds and slay Overgrowth in the Catalyst Gardens. Progress: How can one understand what cannot be defined?", ["rewardItems"] = { 188230, 189544, 190189, 190342, 190343, 190344, 190346, 190347, 190348, 190350, 190351, 190354, 190355, 190356, 190357, 190358, 190359, 190360, 190362, 190363, 190364, 190365, 190366, 190367, 190370, 190371, 190372, 190605, 190633, 190634, 192422, 192423, 192424, 192428, 192429, 192430, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
