[65255] = { ["id"] = 65255, ["name"] = "Forcing the Cycle", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65255 }, ["description"] = "The forces of Zovaal have been spreading their malign influence into the natural life within Provis Fauna. With the rate of their corruption, attempting to cleanse them one by one would be ill advised. Instead, we can just return their energies into the systems of Zereth Mortis to be used to create new fauna. Use this orb, let it absorb their energy as they die, and then cleanse it once it has been charged.", ["objectivesText"] = "Charge and cleanse the Progenitor orb. Progress: Have you finished?", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190341, 190342, 190345, 190349, 190350, 190352, 190357, 190359, 190360, 190365, 190366, 190367, 190368, 190605, 190632, 190635, 192424 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65256] = { ["id"] = 65256, ["name"] = "Cluck, Cluck, Boom", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65256 }, ["description"] = "The endemic poultrids of Zereth Mortis have been influenced in an unseemly way by all these invaders. Use this device on the ones that have malfunctioned. Otherwise, they will do too much damage to the land.", ["objectivesText"] = "Use the Kinematic Micro-Life Recalibrator to \"recalibrate\" Malfunctioned Poultrids in the Great Veldt. Progress: These mysterious ways must be understood.", ["rewardItems"] = { 188697, 189436, 189544, 189853, 190189, 190341, 190342, 190343, 190348, 190349, 190353, 190355, 190358, 190363, 190364, 190366, 190369, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192426, 192429, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 177958, ["x"] = 0.342, ["y"] = 0.485 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.342, ["y"] = 0.485 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65259] = { ["id"] = 65259, ["name"] = "Heart of the Sepulcher", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65259 }, ["series"] = { 64798, 64812, 64813 }, ["description"] = "Soon after we stepped forth into the realms of Death, a message left behind by the Primus gave warning that the Jailer must not be allowed to reach the Sepulcher. Despite all our efforts, he has done so. Within the heart of that ancient place lie secrets the Jailer could use to dominate the entire cosmos. If he succeeds, everything we hold dear will be lost. Gather your allies, <name>. Claim victory for the Shadowlands... and for Azeroth.", ["objectivesText"] = "Defeat the Jailer in the Sepulcher of the First Ones .", ["rewardGold"] = 772200, ["rewardXP"] = 12250, ["rewardItems"] = { 189865 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181183, ["x"] = 0.35, ["y"] = 0.648 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.35, ["y"] = 0.648 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "raid" },
[65264] = { ["id"] = 65264, ["name"] = "Operation: Relocation", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65264 }, ["description"] = "Devourers have disrupted the avians nesting at Provis Esper. This may be our last chance to examine them before they become tainted, like the others. Capture several of the avians at Provis Esper and return them to Pilgrim Arizh for relocation and study. Deal with any problems that get in your way.", ["objectivesText"] = "Deliver 8 wrangled Wild Proto Avians and slay 6 Soul-Parched Gorgers and 2 Reality Breachers in Provis Esper.", ["rewardItems"] = { 189544, 189554, 190189, 190342, 190345, 190346, 190347, 190348, 190350, 190352, 190353, 190354, 190355, 190356, 190357, 190360, 190361, 190362, 190363, 190364, 190365, 190368, 190369, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192425, 192428, 192429, 192430, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65265] = { ["id"] = 65265, ["name"] = "Buried Remnants", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65265 }, ["description"] = "Much has been lost to the invading forces, those that came with destruction in their hearts. We cannot preserve this land as the First Ones intended if the Mawsworn are allowed to pulverize all remnants of their knowledge. See what you can recover from the sands of Provis Strata.", ["objectivesText"] = "Recover Strange Artifacts from Provis Strata. Progress: What was before, will be again.", ["rewardXP"] = 8165, ["rewardItems"] = { 188738, 189544, 190189, 190341, 190342, 190344, 190345, 190346, 190350, 190352, 190353, 190354, 190356, 190357, 190360, 190361, 190364, 190365, 190368, 190369, 190370, 190372, 190605, 190632, 190633, 190634, 190635, 192423, 192425, 192450 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65266] = { ["id"] = 65266, ["name"] = "Lost Research", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = { "repeatable", "weekly" }, ["sharable"] = false, ["expansion"] = 8, ["zoneID"] = 13570, ["mapID"] = 1961, ["storyline"] = { 65266 }, ["description"] = "We have uncovered a promising source of Korthian research. Previous Archivists hid knowledge within repositories that were then placed within the rift. I fear that the repositories are no longer safe and that shades of that realm will consume them. It is imperative that we secure this research before it is lost forever. Use a Repaired Riftkey to enter the Korthia Rift. Recover the Korthian Repositories.", ["objectivesText"] = "Recover Korthian Repositories from the Korthia Rift for Archivist Roh-Suir . Progress: The archive would be lost without you, Maw Walker.", ["rewardItems"] = { 186731, 188740 }, ["starts"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["ends"] = { { ["mapID"] = 1961, ["npcID"] = 178257, ["x"] = 0.6205, ["y"] = 0.2215 } }, ["coords"] = { ["mapID"] = 1961, ["source"] = "quest_giver", ["x"] = 0.6205, ["y"] = 0.2215 }, ["mapCandidates"] = { ["npc"] = { 1961 }, ["zone"] = { 13570 } }, ["questType"] = "standard" },
[65268] = { ["id"] = 65268, ["name"] = "Bzzzzt!", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65268 }, ["description"] = "The vespoids of the region use debris in the area to form the core of their nests. While this is normally something we'd allow them to naturally do, they've started taking some of the relics we were studying. I have a device that should hopefully allow for the removal of such relics from their hives without damaging the core structure. Use it to retrieve these relics.", ["objectivesText"] = "Use the enlightened broker device to remove the progenitor debris from vespoid nests .", ["rewardXP"] = 8165, ["rewardItems"] = { 188788, 189544, 190189, 190342, 190345, 190350, 190352, 190357, 190360, 190365, 190368, 190370, 190605, 190632, 190633, 190634, 190635, 192424 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65269] = { ["id"] = 65269, ["name"] = "Obvious Plant", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65269 }, ["description"] = "The situation in the Catalyst Gardens is troubling. But most troubling of all is that we do not know more. If we had an understanding of the changing levels of energy emitted by the Creation Catalyst, we could make better decisions as to how to proceed. Take these sensors. Place them below the catalyst at the locations marked upon your map.", ["objectivesText"] = "Place the Progenitor Magic Sensors in the Catalyst Gardens. Progress: Were you able to place the sensors?", ["rewardItems"] = { 189544, 190189, 190342, 190344, 190347, 190348, 190350, 190351, 190354, 190355, 190357, 190362, 190363, 190365, 190370, 190371, 190632, 190633, 190634, 190635 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 181179, ["x"] = 0.612, ["y"] = 0.515 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.612, ["y"] = 0.515 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65325] = { ["id"] = 65325, ["name"] = "Motes of Knowledge", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65325 }, ["description"] = "The creatures of Untamed Verdure are ingesting everything in sight. They have consumed our Compilation Nodule , and the Composition Motes needed for compilation. We Jiro require these resources. This area is too hazardous for unprotected Jiro operation. Please help us reclaim our resources. Mai Obet will assist you.", ["objectivesText"] = "1 Compilation Nodule and 10 Composition Motes recovered. Progress: Have you recovered our resources?", ["rewardXP"] = 8165, ["rewardItems"] = { 189438, 189439, 189544, 190058, 190189, 190341, 190343, 190344, 190345, 190346, 190348, 190351, 190352, 190353, 190354, 190355, 190356, 190358, 190359, 190360, 190361, 190363, 190364, 190366, 190368, 190369, 190371, 190372, 190605, 190632, 190633, 190634, 192423, 192424, 192425, 192427, 192429, 192430, 192440, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65326] = { ["id"] = 65326, ["name"] = "Circle of Strife", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65326 }, ["description"] = "Automa need assistance to operate properly. We fulfill this purpose, but outsiders have caused too many interruptions. We cannot properly address them all. Please assist Mai Obet in inspecting and reviewing the performance of the automa.", ["objectivesText"] = "Inspect 10 Automa Constructors in Provis Flora. Progress: Do the automa meet expectations?", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190343, 190344, 190347, 190348, 190349, 190351, 190354, 190355, 190358, 190359, 190362, 190363, 190364, 190366, 190367, 190370, 190371, 190605, 190632, 190633, 190634, 190635, 192423, 192424, 192426, 192427, 192429, 192440, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
