[65362] = { ["id"] = 65362, ["name"] = "Not of the Body", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65362 }, ["description"] = "Enemies of Zereth Mortis wear the guise of productive automa. They do not complete any desired tasks. Scan the automa to reveal enemy threats, then eliminate them. Mai Obet shall assist.", ["objectivesText"] = "6 Dreadlord Infiltrators slain", ["rewardGold"] = 210000, ["rewardXP"] = 8165, ["rewardItems"] = { 35818, 35820, 35821, 35822, 74577, 74578, 74579, 131910, 155254, 155255, 155256, 155257, 161139, 181645, 181647, 181648, 181649, 181650, 181652, 181654, 181655, 181668, 181670, 181677, 181680, 181681, 181686, 184195, 184305, 184772, 184773, 184774, 184775, 184776, 189449, 189544, 189704, 190189, 190341, 190345, 190346, 190347, 190348, 190349, 190352, 190353, 190354, 190355, 190356, 190360, 190361, 190362, 190363, 190364, 190367, 190368, 190369, 190370, 190371, 190372, 190605, 190632, 190633, 190634, 192423, 211279, 237812 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180289, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
[65363] = { ["id"] = 65363, ["name"] = "Dangerous State", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65363 }, ["description"] = "Enemies have attacked the jiro and severed them from the circle. The jiro are no longer stable. They are a danger to the order of things. They must be removed.", ["objectivesText"] = "Leashkeeper Helzid and 12 Dominated Jiro slain Progress: Have you removed the threat?", ["rewardXP"] = 8165, ["rewardItems"] = { 189544, 190189, 190342, 190343, 190346, 190348, 190350, 190353, 190355, 190357, 190358, 190361, 190363, 190365, 190366, 190369, 190370, 190371, 190605, 190632, 190633, 190634, 192423, 192424, 192425, 192427, 192428, 192429, 192430, 192440, 192449, 192450, 192451 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 184434, ["x"] = 0.584, ["y"] = 0.498 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.584, ["y"] = 0.498 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard", ["db2PoiMapID"] = 2374, ["db2PoiUiMapID"] = 1970 },
