[65731] = { ["id"] = 65731, ["name"] = "The Burrowed Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65731 }, ["objectivesText"] = "Progress: Hmmmmm... My friend, I am nearly out of ideas. We have exhausted most of Zereth Mortis ' supply of tempting flavors. I have spent hours pondering the things I find enticing. Only one thing outside of Zereth Mortis brushes my memory: Sweet organic melons . My dear friend once sold them just inside the great Tazavesh marketplace. Is it possible they are still there? You will need to gain access to the city, if you have not already.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
[65732] = { ["id"] = 65732, ["name"] = "The Patient Bufonid", ["level"] = 60, ["requiredLevel"] = 60, ["faction"] = "both", ["categories"] = {}, ["flags"] = {}, ["sharable"] = true, ["expansion"] = 8, ["zoneID"] = 13536, ["mapID"] = 1970, ["storyline"] = { 65732 }, ["description"] = "Look, another magnificent creature of Zereth Mortis ! By the glint in its eye, I would say it was playing along the whole time. Patience delights. Bud is pleased. Excellent work, Maw Walker.", ["rewardGold"] = 128700, ["rewardXP"] = 4085, ["rewardItems"] = { 172053, 173037, 173202, 187171, 187704, 188808, 190852, 190880 }, ["starts"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["ends"] = { { ["mapID"] = 1970, ["npcID"] = 180950, ["x"] = 0.344, ["y"] = 0.658 } }, ["coords"] = { ["mapID"] = 1970, ["source"] = "quest_giver", ["x"] = 0.344, ["y"] = 0.658 }, ["mapCandidates"] = { ["npc"] = { 1970 }, ["zone"] = { 13536 } }, ["questType"] = "standard" },
